            if showContactPreview, let contact = contactPreviewData {
                ContactPreviewCard(contact: contact, isPresented: $showContactPreview)
                    .transition(.opacity.combined(with: .scale(scale: 0.95)))
            }

            // AI Extension Suggestions Overlay
            if showAIExtensionSuggestions {
                ZStack {
                    // Dim background
                    Color.black.opacity(0.3)
                        .ignoresSafeArea()
                        .onTapGesture {
                            withAnimation(.spring(response: 0.3)) {
                                showAIExtensionSuggestions = false
                            }
                        }

                    // AI Suggestions View
                    AIModeView(
                        currentContext: $currentContext,
                        isVisible: $showAIExtensionSuggestions
                    )
                    .transition(.opacity.combined(with: .scale(scale: 0.95)))
                }
            }

        }
        .onReceive(adapterManager.$pendingApproval) { pending in
            DispatchQueue.main.async {
                if let pending {
                    openAdapterApprovalWindow(request: pending)
                } else {
                    AdapterApprovalWindowHost.close()
                }
            }
        }
        .onReceive(TerminalAIBridge.shared.$pendingApproval) { pending in
            if let pending = pending {
                let risk = pending.classification.riskLevel.displayName
                let approvalMsg = AIChatMessage(
                    role: .approval,
                    content: pending.command,
                    structuredData: "\(pending.purpose)|||/\(risk)"
                )
                if l2TargetApp != nil || showContextInDock {
                    // L2 app scope active — show inline in L2 chat
                    l2ChatMessages.append(approvalMsg)
                } else if activeSmartQueryKey != nil {
                    // Legacy panel fallback
                    remPanelChatMessages.append(approvalMsg)
                } else {
                    openCommandApprovalWindow(pending: pending)
                }
            } else {
                // Close popup if one was open (for non-panel contexts)
                CommandApprovalWindowHost.close()
            }
        }
    }

    private func openCommandApprovalWindow(pending: TerminalAIBridge.PendingCommand) {
        CommandApprovalWindowHost.close()
        let view = CommandApprovalView(
            command: pending.command,
            classification: pending.classification,
            purpose: pending.purpose,
            onApprove: { approvedCommand in
                TerminalAIBridge.shared.approveCommand(approvedCommand)
            },
            onDeny: {
                TerminalAIBridge.shared.denyCommand()
            }
        )
        let controller = NSHostingController(rootView: view)
        let win = NSWindow(contentViewController: controller)
        win.title = "Terminal Command Approval"
        win.styleMask = [.titled, .closable]
        win.level = .floating
        let isCritical = pending.classification.riskLevel == .critical
        win.setContentSize(NSSize(width: 520, height: isCritical ? 460 : 410))
        win.isReleasedWhenClosed = false
        win.center()
        win.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
        CommandApprovalWindowHost.window = win
        // When the user closes via the X button, treat as deny
        win.delegate = CommandApprovalWindowHost.shared
    }

    private func openAdapterApprovalWindow(request: AdapterActionRequest) {
        AdapterApprovalWindowHost.close()

        let size = NSSize(width: 460, height: 252)
        let view = AdapterApprovalPopupView(request: request)
        let controller = NSHostingController(rootView: view)
        let panel = AdapterApprovalPanel(
            contentRect: NSRect(origin: .zero, size: size),
            styleMask: [.borderless, .fullSizeContentView],
            backing: .buffered,
            defer: false
        )

        panel.contentViewController = controller
        panel.level = .floating
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.hasShadow = true
        panel.hidesOnDeactivate = false
        panel.isMovableByWindowBackground = true
        panel.collectionBehavior = [.fullScreenAuxiliary, .moveToActiveSpace, .transient]

        positionAdapterApprovalPanel(panel, size: size)

        AdapterApprovalWindowHost.shared.onClose = request.onDeny
        AdapterApprovalWindowHost.window = panel
        panel.delegate = AdapterApprovalWindowHost.shared
        panel.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
    }

    private func positionAdapterApprovalPanel(_ panel: NSPanel, size: NSSize) {
        if let launcherWindow = AppDelegate.shared?.launcherWindow, launcherWindow.isVisible {
            let screenFrame = (launcherWindow.screen ?? NSScreen.main)?.visibleFrame
                ?? NSScreen.main?.visibleFrame
                ?? NSRect(origin: .zero, size: size)
            let margin: CGFloat = 16
            let verticalGap: CGFloat = 18

            var x = launcherWindow.frame.midX - (size.width / 2)
            var y = launcherWindow.frame.maxY + verticalGap

            x = min(max(x, screenFrame.minX + margin), screenFrame.maxX - size.width - margin)

            if y + size.height > screenFrame.maxY - margin {
                y = max(
                    screenFrame.minY + margin,
                    launcherWindow.frame.minY - size.height - verticalGap
                )
            }

            panel.setFrame(NSRect(x: x, y: y, width: size.width, height: size.height), display: false)
            return
        }

        panel.center()
    }

