    // ── L2 Panel Quick Action Pills ─────────────────────────────────────────
    /// Quick actions from all user-created panels, shown as floating pills in L2 mode.
    /// Groups by panel key and shows up to 6 most recently used.
    private var l2PanelQuickActions: [AppShortcut] {
        let allKeys = AppPanelChatStore.shared.allPanelKeys()
        let frontApp = frontmostAppName.lowercased()
        // Prioritise panels matching the current frontmost app, then rest
        var keys = allKeys.filter {
            $0.localizedCaseInsensitiveContains(frontApp) && !frontApp.isEmpty
        }
        keys += allKeys.filter {
            !($0.localizedCaseInsensitiveContains(frontApp) && !frontApp.isEmpty)
        }
        // Gather shortcuts for these panel keys (max 8)
        var result: [AppShortcut] = []
        for key in keys {
            let shortcuts = settings.shortcuts(for: key)
            result.append(contentsOf: shortcuts)
            if result.count >= 8 { break }
        }
        return Array(result.prefix(8))
    }

    @ViewBuilder
    private var l2QuickActionPills: some View {
        let pills = l2PanelQuickActions
        if !pills.isEmpty {
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 6) {
                    ForEach(pills) { sc in
                        Button {
                            executeAppShortcut(sc)
                        } label: {
                            HStack(spacing: 5) {
                                Image(systemName: sc.iconName)
                                    .font(.system(size: 10, weight: .semibold))
                                Text(sc.name)
                                    .font(.system(size: 11, weight: .medium))
                                    .lineLimit(1)
                            }
                            .padding(.horizontal, 10)
                            .padding(.vertical, 5)
                            .background(.regularMaterial, in: Capsule())
                            .overlay(Capsule().strokeBorder(.primary.opacity(0.07), lineWidth: 0.5))
                        }
                        .buttonStyle(.plain)
                    }
                }
                .padding(.horizontal, 2)
            }
        }
    }

    /// L2Extensions from L2ExtensionManager that match the current frontmost app.
    private var frontmostAppL2Extensions: [L2Extension] {
        let appName: String
        let bundleID: String
        if !frontmostAppName.isEmpty {
            appName = frontmostAppName
            bundleID = frontmostAppBundleID
        } else if let ws = NSWorkspace.shared.frontmostApplication,
            let name = ws.localizedName,
            !(ws.bundleIdentifier ?? "").contains("ILauncher")
        {
            appName = name
            bundleID = ws.bundleIdentifier ?? ""
        } else {
            return []
        }
        return l2Extensions(forAppName: appName, bundleID: bundleID)
    }

    private func l2Extensions(forAppName appName: String, bundleID: String) -> [L2Extension] {
        let appLower = appName.lowercased()
        let bundleLower = bundleID.lowercased()
        return L2ExtensionManager.shared.extensions.filter { ext in
            guard !ext.contextApps.isEmpty else { return false }
            // Check ALL contextApps entries (app name OR bundle ID match)
            return ext.contextApps.contains { ctx in
                let ctxLower = ctx.lowercased()
                return ctxLower == appLower
                    || ctxLower.contains(appLower)
                    || appLower.contains(ctxLower)
                    || (!bundleLower.isEmpty
                        && (ctxLower == bundleLower || ctxLower.contains(bundleLower)))
            }
        }
    }

    private func scopedContextExtensions(query: String, appName: String?, bundleId: String?)
        -> [ExtensionDiscoveryResult]
    {
        guard settings.enableContextAIExtensions else { return [] }

        let trimmedQuery = query.trimmingCharacters(in: .whitespacesAndNewlines)
        let includeSelectionContext =
            !isL2ContextActive && AppDelegate.shared?.isDockContextMode != true

        let contextFiles: [URL] = {
            guard includeSelectionContext else { return [] }
            switch currentContext {
            case .filesSelected(let urls): return urls
            default:
                return axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
            }
        }()
        let selectedText: String? = {
            guard includeSelectionContext else { return nil }
            switch currentContext {
            case .textSelected(let t): return t.isEmpty ? nil : t
            default: return nil
            }
        }()

        let resolvedAppName: String? = {
            if let appName, !appName.isEmpty { return appName }
            if let bundleId,
                let app = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == bundleId
                })
            {
                return app.localizedName
            }
            return nil
        }()

        guard resolvedAppName != nil || !contextFiles.isEmpty || selectedText != nil else {
            return []
        }

        let results = LayeredExtensionManager.shared.discoverExtensions(
            for: trimmedQuery,
            selectedFiles: contextFiles,
            selectedText: selectedText,
            frontmostApp: resolvedAppName,
            layer: .l2_context
        )

        return Array(results.prefix(6))
    }

    // MARK: - Context Dock Filter (type to find actions)

    private struct L2FilteredItem {
        let id: String
        let icon: String
        let name: String
        let isExtension: Bool
    }

    private var l2FilteredContextActions: [L2FilteredItem] {
        let q = searchText.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return [] }
        let appKey = activeSmartQueryKey ?? settings.autoDetectedAppKey ?? ""
        var results: [L2FilteredItem] = []
        for sc in settings.shortcuts(for: appKey) where sc.name.lowercased().contains(q) {
            results.append(
                L2FilteredItem(
                    id: "sc_\(sc.id)", icon: sc.iconName, name: sc.name, isExtension: false))
        }
        for ext in appPillScriptExtensions(for: appKey, query: q)
        where ext.toolName.lowercased().contains(q) || ext.aiHint.lowercased().contains(q) {
            let icon = ext.scriptLanguage?.systemImage ?? "terminal"
            results.append(
                L2FilteredItem(
                    id: "usr_ext_\(ext.id.uuidString)",
                    icon: icon,
                    name: ext.toolName.replacingOccurrences(of: "-", with: " ").capitalized,
                    isExtension: false
                )
            )
        }
        for tool in frontmostAppL2Extensions
        where tool.displayName.lowercased().contains(q) || tool.toolName.lowercased().contains(q) {
            results.append(
                L2FilteredItem(
                    id: "ext_\(tool.toolName)", icon: tool.icon, name: tool.displayName,
                    isExtension: true))
        }
        return results
    }

    private func executeL2FilteredItem(_ item: L2FilteredItem) {
        if item.isExtension {
            let toolName = String(item.id.dropFirst(4))  // strip "ext_"
            guard let tool = frontmostAppL2Extensions.first(where: { $0.toolName == toolName })
            else { return }
            l2ChatMessages.append(AIChatMessage(role: .user, content: tool.displayName))
            l2IsLoading = true
            Task {
                let (success, output) = await L2ExtensionManager.shared.execute(
                    toolName: tool.toolName, arguments: [:])
                await MainActor.run {
                    let content =
                        success
                        ? (output.isEmpty ? "✅ \(tool.displayName) done." : output)
                        : "❌ \(tool.displayName) failed: \(output)"
                    l2ChatMessages.append(AIChatMessage(role: .assistant, content: content))
                    l2IsLoading = false
                }
            }
        } else {
            let scIdStr = String(item.id.dropFirst(3))  // strip "sc_"
            let appKey = activeSmartQueryKey ?? settings.autoDetectedAppKey ?? ""
            if item.id.hasPrefix("usr_ext_"),
               let ext = appPillScriptExtensions(for: appKey, query: searchText)
                    .first(where: { $0.id.uuidString == String(item.id.dropFirst("usr_ext_".count)) }) {
                executeAppToolExtension(ext, launchQuery: searchText)
            } else if let sc = settings.shortcuts(for: appKey).first(where: { $0.id.uuidString == scIdStr }
            ) {
                executeAppShortcut(sc)
            }
        }
        searchText = ""
    }

    // MARK: - Unified dock pill list (drives both rendering and keyboard navigation)

    /// A lightweight token for each pill currently visible in the dock.
    struct DockPill: Identifiable {
        let id: String
        let name: String
        let icon: String
        let accentColorName: String?
        let badge: String?  // keyboard shortcut display
        let execute: () -> Void
        var isSeparator: Bool = false
        var isFavourited: Bool = false
        var menuItemName: String = ""
        var sourceBundleId: String = ""
        var sourceAppName: String = ""
        var isShareAction: Bool = false
        var rankingKind: String = ""
        var trackingIdentifier: String = ""
        var searchTerms: [String] = []
        var rankingScore: Double = 0
        var menuItemImage: NSImage? = nil  // native icon read from AX kAXImageAttribute
    }

    private struct InstalledAppMenuTarget {
        let appName: String
        let bundleId: String
        let appPath: String
        let actionQuery: String
        let matchedAlias: String
    }

    private struct DockScopeResolution {
        let scopedBundleId: String
        let scopedAppName: String
        let scopedSearchQuery: String
        let isExplicitAppScope: Bool
        let isGlobalScope: Bool
    }

    private struct FinderSemanticMatch {
        let path: String
        let title: String
        let subtitle: String
        let isDirectory: Bool
        let score: Double
        let source: String
        let searchTerms: [String]
    }

    // MARK: - Finder selected-file context pills

    /// When Finder is frontmost and files are selected, generate instant-action pills
    /// for those files so they appear *before* the generic adapter pills.
    func buildFinderFilePills(query q: String) -> [DockPill] {
        guard axContext.bundleId == "com.apple.finder",
            !axContext.selectedFilePaths.isEmpty
        else { return [] }
        let paths = axContext.selectedFilePaths
        let count = paths.count
        let first = paths[0]
        let firstName = URL(fileURLWithPath: first).lastPathComponent
        let label = count == 1 ? firstName : "\(count) items selected"
        let ext = URL(fileURLWithPath: first).pathExtension.lowercased()

        // Pills that always make sense for any selection
        var pills: [DockPill] = []

        func add(
            _ id: String, _ name: String, _ icon: String, _ color: String,
            _ action: @escaping () -> Void
        ) {
            if !q.isEmpty && !name.lowercased().contains(q) { return }
            pills.append(
                DockPill(
                    id: "finder-ctx-\(id)", name: name, icon: icon,
                    accentColorName: color, badge: label, execute: action))
        }

        add("ql", "Quick Look", "eye", "blue") {
            NSWorkspace.shared.activateFileViewerSelecting(
                paths.compactMap { URL(fileURLWithPath: $0) })
        }
        add("open", "Open", "arrow.up.right.square", "blue") {
            for p in paths { NSWorkspace.shared.open(URL(fileURLWithPath: p)) }
        }
        add("reveal", "Show in Finder", "folder", "gray") {
            NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: first)])
        }
        add("copypath", "Copy Path", "doc.on.clipboard", "teal") {
            let pb = NSPasteboard.general
            pb.clearContents()
            pb.setString(paths.joined(separator: "\n"), forType: .string)
        }
        add("share", "Share…", "square.and.arrow.up", "blue") {
            let urls = paths.map { URL(fileURLWithPath: $0) }
            presentSharingPicker(items: urls)
        }
        add("trash", "Move to Trash", "trash", "red") {
            let urls = paths.map { URL(fileURLWithPath: $0) }
            try? FileManager.default.trashItem(at: urls[0], resultingItemURL: nil)
            if urls.count > 1 {
                for u in urls.dropFirst() {
                    try? FileManager.default.trashItem(at: u, resultingItemURL: nil)
                }
            }
        }

        // Extension-aware pills
        let imageExts = ["jpg", "jpeg", "png", "gif", "heic", "tiff", "bmp", "webp", "svg"]
        let videoExts = ["mp4", "mov", "m4v", "avi", "mkv", "wmv"]
        let archiveExts = ["zip", "tar", "gz", "bz2", "xz", "7z", "rar"]
        let textExts = [
            "txt", "md", "markdown", "rtf", "csv", "json", "xml", "yaml", "yml", "toml", "log",
        ]
        let pdfExts = ["pdf"]

        func openInApp(_ fileURL: URL, appName: String) {
            let proc = Process()
            proc.executableURL = URL(fileURLWithPath: "/usr/bin/open")
            proc.arguments = ["-a", appName, fileURL.path]
            try? proc.run()
        }

        if imageExts.contains(ext) {
            add("preview-img", "Open in Preview", "photo", "purple") {
                openInApp(URL(fileURLWithPath: first), appName: "Preview")
            }
        }
        if videoExts.contains(ext) {
            add("play", "Play in QuickTime", "play.circle", "red") {
                openInApp(URL(fileURLWithPath: first), appName: "QuickTime Player")
            }
        }
        if pdfExts.contains(ext) {
            add("preview-pdf", "Open in Preview", "doc.richtext", "red") {
                openInApp(URL(fileURLWithPath: first), appName: "Preview")
            }
        }
        if archiveExts.contains(ext) {
            add("unzip", "Unarchive", "archivebox.circle", "yellow") {
                let dir = URL(fileURLWithPath: first).deletingLastPathComponent().path
                let proc = Process()
                proc.executableURL = URL(fileURLWithPath: "/usr/bin/unzip")
                proc.arguments = ["-o", first, "-d", dir]
                try? proc.run()
            }
        }
        if textExts.contains(ext) {
            add("texteditor", "Open in TextEdit", "doc.plaintext", "gray") {
                openInApp(URL(fileURLWithPath: first), appName: "TextEdit")
            }
        }
        return pills
    }

    private func buildFinderSelectionMenuPills(query q: String, excludingTitles: Set<String>) -> [DockPill] {
        guard axContext.bundleId == "com.apple.finder",
            !axContext.selectedFilePaths.isEmpty
        else { return [] }

        let limit = q.isEmpty ? 12 : 10
        let items = FileContextOverlayController.shared.finderMenuResults(query: q, limit: limit)

        func icon(for item: AXMenuItem) -> String {
            let title = item.title.lowercased()
            if title.contains("open with") { return "chevron.right.square" }
            if title.contains("open") { return "arrow.up.right.square" }
            if title.contains("bin") || title.contains("trash") { return "trash" }
            if title.contains("info") { return "info.circle" }
            if title.contains("rename") { return "pencil" }
            if title.contains("compress") || title.contains("archive") { return "archivebox" }
            if title.contains("duplicate") { return "plus.square.on.square" }
            if title.contains("alias") { return "arrow.triangle.branch" }
            if title.contains("quick look") { return "eye" }
            if title.contains("copy") { return "doc.on.doc" }
            if title.contains("share") { return "square.and.arrow.up" }
            if title.contains("tag") { return "tag" }
            if title.contains("service") { return "gearshape.2" }
            if title.contains("quick action") { return "bolt" }
            return "menubar.rectangle"
        }

        var pills: [DockPill] = []
        for item in items {
            let normalizedTitle = normalizedDockPillText(item.title)
            guard !excludingTitles.contains(normalizedTitle) else { continue }

            let path = item.path
            let sourcePID = item.sourcePID
            let shortcutChar = item.shortcutChar
            let shortcutModifiers = item.shortcutModifiers
            let badge = item.shortcutDisplay   // parent menu name dropped — use shortcut only
            let isShareItem = item.title.lowercased().hasPrefix("share")

            let menuImg = item.image
            var pill = DockPill(
                id: "finder-menu-\(item.id)",
                name: item.title,
                icon: isShareItem ? "square.and.arrow.up" : icon(for: item),
                accentColorName: isShareItem ? "blue" : "gray",
                badge: badge,
                execute: {
                    if isShareItem {
                        showShareSheetForContext()
                        return
                    }

                    guard sourcePID != 0 else { return }
                    executeDockMenuAction(
                        sourcePID: sourcePID,
                        path: path,
                        shortcutChar: shortcutChar,
                        shortcutModifiers: shortcutModifiers
                    )
                }
            )
            pill.menuItemImage = menuImg
            pill.isShareAction = isShareItem
            pill.menuItemName = item.title
            pill.sourceBundleId = "com.apple.finder"
            pill.sourceAppName = "Finder"
            pill.rankingKind = "finderMenu"
            pill.trackingIdentifier =
                "finder-menu:\(path.joined(separator: " > ").lowercased())"
            pill.searchTerms = item.path + ["finder", "files", "selection"]
            pills.append(pill)
        }

        return pills
    }

    // MARK: - Cross-app / clipboard / session pill helpers

    /// Pills for apps that can receive the current context (URL, text, file).
    /// Delegates to CrossAppRouter for capability-aware, content-type routing.
    func buildCrossAppPills(query q: String) -> [DockPill] {
        guard settings.crossAppPills else { return [] }
        let runningIds = Set(
            NSWorkspace.shared.runningApplications
                .filter { $0.activationPolicy == .regular }
                .compactMap(\.bundleIdentifier)
        )
        let routed = CrossAppRouter.shared.buildPills(
            context: axContext,
            runningBundleIds: runningIds,
            query: q
        )
        return routed.compactMap { pill in
            let normalizedQuery = q.lowercased()
            let searchable = "\(pill.label.lowercased()) \(pill.appName.lowercased())"
            if !q.isEmpty && !searchable.contains(normalizedQuery) { return nil }
            var dockPill = DockPill(
                id: "cross-\(pill.bundleId)",
                name: pill.label,
                icon: pill.icon,
                accentColorName: pill.badgeColor,
                badge: nil,
                execute: pill.action
            )
            dockPill.sourceBundleId = pill.bundleId
            dockPill.sourceAppName = pill.appName
            dockPill.rankingKind = "crossApp"
            dockPill.trackingIdentifier = "cross:\(pill.bundleId):\(normalizedDockPillText(pill.label))"
            dockPill.searchTerms = [pill.appName, pill.label]
            return dockPill
        }
    }

    /// Pills derived from the current clipboard content.
    func buildClipboardPills(query q: String) -> [DockPill] {
        guard settings.clipboardAwarePills else { return [] }
        let pb = NSPasteboard.general
        var pills: [DockPill] = []

        // URL on clipboard
        if let urlStr = pb.string(forType: .string),
            let url = URL(string: urlStr.trimmingCharacters(in: .whitespacesAndNewlines)),
            url.scheme?.hasPrefix("http") == true
        {
            let label = "Open Clipboard URL"
            if q.isEmpty || label.lowercased().contains(q) || "clipboard".contains(q) {
                pills.append(
                    DockPill(
                        id: "clip-url", name: label, icon: "link",
                        accentColorName: "blue", badge: "Clipboard",
                        execute: { NSWorkspace.shared.open(url) }))
            }
            let label2 = "Copy Clipboard URL"
            if q.isEmpty || label2.lowercased().contains(q) {
                pills.append(
                    DockPill(
                        id: "clip-copy-url", name: label2, icon: "doc.on.clipboard",
                        accentColorName: "blue", badge: "Clipboard",
                        execute: {
                            let p = NSPasteboard.general
                            p.clearContents()
                            p.setString(urlStr, forType: .string)
                        }))
            }
        } else if let text = pb.string(forType: .string), !text.isEmpty {
            // Plain text on clipboard
            let preview = String(text.prefix(30)).replacingOccurrences(of: "\n", with: " ")
            let label = "Use: \"\(preview)\""
            if q.isEmpty || label.lowercased().contains(q) || "clipboard".contains(q) {
                pills.append(
                    DockPill(
                        id: "clip-text", name: label, icon: "doc.on.clipboard",
                        accentColorName: "yellow", badge: "Clipboard",
                        execute: {
                            // Re-paste into frontmost app
                            if let app = AppDelegate.shared?.previousFrontmostApp {
                                app.activate(options: .activateIgnoringOtherApps)
                                DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
                                    let src = CGEventSource(stateID: .hidSystemState)
                                    let vKey: CGKeyCode = 9  // 'v'
                                    CGEvent(
                                        keyboardEventSource: src, virtualKey: vKey, keyDown: true)?
                                        .flags = .maskCommand
                                    CGEvent(
                                        keyboardEventSource: src, virtualKey: vKey, keyDown: true)?
                                        .post(tap: .cgSessionEventTap)
                                    CGEvent(
                                        keyboardEventSource: src, virtualKey: vKey, keyDown: false)?
                                        .post(tap: .cgSessionEventTap)
                                }
                            }
                        }))
            }
        }

        // File URL(s) on clipboard
        if let urls = pb.readObjects(
            forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
            !urls.isEmpty
        {
            let label =
                "Open \(urls.count == 1 ? urls[0].lastPathComponent : "\(urls.count) Files")"
            if q.isEmpty || label.lowercased().contains(q) {
                let captured = urls
                pills.append(
                    DockPill(
                        id: "clip-files", name: label, icon: "doc",
                        accentColorName: "green", badge: "Clipboard",
                        execute: { NSWorkspace.shared.activateFileViewerSelecting(captured) }))
            }
        }
        return pills
    }

    /// Compact pills that surface automatically detected context (files, browser tab, selection text).
    /// Shown when context-awareness is enabled so L2 stays focused on user-selected context.
    private func buildAutoDetectedContextPills(query q: String) -> [DockPill] {
        guard settings.enableContextAIExtensions else { return [] }

        let needle = q.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        var pills: [DockPill] = []

        func add(
            _ id: String, _ name: String, _ icon: String, _ color: String, badge: String?,
            action: @escaping () -> Void
        ) {
            if !needle.isEmpty {
                let haystack = "\(name) \(badge ?? "")".lowercased()
                guard haystack.contains(needle) else { return }
            }
            pills.append(
                DockPill(
                    id: "autocx-\(id)",
                    name: name,
                    icon: icon,
                    accentColorName: color,
                    badge: badge,
                    execute: action
                ))
        }

        switch currentContext {
        case .filesSelected(let urls) where !urls.isEmpty:
            let firstName = urls[0].lastPathComponent
            let badge = urls.count == 1 ? firstName : "\(urls.count) selected"
            add("files", "File Context", "folder.badge.person.crop", "blue", badge: badge) {
                NSWorkspace.shared.activateFileViewerSelecting(urls)
            }

        case .url(let urlString):
            let trimmedURL = urlString.trimmingCharacters(in: .whitespacesAndNewlines)
            if let url = URL(string: trimmedURL), !trimmedURL.isEmpty {
                let badge = url.host ?? "Browser"
                add("url", "Web Context", "globe", "teal", badge: badge) {
                    NSWorkspace.shared.open(url)
                }
            }

        case .textSelected(let text):
            let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
            if !trimmed.isEmpty {
                let compact = trimmed.replacingOccurrences(of: "\n", with: " ")
                let preview = String(compact.prefix(28))
                add("text", "Text Context", "text.quote", "orange", badge: preview) {
                    let pb = NSPasteboard.general
                    pb.clearContents()
                    pb.setString(trimmed, forType: .string)
                }
            }

        default:
            break
        }

        // Fallback for cases where AX captured file selection but currentContext hasn't switched yet.
        if pills.isEmpty && !axContext.selectedFilePaths.isEmpty {
            let urls = axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
            let firstName = urls[0].lastPathComponent
            let badge = urls.count == 1 ? firstName : "\(urls.count) selected"
            add("files-ax", "File Context", "folder", "blue", badge: badge) {
                NSWorkspace.shared.activateFileViewerSelecting(urls)
            }
        }

        return Array(pills.prefix(2))
    }

    /// Detect current work session from running apps and re-order adapter actions.
    func sessionRankedAdapterActions(base: [AdapterAction]) -> [AdapterAction] {
        guard settings.sessionDetectionPills else { return base }
        let runningIds = Set(
            NSWorkspace.shared.runningApplications.compactMap { $0.bundleIdentifier })
        // Session profiles: bundles that signal a session type, and action keywords to boost
        let devBundles = [
            "com.apple.dt.Xcode", "com.microsoft.VSCode", "com.jetbrains", "io.cursor",
            "com.sublimetext", "com.github.atom", "com.panic.Nova",
        ]
        let browseBundles = [
            "com.apple.Safari", "com.google.Chrome", "org.mozilla.firefox", "com.microsoft.edgemac",
        ]
        let commsBundles = [
            "com.apple.MobileSMS", "com.tinyspeck.slackmacgap", "com.microsoft.teams",
            "com.discord", "com.apple.mail",
        ]

        let isDev = devBundles.contains { b in runningIds.contains { $0.hasPrefix(b) } }
        let isBrowse = browseBundles.contains { b in runningIds.contains { $0.hasPrefix(b) } }
        let isComms = commsBundles.contains { b in runningIds.contains { $0.hasPrefix(b) } }

        let boostKeywords: [String]
        if isDev {
            boostKeywords = ["build", "run", "debug", "test", "deploy", "commit", "push", "pull"]
        } else if isBrowse {
            boostKeywords = ["open", "browse", "search", "bookmark", "read", "save"]
        } else if isComms {
            boostKeywords = ["send", "share", "copy", "message", "paste", "email"]
        } else {
            return base
        }

        return base.sorted { a, b in
            let aBoost = boostKeywords.contains { a.name.lowercased().contains($0) }
            let bBoost = boostKeywords.contains { b.name.lowercased().contains($0) }
            if aBoost != bBoost { return aBoost }
            return false
        }
    }

    private func normalizedDockPillText(_ text: String) -> String {
        let lowered = text.lowercased()
        let mapped = lowered.unicodeScalars.map { scalar -> Character in
            if CharacterSet.alphanumerics.contains(scalar)
                || CharacterSet.whitespacesAndNewlines.contains(scalar)
            {
                return Character(scalar)
            }
            return " "
        }
        return String(mapped)
            .components(separatedBy: .whitespacesAndNewlines)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
    }

    private func dockPillTokens(_ text: String) -> [String] {
        normalizedDockPillText(text).split(separator: " ").map(String.init)
    }

    private func dockPillAppAliases(appName: String, bundleId: String) -> [String] {
        var aliases = Set<String>()
        let normalizedName = normalizedDockPillText(appName)
        if !normalizedName.isEmpty {
            aliases.insert(normalizedName)
            if let firstWord = normalizedName.split(separator: " ").first {
                aliases.insert(String(firstWord))
            }
            if normalizedName.hasSuffix("s"), normalizedName.count > 3 {
                aliases.insert(String(normalizedName.dropLast()))
            }
        }

        if let bundleTail = bundleId.split(separator: ".").last {
            let tail = normalizedDockPillText(String(bundleTail))
            if !tail.isEmpty && tail != "app" {
                aliases.insert(tail)
            }
        }

        switch bundleId {
        case "com.apple.MobileSMS":
            aliases.formUnion(["messages", "message", "imessage", "texts"])
        case "com.apple.mail":
            aliases.formUnion(["mail", "email"])
        case "com.apple.systempreferences":
            aliases.formUnion(["settings", "preferences", "system settings", "system preferences"])
        case "com.apple.Safari":
            aliases.insert("safari")
        default:
            break
        }

        return aliases.filter { !$0.isEmpty }
    }

    private func defaultDockPillTrackingIdentifier(_ pill: DockPill) -> String {
        if !pill.trackingIdentifier.isEmpty {
            return pill.trackingIdentifier
        }

        let scope = pill.sourceBundleId.isEmpty ? "global" : pill.sourceBundleId
        let baseName =
            !pill.menuItemName.isEmpty ? pill.menuItemName : pill.name
        let normalizedBase = normalizedDockPillText(baseName)
        if pill.rankingKind == "menu", !normalizedBase.isEmpty {
            return "dock-menu:\(scope):\(normalizedBase)"
        }
        return "dock-pill:\(scope):\(pill.rankingKind):\(normalizedBase)"
    }

    private func dockPillKindBaseScore(_ pill: DockPill) -> Double {
        switch pill.rankingKind {
        case "appLaunch": return 136
        case "semanticIntent": return 128
        case "finderCurrent": return 114
        case "finderSearch": return 104
        case "adapter", "appAdapter": return 108
        case "menu": return 98
        case "payload": return 94
        case "cliTool": return 92
        case "quickAction": return 90
        case "contextExtension": return 86
        case "tool": return 82
        case "crossApp": return 72
        case "finderContext": return 68
        case "context", "clipboard": return 62
        default: return 58
        }
    }

    private func scoreDockPill(
        _ pill: DockPill,
        originalIndex: Int,
        query: String,
        rawQuery: String,
        scopedBundleId: String,
        scopedAppName: String,
        isExplicitAppScope: Bool
    ) -> Double {
        var score = dockPillKindBaseScore(pill)
        let trackingIdentifier = defaultDockPillTrackingIdentifier(pill)
        let usageScore = UsageTracker.shared.getScore(for: trackingIdentifier)
        score += usageScore * (query.isEmpty ? 8.5 : 6.5)

        if pill.isFavourited {
            score += 190
        }

        let frontBundleId =
            frontmostAppBundleID.isEmpty ? axContext.bundleId : frontmostAppBundleID
        let sourceBundleId = pill.sourceBundleId.isEmpty ? scopedBundleId : pill.sourceBundleId
        let sourceAppName = pill.sourceAppName.isEmpty ? scopedAppName : pill.sourceAppName

        if !sourceBundleId.isEmpty {
            if sourceBundleId == scopedBundleId {
                score += isExplicitAppScope ? 220 : 125
            } else if sourceBundleId == frontBundleId {
                score += isExplicitAppScope ? 28 : 92
            } else if isExplicitAppScope {
                score -= 35
            }
        }

        let appAliases = dockPillAppAliases(appName: sourceAppName, bundleId: sourceBundleId)
        let normalizedName = normalizedDockPillText(pill.name)
        let normalizedBadge = normalizedDockPillText(pill.badge ?? "")
        let corpora = ([normalizedName, normalizedBadge] + pill.searchTerms.map(normalizedDockPillText)
            + appAliases)
            .filter { !$0.isEmpty }

        if !rawQuery.isEmpty && appAliases.contains(rawQuery) {
            score += sourceBundleId == scopedBundleId ? 120 : 60
        }

        if query.isEmpty {
            let isPureScopedAppSelection =
                isExplicitAppScope && !rawQuery.isEmpty && appAliases.contains(rawQuery)
            if pill.rankingKind == "adapter" || pill.rankingKind == "appAdapter" {
                score += isPureScopedAppSelection ? 72 : 28
            }
            if pill.rankingKind == "quickAction" {
                score += isPureScopedAppSelection ? 40 : 18
            }
            if pill.rankingKind == "menu" {
                score += isPureScopedAppSelection ? 34 : 18
            }
            if pill.rankingKind == "cliTool" {
                score += isPureScopedAppSelection ? 8 : 24
            }
            if pill.rankingKind == "appLaunch" && isPureScopedAppSelection {
                score -= 84
            }
            if normalizedName.hasPrefix("new ") || normalizedName == "new" {
                score += 22
            }
            return score - (Double(originalIndex) * 0.01)
        }

        if normalizedName == query {
            score += 280
        } else if corpora.contains(query) {
            score += 220
        }

        if normalizedName.hasPrefix(query) {
            score += 195
        } else if corpora.contains(where: { $0.hasPrefix(query) }) {
            score += 165
        }

        if normalizedName.contains(query) {
            score += 120
        } else if corpora.contains(where: { $0.contains(query) }) {
            score += 82
        }

        let orderedQueryTokens = dockPillTokens(query)
        let queryTokens = Set(orderedQueryTokens)
        if !queryTokens.isEmpty {
            let nameTokens = Set(dockPillTokens(normalizedName))
            let corpusTokens = Set(corpora.flatMap(dockPillTokens))
            let nameOverlap = queryTokens.intersection(nameTokens).count
            let corpusOverlap = queryTokens.intersection(corpusTokens).count

            if nameOverlap > 0 {
                score += Double(nameOverlap) * 54
            }
            if corpusOverlap > nameOverlap {
                score += Double(corpusOverlap - nameOverlap) * 30
            }

            if let firstToken = orderedQueryTokens.first {
                if nameTokens.contains(firstToken) {
                    score += 34
                }
                if normalizedName.hasPrefix(firstToken) {
                    score += 28
                }
            }
        }

        return score - (Double(originalIndex) * 0.01)
    }

    private func rankDockPills(
        _ pills: [DockPill],
        rawQuery: String,
        rankingQuery: String,
        scopedBundleId: String,
        scopedAppName: String,
        isExplicitAppScope: Bool
    ) -> [DockPill] {
        guard !rawQuery.isEmpty else { return pills }

        let normalizedRawQuery = normalizedDockPillText(rawQuery)
        let normalizedRankingQuery = normalizedDockPillText(rankingQuery)

        return pills.enumerated()
            .map { index, pill in
                var enriched = pill
                enriched.trackingIdentifier = defaultDockPillTrackingIdentifier(pill)
                enriched.rankingScore = scoreDockPill(
                    enriched,
                    originalIndex: index,
                    query: normalizedRankingQuery,
                    rawQuery: normalizedRawQuery,
                    scopedBundleId: scopedBundleId,
                    scopedAppName: scopedAppName,
                    isExplicitAppScope: isExplicitAppScope
                )
                return enriched
            }
            .sorted { lhs, rhs in
                if lhs.rankingScore == rhs.rankingScore {
                    return lhs.name.localizedCaseInsensitiveCompare(rhs.name) == .orderedAscending
                }
                return lhs.rankingScore > rhs.rankingScore
            }
    }

    /// If `q` starts with a known recent/running app name, returns (that app, remainder query).
    /// e.g. "safari tab" → (safariApp, "tab")   "xcode build" → (xcodeApp, "build")
    // MARK: - Instant menu reload on app switch

    /// Called immediately when the frontmost app changes while the dock is open.
    /// Cancels any in-flight menu load and starts a fresh one for `app`.
    private func reloadMenuForApp(_ app: NSRunningApplication) {
        guard showContextInDock, !app.isTerminated else { return }
        let pid = app.processIdentifier
        let name = app.localizedName ?? ""

        menuLoadTask?.cancel()
        liveMenuRefreshTask?.cancel()
        liveMenuRefreshTask = nil
        lastLiveMenuStructureRefresh = .distantPast
        contextMenuPills = []
        previousEnabledIDs = []

        menuLoadTask = Task.detached(priority: .userInitiated) {
            var loadedFromPersistentCache = false
            var items = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            if items.isEmpty {
                try? await Task.sleep(nanoseconds: 180_000_000)
                items = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            }
            if items.isEmpty {
                let snapshotItems = await MainActor.run { AXContextReader.shared.current.menuItems }
                items = snapshotItems.compactMap { info in
                    let path = info.fullPath
                        .components(separatedBy: " > ")
                        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                        .filter { !$0.isEmpty }
                    guard let title = path.last, !title.isEmpty else { return nil }
                    return AXMenuItem(
                        title: title,
                        path: path,
                        isEnabled: info.enabled,
                        element: AXUIElementCreateApplication(pid),
                        children: [],
                        sourcePID: pid,
                        sourceAppName: name,
                        isAppleMenu: path.first == "Apple",
                        shortcutChar: nil,
                        shortcutModifiers: 0
                        )
                }
            }
            if items.isEmpty {
                items = AppMenuCapabilityCache.shared.menuItems(for: app, maxResults: 120)
                loadedFromPersistentCache = !items.isEmpty
            }
            for i in items.indices {
                items[i].sourcePID = pid
                items[i].sourceAppName = name
            }
            if !loadedFromPersistentCache {
                AppMenuCapabilityCache.shared.store(items: items, for: app)
            }
            let debug = AXMenuReader.shared.lastDebug(for: pid) ?? "no reader detail"
            await MainActor.run {
                self.liveMenuItems = items
                self.menuDebugText = "\(name): \(items.count) menus, \(debug)"
                self.lastLiveMenuSignature = self.menuSignature(for: items)
                self.previousEnabledIDs = Set(items.filter(\.isEnabled).map(\.id))
                self.syncRecentAppsFromAppleMenu(items)
            }
        }

        // Restart observer for the new app
        selectionModel.start(for: pid)

        // Refresh AX context snapshot
        AXContextReader.shared.refresh(from: app)
        axContext = AXContextReader.shared.current
    }

    // MARK: - Finder AI — natural language over current folder

    private func handleFinderAIQuery(query: String) {
        guard !query.isEmpty else { return }

        let scope = resolveDockScope(for: query)
        let effectiveQuery =
            scope.scopedBundleId == "com.apple.finder"
                && scope.isExplicitAppScope
                && !scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? scope.scopedSearchQuery
            : query
        let normalized = effectiveQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let folderPath = currentFinderFolderPath()
        let finderFrontmostWindowActive = isFinderFrontmostWindowContext()
        let folderSearchAttached = isFinderCurrentWindowSearchAttached(currentFolderPath: folderPath)
        let selectedFileURLs = effectiveFinderSelectedFileURLs(
            for: normalized,
            currentFolderPath: folderPath
        )
        let selectedFiles = selectedFileURLs.map(\.path)

        if let pending = pendingFinderOperation {
            l2ChatMessages.append(AIChatMessage(role: .user, content: query))
            if isAffirmativeResponse(normalized) {
                pendingFinderOperation = nil
                runFinderIntent(pending.intent, folderPath: pending.folderPath, confirmed: true)
                return
            }
            if isNegativeResponse(normalized) {
                pendingFinderOperation = nil
                l2ChatMessages.append(
                    AIChatMessage(
                        role: .assistant, content: "Okay, I won't reorganize that folder."))
                return
            }
        }

        if let intent = parseFinderIntent(query: normalized) {
            l2ChatMessages.append(AIChatMessage(role: .user, content: query))
            l2IsLoading = true
            searchText = ""
            enforceL2ContextMode()
            runFinderIntent(
                intent, folderPath: folderPath, confirmed: false, originalQuery: normalized)
            return
        }

        if isFinderSearchStyleQuery(normalized) {
            guard folderSearchAttached else {
                l2ChatMessages.append(AIChatMessage(role: .user, content: query))
                l2ChatMessages.append(
                    AIChatMessage(
                        role: .assistant,
                        content:
                            finderFrontmostWindowActive
                                ? "Add the current Finder folder first, then I’ll search only the files and folders in this frontmost Finder window."
                                : "Bring Finder to the front, add the current folder, then I’ll search only the files and folders in that frontmost Finder window."
                    )
                )
                searchText = ""
                enforceL2ContextMode()
                clearFinderSemanticState()
                return
            }

            let cachedResults = finderSemanticQuery == normalized ? finderSemanticResults : []
            if !cachedResults.isEmpty {
                l2ChatMessages.append(AIChatMessage(role: .user, content: query))
                l2ChatMessages.append(
                    AIChatMessage(
                        role: .assistant,
                        content: finderSubmissionSummary(for: effectiveQuery, results: cachedResults)
                    ))
                searchText = ""
                enforceL2ContextMode()
                updateL2Results(cachedResults)
                return
            }

            l2ChatMessages.append(AIChatMessage(role: .user, content: query))
            l2IsLoading = true
            searchText = ""
            enforceL2ContextMode()
            l2CurrentTask = Task {
                let spotlightEnabled = settings.enableSpotlightSearch
                let fastMatches = await buildFastFinderSemanticMatches(
                    query: normalized,
                    currentFolderPath: folderPath
                )
                let spotlightMatches =
                    spotlightEnabled && normalized.count >= 3
                    ? runFinderSpotlightSearch(
                        query: normalized,
                        currentFolderPath: folderPath,
                        limit: 18
                    )
                    : []
                let targetMatches = await buildFinderTargetSemanticMatches(
                    for: normalized,
                    currentFolderPath: folderPath,
                    spotlightEnabled: spotlightEnabled
                )
                let mergedMatches = mergeFinderSemanticMatches(
                    mergeFinderSemanticMatches(fastMatches, with: spotlightMatches),
                    with: targetMatches
                )

                await MainActor.run {
                    let results = makeFinderSemanticSearchResults(from: mergedMatches)
                    finderSemanticQuery = normalized
                    finderSemanticResults = results
                    finderSemanticPills = makeFinderSemanticDockPills(from: mergedMatches)
                    l2ChatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: finderSubmissionSummary(for: effectiveQuery, results: results)
                        ))
                    updateL2Results(results)
                    l2IsLoading = false
                    l2CurrentTask = nil
                }
            }
            return
        }

        l2ChatMessages.append(AIChatMessage(role: .user, content: query))
        l2IsLoading = true
        searchText = ""
        enforceL2ContextMode()

        // Snapshot everything we know about Finder right now
        let fallbackFolderPath =
            axContext.currentURL?
            .replacingOccurrences(of: "file://", with: "")
            .removingPercentEncoding
            ?? axContext.windowTitle
            ?? "unknown folder"
        let menuTitles = liveMenuItems.filter(\.isEnabled).map(\.title)

        // Set currentContext so on-device AI gets proper file/PDF content via buildContextPrompt
        if !selectedFileURLs.isEmpty {
            currentContext = .filesSelected(selectedFileURLs)
        }

        // Read all visible filenames in the current folder via AppleScript
        l2CurrentTask = Task {
            let spotlightEnabled = settings.enableSpotlightSearch && folderSearchAttached
            let fastSemanticMatches =
                folderSearchAttached
                ? await buildFastFinderSemanticMatches(
                    query: normalized,
                    currentFolderPath: folderPath
                )
                : []
            let spotlightSemanticMatches =
                spotlightEnabled && normalized.count >= 3
                ? runFinderSpotlightSearch(
                    query: normalized,
                    currentFolderPath: folderPath,
                    limit: 12
                )
                : []
            let targetMatches =
                folderSearchAttached
                ? await buildFinderTargetSemanticMatches(
                    for: normalized,
                    currentFolderPath: folderPath,
                    spotlightEnabled: spotlightEnabled
                )
                : []
            let retrievedMatches = mergeFinderSemanticMatches(
                mergeFinderSemanticMatches(
                    fastSemanticMatches,
                    with: spotlightSemanticMatches
                ),
                with: targetMatches
            )

            // 1. Get visible files in current Finder window
            let visibleFilesScript = """
                tell application "Finder"
                    try
                        set theItems to every item of (target of front window) as alias
                        set nameList to {}
                        repeat with i in theItems
                            set end of nameList to name of i
                        end repeat
                        return nameList as string
                    end try
                end tell
                """
            var visibleFiles: [String] = []
            if let raw = await runAppleScript(visibleFilesScript), !raw.isEmpty {
                visibleFiles = raw.components(separatedBy: ", ").filter { !$0.isEmpty }
            }

            // 2. Read file content for selected files (text, PDF, code, etc.)
            var fileContentBlock = ""
            for filePath in selectedFiles.prefix(3) {
                let fileURL = URL(fileURLWithPath: filePath)
                let ext = fileURL.pathExtension.lowercased()
                let textExts = Set([
                    "txt", "md", "markdown", "swift", "py", "js", "ts", "jsx", "tsx", "html", "css",
                    "scss", "json", "xml", "yaml", "yml", "csv", "log", "sh", "bash", "zsh", "conf",
                    "config", "ini", "toml", "r", "c", "cpp", "h", "java", "go", "rs", "rb", "php",
                    "sql", "rtf",
                ])
                var content: String? = nil
                if textExts.contains(ext) {
                    content = try? String(contentsOf: fileURL, encoding: .utf8)
                    if content == nil {
                        content = try? String(contentsOf: fileURL, encoding: .isoLatin1)
                    }
                    if let c = content { content = String(c.prefix(4000)) }
                } else if ext == "pdf" {
                    if let pdf = PDFDocument(url: fileURL) {
                        var text = ""
                        for i in 0..<min(pdf.pageCount, 8) {
                            if let pageText = pdf.page(at: i)?.string { text += pageText + "\n" }
                            if text.count > 4000 { break }
                        }
                        if !text.isEmpty { content = String(text.prefix(4000)) }
                    }
                } else if ext == "docx" || ext == "rtfd" {
                    if let attr = try? NSAttributedString(
                        url: fileURL, options: [:], documentAttributes: nil)
                    {
                        content = String(attr.string.prefix(4000))
                    }
                }
                if let content, !content.isEmpty {
                    fileContentBlock +=
                        "\n\n### Content of \(fileURL.lastPathComponent):\n```\n\(content)\n```"
                }
            }

            let retrievedSummaryBlock: String = {
                guard !retrievedMatches.isEmpty else { return "" }
                let lines = retrievedMatches.prefix(8).map { match in
                    "- \(match.title) [\(match.source)] \(finderDisplayPath(match.path))"
                }
                return "\nRETRIEVED FINDER MATCHES:\n" + lines.joined(separator: "\n")
            }()

            let currentFolderCatalogBlock =
                folderSearchAttached
                ? buildFinderFileCatalogBlock(
                    currentFolderPath: folderPath,
                    selectedFilePaths: selectedFiles
                )
                : ""

            let resolvedTargetContext = buildFinderResolvedTargetContext(
                query: normalized,
                selectedFilePaths: selectedFiles,
                retrievedMatches: retrievedMatches
            )

            let retrievedContentBlock: String = {
                let candidateURLs = retrievedMatches
                    .filter { !$0.isDirectory }
                    .prefix(2)
                    .map { URL(fileURLWithPath: $0.path) }
                guard !candidateURLs.isEmpty else { return "" }

                let analyzedFiles = ContextDetector.shared.analyzeFiles(Array(candidateURLs))
                var block = ""
                for file in analyzedFiles.prefix(2) {
                    guard let content = file.content,
                        !content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    else { continue }
                    block +=
                        "\n\n### Retrieved content from \(file.url.lastPathComponent):\n```\n\(String(content.prefix(2500)))\n```"
                }
                return block
            }()

            // 3. Build the AI prompt
            let systemPrompt = """
                You are a macOS Finder assistant embedded in Context-Dock.
                You help users with file operations AND answer questions about file contents.

                \(currentDateTimeContextBlock())

                CURRENT STATE:
                - Folder: \(fallbackFolderPath)
                - Selected files: \(selectedFiles.isEmpty ? "none" : selectedFiles.map { URL(fileURLWithPath: $0).lastPathComponent }.joined(separator: ", "))
                - Visible files in window: \(visibleFiles.isEmpty ? "unknown" : visibleFiles.prefix(30).joined(separator: ", "))
                - Available Finder menu actions: \(menuTitles.prefix(20).joined(separator: ", "))
                \(retrievedSummaryBlock)
                \(currentFolderCatalogBlock)
                \(resolvedTargetContext.summaryBlock)
                \(fileContentBlock)
                \(retrievedContentBlock)
                \(resolvedTargetContext.contentBlock)

                RULES:
                1. Respond with EITHER:
                   a) ACTION:APPLESCRIPT:<applescript code on one line using \\n for newlines>
                   b) ACTION:SHELL:<shell command>
                   c) ACTION:MENU:<exact menu item title from the available actions list>
                   d) ANSWER:<plain text answer if the user asks about file contents, explanations, summaries, or informational questions>

                2. For questions about what a file contains, what it is, summarize, explain, translate — use ANSWER with the file content above.
                3. For file operations prefer AppleScript (it integrates with Finder natively).
                4. For conversions, compressions, bulk renames prefer SHELL.
                5. For menu items that exist in the available list, prefer MENU.
                6. Use the EXACT filenames from the visible files list when referencing files.
                7. For selected files use: \(selectedFiles.map { "\"\($0)\"" }.joined(separator: ", "))
                8. Shell commands run in bash. $HOME = /Users/\(NSUserName()). Current dir = \(fallbackFolderPath)
                9. For ACTION responses, output ONLY the ACTION line. For ANSWER responses, provide a helpful answer.
                10. For file operations, prefer RESOLVED TARGET FILES first. If there are no resolved targets, use SELECTED FILES. If there is still ambiguity, ask a short clarification instead of guessing.
                11. When converting or chaining actions, use the exact file path from RESOLVED TARGET FILES or SELECTED FILES.

                EXAMPLES:
                User: move selected files to desktop
                ACTION:APPLESCRIPT:tell application "Finder" to move selection to (path to desktop)

                User: rename all jpg files to add today's date
                ACTION:SHELL:cd "\(fallbackFolderPath)" && for f in *.jpg; do mv "$f" "$(date +%Y-%m-%d)_$f"; done

                User: what is this file about?
                ANSWER:This file is about [summary based on the file content above].

                User: how many files are here
                ANSWER:There are \(visibleFiles.count) visible items in \(fallbackFolderPath).
                """

            let provider = await MainActor.run { self.settings.selectedAIProvider }

            do {
                let context: [[String: String]] = [
                    ["role": "system", "content": systemPrompt],
                    ["role": "user", "content": query],
                ]

                if selectedFileURLs.isEmpty && !resolvedTargetContext.targetURLs.isEmpty {
                    await MainActor.run {
                        self.rememberFinderFollowUpTargets(
                            Array(resolvedTargetContext.targetURLs.prefix(3)),
                            folderPath: folderPath,
                            sourceQuery: normalized
                        )
                        self.currentContext = .filesSelected(Array(resolvedTargetContext.targetURLs.prefix(3)))
                    }
                } else if !selectedFileURLs.isEmpty {
                    await MainActor.run {
                        self.rememberFinderFollowUpTargets(
                            Array(selectedFileURLs.prefix(3)),
                            folderPath: folderPath,
                            sourceQuery: normalized
                        )
                    }
                }

                let response: String
                if provider == .onDevice {
                    response = try await self.sendToOnDeviceAI(query: query, context: context)
                } else {
                    response = try await self.sendToProvider(query: query, context: context)
                }

                await MainActor.run {
                    self.l2IsLoading = false
                    self.l2CurrentTask = nil
                    DispatchQueue.main.async {
                        self.executeFinderAIResponse(response, folderPath: fallbackFolderPath)
                    }
                }
            } catch {
                await MainActor.run {
                    self.l2ChatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: "❌ \(error.localizedDescription)",
                            isError: true
                        ))
                    self.l2IsLoading = false
                    self.l2CurrentTask = nil
                }
            }
        }
    }

    private func parseFinderIntent(query: String) -> FinderIntent? {
        if query.contains("organize"),
            query.contains("type") || query.contains("types") || query.contains("category")
        {
            return .organizeByType
        }

        let detectedCategory = FinderFileCategory.detect(in: query)

        if query.contains("recent"),
            detectedCategory == nil,
            !query.contains("today"),
            !query.contains("yesterday"),
            !query.contains("week"),
            !query.contains("large"),
            !query.contains("small")
        {
            return .showRecentFiles(limit: 30)
        }

        // Natural language: "any X?", "is there any X", "are there X", "check for X",
        // "do i have X", "how many X", "look for X", "search for X", "count X"
        let listWords = [
            "show", "list", "find", "display", "any", "there any", "check", "search",
            "how many", "count", "look for", "do i have", "have any", "got any",
        ]
        if listWords.contains(where: query.contains),
            let category = detectedCategory
        {
            return .filterFiles(category: category)
        }

        // Also catch bare category mentions: "torrent files?", "pdf files?"
        if let category = detectedCategory,
            query.contains("file") || query.contains("files")
        {
            return .filterFiles(category: category)
        }

        return nil
    }

    private func runFinderIntent(
        _ intent: FinderIntent, folderPath: String, confirmed: Bool, originalQuery: String = ""
    ) {
        l2CurrentTask?.cancel()
        l2CurrentTask = Task {
            switch intent {
            case .showRecentFiles(let limit):
                let urls = recentFinderItems(in: folderPath, limit: limit)
                let summary: String
                if urls.isEmpty {
                    summary =
                        "No recent files found in \(URL(fileURLWithPath: folderPath).lastPathComponent)."
                } else {
                    summary =
                        "Found \(urls.count) recent item\(urls.count == 1 ? "" : "s") in \(URL(fileURLWithPath: folderPath).lastPathComponent). Showing newest first."
                }
                let results = buildFinderSearchResults(from: urls, subtitle: "Recent Files")
                await MainActor.run {
                    l2ChatMessages.append(AIChatMessage(role: .assistant, content: summary))
                    updateL2Results(results)
                    l2IsLoading = false
                    l2CurrentTask = nil
                }

            case .filterFiles(let category):
                // For archives, further filter by a specific extension if the original query mentions one
                let lowerQuery = originalQuery.lowercased()
                let specificExt: String? = {
                    if category == .archive {
                        if lowerQuery.contains("torrent") { return "torrent" }
                        if lowerQuery.contains("dmg") { return "dmg" }
                        if lowerQuery.contains("zip") { return "zip" }
                    }
                    return nil
                }()
                let all = finderItems(in: folderPath).filter { category.matches($0) }
                let urls =
                    specificExt != nil
                    ? all.filter { $0.pathExtension.lowercased() == specificExt! }
                    : all
                let typeName = specificExt ?? category.displayName
                let folderName = URL(fileURLWithPath: folderPath).lastPathComponent
                let summary: String
                if urls.isEmpty {
                    summary = "No \(typeName) files found in \(folderName)."
                } else {
                    let names = urls.prefix(5).map { $0.lastPathComponent }.joined(
                        separator: "\n• ")
                    summary =
                        "Found \(urls.count) \(typeName) file\(urls.count == 1 ? "" : "s") in \(folderName):\n• \(names)"
                        + (urls.count > 5 ? "\n…and \(urls.count - 5) more." : "")
                }
                let results = buildFinderSearchResults(from: urls, subtitle: category.resultTitle)
                await MainActor.run {
                    l2ChatMessages.append(AIChatMessage(role: .assistant, content: summary))
                    updateL2Results(results)
                    l2IsLoading = false
                    l2CurrentTask = nil
                }

            case .organizeByType:
                if !confirmed {
                    let preview = previewOrganizeFinderItems(in: folderPath)
                    await MainActor.run {
                        if preview.moveCount == 0 {
                            l2ChatMessages.append(
                                AIChatMessage(
                                    role: .assistant,
                                    content:
                                        "Nothing to reorganize in \(URL(fileURLWithPath: folderPath).lastPathComponent)."
                                ))
                        } else {
                            pendingFinderOperation = PendingFinderOperation(
                                intent: intent, folderPath: folderPath)
                            l2ChatMessages.append(
                                AIChatMessage(role: .assistant, content: preview.message))
                        }
                        l2IsLoading = false
                        l2CurrentTask = nil
                    }
                    return
                }

                let result = organizeFinderItemsByType(in: folderPath)
                await MainActor.run {
                    l2ChatMessages.append(
                        AIChatMessage(
                            role: .assistant, content: result.message, isError: !result.success))
                    if !result.createdFolders.isEmpty {
                        updateL2Results(
                            buildFinderSearchResults(
                                from: result.createdFolders, subtitle: "Organized Folders"))
                    }
                    l2IsLoading = false
                    l2CurrentTask = nil
                }
            }
        }
    }

    private func currentFinderFolderPath() -> String {
        let cachedPath = cachedFinderCurrentDirectoryPath.trimmingCharacters(
            in: .whitespacesAndNewlines)
        if !cachedPath.isEmpty {
            return cachedPath
        }

        let decodedURLPath =
            axContext.currentURL?
            .replacingOccurrences(of: "file://", with: "")
            .removingPercentEncoding?
            .trimmingCharacters(in: .whitespacesAndNewlines)

        let fallback =
            (decodedURLPath?.isEmpty == false ? decodedURLPath : nil)
            ?? {
                let title = axContext.windowTitle?.trimmingCharacters(in: .whitespacesAndNewlines)
                return title?.isEmpty == false ? title : nil
            }()

        return fallback ?? NSHomeDirectory()
    }

    private func refreshCachedFinderCurrentDirectory(for bundleID: String) {
        guard bundleID == "com.apple.finder" else {
            cachedFinderCurrentDirectoryPath = ""
            return
        }

        cachedFinderCurrentDirectoryPath =
            ContextDetector.shared.getCurrentFinderDirectory()?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    }

    private func isFinderFrontmostWindowContext() -> Bool {
        if frontmostAppBundleID == "com.apple.finder" { return true }
        if contextTargetApp()?.bundleIdentifier == "com.apple.finder" { return true }
        return axContext.bundleId == "com.apple.finder"
    }

    private func isFinderCurrentWindowSearchAttached(currentFolderPath: String? = nil) -> Bool {
        guard isFinderFrontmostWindowContext() else { return false }
        return isFinderFolderSearchAttached(currentFolderPath: currentFolderPath)
    }

    private func shouldUseFinderSearchPopover(for query: String) -> Bool {
        guard isL2ContextActive, showContextInDock, !showMediaLayer else { return false }
        let normalized = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !normalized.isEmpty else { return false }

        let scope = resolveDockScope(for: normalized)
        guard scope.scopedBundleId == "com.apple.finder" else { return false }

        let currentFolderPath = currentFinderFolderPath()
        return isFinderCurrentWindowSearchAttached(currentFolderPath: currentFolderPath)
    }

    private func shouldKeepFinderSearchPopoverVisible(for query: String) -> Bool {
        guard isL2ContextActive, showContextInDock, !showMediaLayer else { return false }

        let scope = resolveDockScope(for: query)
        let scopeIsFinder =
            scope.scopedBundleId == "com.apple.finder"
            || (query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                && isFinderFrontmostWindowContext())
        guard scopeIsFinder else { return false }

        let semanticQuery = scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard semanticQuery.isEmpty else { return false }

        let currentFolderPath = currentFinderFolderPath()
        return isFinderCurrentWindowSearchAttached(currentFolderPath: currentFolderPath)
    }

    private func isFinderFolderSearchModeEnabled(for query: String) -> Bool {
        guard isL2ContextActive, showContextInDock, !showMediaLayer else { return false }
        let scope = resolveDockScope(for: query)
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        let scopeIsFinder =
            scope.scopedBundleId == "com.apple.finder"
            || (trimmed.isEmpty && isFinderFrontmostWindowContext())
        guard scopeIsFinder else { return false }

        let currentFolderPath = currentFinderFolderPath()
        return isFinderCurrentWindowSearchAttached(currentFolderPath: currentFolderPath)
    }

    private func shouldShowFinderSearchResultsPanel(for query: String) -> Bool {
        guard isFinderFolderSearchModeEnabled(for: query) else { return false }
        let scopedQuery = resolveDockScope(for: query)
            .scopedSearchQuery
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return !scopedQuery.isEmpty || isFinderSemanticLoading || !finderSemanticResults.isEmpty
    }

    private func applyFinderSemanticPanelResults(_ results: [SearchResult]) {
        guard showContextInDock, !showMediaLayer else { return }
        if !isSearchBarExpanded && !results.isEmpty {
            withAnimation(.spring(response: 0.3, dampingFraction: 0.8)) {
                isSearchBarExpanded = true
            }
        }
        searchResults = results
        groupedResults = {
            var grouped = GroupedResults()
            results.forEach { grouped.add($0) }
            return grouped
        }()
        selectedResultIndex = nil
    }

    private func finderItems(in folderPath: String) -> [URL] {
        let folderURL = URL(fileURLWithPath: folderPath)
        let keys: [URLResourceKey] = [
            .isDirectoryKey, .contentModificationDateKey, .localizedNameKey,
        ]
        let urls =
            (try? FileManager.default.contentsOfDirectory(
                at: folderURL,
                includingPropertiesForKeys: keys,
                options: [.skipsHiddenFiles]
            )) ?? []

        return urls.sorted {
            $0.lastPathComponent.localizedCaseInsensitiveCompare($1.lastPathComponent)
                == .orderedAscending
        }
    }

    private func recentFinderItems(in folderPath: String, limit: Int) -> [URL] {
        finderItems(in: folderPath)
            .sorted {
                let lhs =
                    (try? $0.resourceValues(forKeys: [.contentModificationDateKey])
                        .contentModificationDate) ?? .distantPast
                let rhs =
                    (try? $1.resourceValues(forKeys: [.contentModificationDateKey])
                        .contentModificationDate) ?? .distantPast
                return lhs > rhs
            }
            .prefix(limit)
            .map { $0 }
    }

    private func buildFinderSearchResults(from urls: [URL], subtitle: String) -> [SearchResult] {
        urls.map { url in
            let path = url.path
            let isDirectory =
                (try? url.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) ?? false
            let resultType: SearchResult.ResultType = {
                if isDirectory { return .folder }
                let ext = url.pathExtension.lowercased()
                if ["pdf", "txt", "md", "doc", "docx", "pages", "rtf"].contains(ext) {
                    return .document
                }
                return .file
            }()

            return SearchResult(
                title: url.lastPathComponent,
                subtitle: subtitle,
                icon: NSWorkspace.shared.icon(forFile: path),
                action: {
                    rememberFinderFollowUpTargets(
                        [url],
                        folderPath: url.deletingLastPathComponent().path,
                        sourceQuery: url.lastPathComponent
                    )
                    currentContext = .filesSelected([url])
                    NSWorkspace.shared.open(url)
                },
                score: 0.0,
                type: resultType,
                filePath: path,
                contactData: nil
            )
        }
    }

    private func previewOrganizeFinderItems(in folderPath: String) -> (
        moveCount: Int, message: String
    ) {
        let items = finderItems(in: folderPath).filter { !($0.hasDirectoryPath) }
        var bucketCounts: [(FinderFileCategory, Int)] = []
        var examples: [String] = []

        for category in FinderFileCategory.allCases where category != .folder {
            let matches = items.filter { category.matches($0) }
            guard !matches.isEmpty else { continue }
            bucketCounts.append((category, matches.count))
            for url in matches.prefix(2) {
                examples.append("• \(url.lastPathComponent) → \(category.destinationFolderName)/")
            }
        }

        let moveCount = bucketCounts.reduce(0) { $0 + $1.1 }
        guard moveCount > 0 else {
            return (0, "")
        }

        var lines = [
            "I can organize \(URL(fileURLWithPath: folderPath).lastPathComponent) by type:"
        ]
        lines.append(contentsOf: bucketCounts.map { "- \($0.0.destinationFolderName): \($0.1)" })
        if !examples.isEmpty {
            lines.append("")
            lines.append("Preview:")
            lines.append(contentsOf: examples.prefix(6))
        }
        lines.append("")
        lines.append("Shall I proceed?")
        return (moveCount, lines.joined(separator: "\n"))
    }

    private func organizeFinderItemsByType(in folderPath: String) -> (
        success: Bool, message: String, createdFolders: [URL]
    ) {
        let items = finderItems(in: folderPath).filter { !($0.hasDirectoryPath) }
        guard !items.isEmpty else {
            return (
                true,
                "No files found to organize in \(URL(fileURLWithPath: folderPath).lastPathComponent).",
                []
            )
        }

        let baseURL = URL(fileURLWithPath: folderPath)
        let fileManager = FileManager.default
        var movedCount = 0
        var createdFolders: [URL] = []
        var failures: [String] = []

        for fileURL in items {
            guard
                let category = FinderFileCategory.allCases.first(where: {
                    $0 != .folder && $0.matches(fileURL)
                })
            else {
                continue
            }

            let destinationFolder = baseURL.appendingPathComponent(
                category.destinationFolderName, isDirectory: true)
            if !fileManager.fileExists(atPath: destinationFolder.path) {
                do {
                    try fileManager.createDirectory(
                        at: destinationFolder, withIntermediateDirectories: true)
                    createdFolders.append(destinationFolder)
                } catch {
                    failures.append("Couldn't create \(category.destinationFolderName)")
                    continue
                }
            }

            let destinationURL = uniqueFinderDestination(for: fileURL, in: destinationFolder)
            do {
                try fileManager.moveItem(at: fileURL, to: destinationURL)
                movedCount += 1
            } catch {
                failures.append("Couldn't move \(fileURL.lastPathComponent)")
            }
        }

        let folderLabel = URL(fileURLWithPath: folderPath).lastPathComponent
        if movedCount == 0 {
            let failureText =
                failures.isEmpty
                ? "No matching files needed organizing." : failures.joined(separator: "\n")
            return (false, failureText, createdFolders)
        }

        var lines = ["Organized \(movedCount) file\(movedCount == 1 ? "" : "s") in \(folderLabel)."]
        if !createdFolders.isEmpty {
            lines.append(
                "Created \(createdFolders.count) folder\(createdFolders.count == 1 ? "" : "s").")
        }
        if !failures.isEmpty {
            lines.append("")
            lines.append("Some items were skipped:")
            lines.append(contentsOf: failures.prefix(5))
        }
        return (failures.isEmpty, lines.joined(separator: "\n"), createdFolders)
    }

    private func uniqueFinderDestination(for fileURL: URL, in folderURL: URL) -> URL {
        let fileManager = FileManager.default
        let ext = fileURL.pathExtension
        let baseName = fileURL.deletingPathExtension().lastPathComponent
        var candidate = folderURL.appendingPathComponent(fileURL.lastPathComponent)
        var index = 2

        while fileManager.fileExists(atPath: candidate.path) {
            let name = ext.isEmpty ? "\(baseName) \(index)" : "\(baseName) \(index).\(ext)"
            candidate = folderURL.appendingPathComponent(name)
            index += 1
        }

        return candidate
    }

    private func executeFinderAIResponse(_ response: String, folderPath: String) {
        let trimmed = response.trimmingCharacters(in: .whitespacesAndNewlines)

        if trimmed.hasPrefix("ACTION:APPLESCRIPT:") {
            let script = String(trimmed.dropFirst("ACTION:APPLESCRIPT:".count))
                .replacingOccurrences(of: "\\n", with: "\n")
            l2ChatMessages.append(
                AIChatMessage(role: .assistant, content: "```applescript\n\(script)\n```"))
            Task.detached(priority: .userInitiated) {
                var err: NSDictionary?
                NSAppleScript(source: script)?.executeAndReturnError(&err)
                if let e = err {
                    await MainActor.run {
                        self.l2ChatMessages.append(
                            AIChatMessage(
                                role: .assistant,
                                content:
                                    "⚠️ \(e["NSAppleScriptErrorMessage"] as? String ?? "Script error")",
                                isError: true))
                    }
                }
                try? await Task.sleep(nanoseconds: 400_000_000)
                await MainActor.run {
                    if let app = NSWorkspace.shared.runningApplications.first(where: {
                        $0.bundleIdentifier == "com.apple.finder"
                    }) {
                        AXMenuReader.shared.invalidateCache(for: app.processIdentifier)
                        self.reloadMenuForApp(app)
                    }
                }
            }

        } else if trimmed.hasPrefix("ACTION:SHELL:") {
            let cmd = String(trimmed.dropFirst("ACTION:SHELL:".count))
            l2ChatMessages.append(AIChatMessage(role: .assistant, content: "```bash\n\(cmd)\n```"))
            Task.detached(priority: .userInitiated) {
                let process = Process()
                process.launchPath = "/bin/bash"
                process.arguments = ["-c", cmd]
                process.currentDirectoryPath = folderPath
                let pipe = Pipe()
                process.standardOutput = pipe
                process.standardError = pipe
                try? process.run()
                process.waitUntilExit()
                let output =
                    String(data: pipe.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8)
                    ?? ""
                let createdURL =
                    process.terminationStatus == 0
                    ? self.detectCreatedFile(command: cmd, output: output) : nil
                await MainActor.run {
                    let status =
                        process.terminationStatus == 0
                        ? "✅ Done" : "❌ Failed (exit \(process.terminationStatus))"
                    let msg =
                        output.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                        ? status
                        : "\(status)\n```\n\(output.prefix(500))\n```"
                    self.l2ChatMessages.append(AIChatMessage(role: .assistant, content: msg))
                    if let createdURL {
                        self.rememberFinderFollowUpTargets(
                            [createdURL],
                            folderPath: createdURL.deletingLastPathComponent().path,
                            sourceQuery: cmd
                        )
                        self.currentContext = .filesSelected([createdURL])
                    }
                    ILauncherNotificationManager.shared.shellFinished(
                        command: cmd,
                        exitCode: process.terminationStatus
                    )
                }
            }

        } else if trimmed.hasPrefix("ACTION:MENU:") {
            let menuTitle = String(trimmed.dropFirst("ACTION:MENU:".count))
            l2ChatMessages.append(AIChatMessage(role: .assistant, content: "▶ \(menuTitle)"))
            if let item = liveMenuItems.first(where: {
                $0.title.lowercased() == menuTitle.lowercased()
            }),
                let pid = NSWorkspace.shared.runningApplications
                    .first(where: { $0.bundleIdentifier == "com.apple.finder" })?.processIdentifier
            {
                executeDockMenuAction(
                    sourcePID: pid,
                    path: item.path,
                    shortcutChar: item.shortcutChar,
                    shortcutModifiers: item.shortcutModifiers
                )
            }

        } else if trimmed.hasPrefix("ANSWER:") {
            let answer = String(trimmed.dropFirst("ANSWER:".count))
            l2ChatMessages.append(AIChatMessage(role: .assistant, content: answer))

        } else {
            // Model didn't follow the format — show the raw response
            l2ChatMessages.append(AIChatMessage(role: .assistant, content: trimmed))
        }
    }

    @discardableResult
    private func runAppleScript(_ source: String) async -> String? {
        return await withCheckedContinuation { cont in
            DispatchQueue.global(qos: .userInitiated).async {
                var err: NSDictionary?
                guard let s = NSAppleScript(source: source) else {
                    cont.resume(returning: nil)
                    return
                }
                let result = s.executeAndReturnError(&err)
                cont.resume(returning: result.stringValue)
            }
        }
    }

    // MARK: - Apple menu recent apps sync

    /// Reads "Recent Items > Applications" from the already-loaded liveMenuItems and
    /// updates AppDelegate.recentApps with running apps that match — giving us the
    /// same list macOS itself tracks, not just apps activated while our dock was open.
    private func syncRecentAppsFromAppleMenu(_ items: [AXMenuItem]) {
        // Apple menu items: path[0] == "" (the  symbol), path[1] == "Recent Items"
        let recentNames =
            items
            .filter { $0.path.count >= 2 && $0.path[0].isEmpty && $0.path[1] == "Recent Items" }
            .map { $0.title.replacingOccurrences(of: ".app", with: "") }
            .filter { !$0.isEmpty && $0 != "Clear Menu" }

        guard !recentNames.isEmpty else { return }

        let running = NSWorkspace.shared.runningApplications
        let frontPID = AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0

        // Match names to running processes, preserving Apple menu order, skip frontmost & self
        let matched: [NSRunningApplication] = recentNames.compactMap { name in
            running.first {
                $0.activationPolicy == .regular
                    && !$0.isTerminated
                    && $0.processIdentifier != frontPID
                    && $0.bundleIdentifier != Bundle.main.bundleIdentifier
                    && ($0.localizedName ?? "") == name
            }
        }

        // Deduplicate and update
        var seen = Set<pid_t>()
        let deduped = matched.filter { seen.insert($0.processIdentifier).inserted }
        AppDelegate.shared?.setRecentAppsFromMenu(Array(deduped.prefix(5)))
    }

    private func menuSignature(for items: [AXMenuItem]) -> String {
        items
            .prefix(500)
            .map { item in
                [
                    item.path.joined(separator: " > "),
                    item.isEnabled ? "1" : "0",
                    item.shortcutChar ?? "",
                    "\(item.shortcutModifiers)",
                ].joined(separator: "|")
            }
            .joined(separator: "\n")
    }

    private func refreshFrontmostMenuStructureIfNeeded(
        for app: NSRunningApplication,
        force: Bool = false
    ) {
        guard showContextInDock, !app.isTerminated else { return }
        guard liveMenuRefreshTask == nil else { return }

        let now = Date()
        let minInterval: TimeInterval = force ? 0 : 1.15
        guard force || now.timeIntervalSince(lastLiveMenuStructureRefresh) >= minInterval else {
            return
        }
        lastLiveMenuStructureRefresh = now

        let pid = app.processIdentifier
        let name = app.localizedName ?? ""
        let bundleId = app.bundleIdentifier

        liveMenuRefreshTask = Task.detached(priority: force ? .userInitiated : .utility) {
            var items = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            guard !Task.isCancelled else { return }
            guard !items.isEmpty else {
                await MainActor.run {
                    if self.liveMenuRefreshTask != nil {
                        self.liveMenuRefreshTask = nil
                    }
                }
                return
            }

            for i in items.indices {
                items[i].sourcePID = pid
                items[i].sourceAppName = name
            }
            if let liveApp = NSWorkspace.shared.runningApplications.first(where: {
                $0.processIdentifier == pid && !$0.isTerminated
            }) {
                AppMenuCapabilityCache.shared.store(items: items, for: liveApp)
            }

            let debug = AXMenuReader.shared.lastDebug(for: pid) ?? "no reader detail"
            await MainActor.run {
                self.liveMenuRefreshTask = nil
                guard self.showContextInDock else { return }
                guard self.contextTargetApp()?.processIdentifier == pid else {
                    return
                }
                let signature = self.menuSignature(for: items)
                guard force || signature != self.lastLiveMenuSignature else { return }

                self.liveMenuItems = items
                self.lastLiveMenuSignature = signature
                self.menuDebugText = "\(name): \(items.count) menus, \(debug), live"
                self.previousEnabledIDs = Set(items.filter(\.isEnabled).map(\.id))
                self.contextMenuPills = []
                self.syncRecentAppsFromAppleMenu(items)
                if self.frontmostAppBundleID.isEmpty, let bundleId {
                    self.frontmostAppBundleID = bundleId
                }
            }
        }
    }

    // MARK: - Selection-change handler

    /// Called (debounced 200ms) whenever AXObserver detects a selection/focus change
    /// in the frontmost app. Re-reads only `kAXEnabled` for all cached menu items,
    /// computes the delta (newly enabled items), and surfaces them as context pills.
    private func handleSelectionChange() {
        guard showContextInDock else { return }

        if !liveMenuItems.isEmpty {
            // Re-read enabled states — one attribute call per item, no tree traversal
            let enabledMap = AXMenuReader.shared.refreshEnabledStates(for: liveMenuItems)

            // Apply updates in-place
            var updated = liveMenuItems
            for i in updated.indices {
                if let enabled = enabledMap[updated[i].id] {
                    updated[i].isEnabled = enabled
                }
            }

            // Compute delta: items that just became enabled
            let newEnabledIDs = Set(updated.filter(\.isEnabled).map(\.id))
            let deltaIDs = newEnabledIDs.subtracting(previousEnabledIDs)
            let delta = updated.filter { deltaIDs.contains($0.id) && !$0.isAppleMenu }
                .sorted { ($0.shortcutChar != nil ? 0 : 1) < ($1.shortcutChar != nil ? 0 : 1) }

            previousEnabledIDs = newEnabledIDs
            liveMenuItems = updated

            // Keep top 6 newly-enabled items as context pills
            contextMenuPills = Array(delta.prefix(6))
        }

        refreshLiveContextDockState()
    }

    private func refreshLiveContextDockState() {
        guard showContextInDock, let app = contextTargetApp() else { return }

        refreshFrontmostMenuStructureIfNeeded(for: app)

        AXContextReader.shared.refresh(from: app)
        let newCtx = AXContextReader.shared.current
        refreshCachedFinderCurrentDirectory(for: app.bundleIdentifier ?? "")

        // URL-change detection: recache page when user navigates
        if AXWebReader.shared.isBrowser(bundleId: app.bundleIdentifier ?? ""),
            let newURL = newCtx.currentURL, !newURL.isEmpty,
            newURL != lastKnownBrowserURL
        {
            lastKnownBrowserURL = newURL
            AXWebReader.shared.invalidate(pid: app.processIdentifier)
            scheduleBrowserContextWarmup(reason: "browser URL changed", urlOverride: newURL)
        }

        let contextChanged =
            newCtx.selectedFilePaths != axContext.selectedFilePaths
            || newCtx.selectedText != axContext.selectedText
            || newCtx.currentURL != axContext.currentURL
            || newCtx.windowTitle != axContext.windowTitle

        if contextChanged {
            axContext = newCtx
            detectAndUpdateContext()
        }
        // Clipboard monitoring: detect copies from any app (covers Electron/VS Code where AX selectedText is nil)
        checkClipboardForGlobalContext()
        // Always check for selection-based global context switch after AX refresh
        autoSwitchGlobalContextIfNeeded()
        // Auto-return to dock if selection was cleared since last poll
        autoReturnFromGlobalContextIfNeeded()
    }

    private func checkClipboardForGlobalContext() {
        let pb = NSPasteboard.general
        let currentCount = pb.changeCount
        guard currentCount != lastCheckedPasteboardCount else { return }
        lastCheckedPasteboardCount = currentCount

        // Ignore our own writes (pasteboard owner check)
        guard pb.pasteboardItems?.first?.types.contains(.string) == true else { return }
        guard let text = pb.string(forType: .string) else { return }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        // Require meaningful text (not a path or tiny string)
        guard trimmed.count > 3 else { return }

        withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
            globalClipboardText = trimmed
            showGlobalClipboardPill = true
        }
        // Auto-switch to global context if we're in dock mode and not already there
        if showContextInDock && !isGlobalContextActive && l2TargetApp == nil {
            withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
                isGlobalContextActive = true
            }
            isGlobalContextAutoActivated = true
        }
        // Rebuild pills so clipboard chip appears immediately
        cachedDockPills = buildDockPills(query: lastPillQuery)
    }

    /// Switches to Global Context automatically when files, text, or a URL are selected
    /// in the frontmost app. Checks both axContext (live AX state) and currentContext.
    private func autoSwitchGlobalContextIfNeeded() {
        guard showContextInDock, l2TargetApp == nil, !isGlobalContextActive else { return }
        // Don't re-trigger within 600ms of an app switch — the AX observer fires for the
        // new app with stale/cursor-position state which would immediately flip back to global.
        guard Date().timeIntervalSince(lastAppSwitchDate) > 0.6 else { return }
        // Files selected: always meaningful
        let hasFileSelection = !axContext.selectedFilePaths.isEmpty
        // Text: require > 15 chars to avoid cursor-position false positives in Electron apps
        let axText = (axContext.selectedText ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let hasTextSelection = axText.count > 15
        let hasContextSelection: Bool = {
            switch currentContext {
            case .filesSelected(let u): return !u.isEmpty
            case .textSelected(let t):
                return t.trimmingCharacters(in: .whitespacesAndNewlines).count > 15
            case .url(let s):
                return !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            default: return false
            }
        }()
        if hasFileSelection || hasTextSelection || hasContextSelection {
            isGlobalContextActive = true
            isGlobalContextAutoActivated = true
        }
    }

    /// Auto-returns to Context Dock when the selection that triggered global context is gone.
    /// Only fires if global context was auto-activated (not manually swiped by user).
    private func autoReturnFromGlobalContextIfNeeded() {
        guard isGlobalContextActive, isGlobalContextAutoActivated, !isAIMode else { return }
        let hasFileSelection = !axContext.selectedFilePaths.isEmpty
        let axText = (axContext.selectedText ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let hasTextSelection = axText.count > 15
        let hasCtxSel: Bool = {
            switch currentContext {
            case .filesSelected(let u): return !u.isEmpty
            case .textSelected(let t): return t.trimmingCharacters(in: .whitespacesAndNewlines).count > 15
            case .url(let s): return !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            default: return false
            }
        }()
        let hasClipboard = showGlobalClipboardPill && !globalClipboardText.isEmpty
        if !hasFileSelection && !hasTextSelection && !hasCtxSel && !hasClipboard {
            withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
                isGlobalContextActive = false
                isGlobalContextAutoActivated = false
            }
            cachedDockPills = buildDockPills(query: lastPillQuery)
        }
    }

    // MARK: - Share sheet

    private func presentSharingPicker(items: [Any]) {
        guard !items.isEmpty else { return }
        let picker = NSSharingServicePicker(items: items)
        let coordinator = SharePickerCoordinator {
            self.isSharingSheetActive = false
        }
        picker.delegate = coordinator
        objc_setAssociatedObject(
            picker,
            &SharePickerCoordinator.key,
            coordinator,
            .OBJC_ASSOCIATION_RETAIN_NONATOMIC
        )

        isSharingSheetActive = true
        DispatchQueue.main.async {
            guard let window = NSApp.keyWindow,
                let view = window.contentView
            else {
                self.isSharingSheetActive = false
                return
            }
            let rect = NSRect(x: window.frame.width / 2 - 60, y: 52, width: 120, height: 1)
            picker.show(relativeTo: rect, of: view, preferredEdge: .maxY)
        }
    }

    /// Shows NSSharingServicePicker anchored above the pill row,
    /// using the current AX context (selected files, URL, or text).
    /// Sets shareSheetVisible = true so arrow keys are passed through to the picker.
    private func showShareSheetForContext() {
        var items = ShareIntentRouter.shared.shareItems(for: effectiveAXContextForConversation())
        if items.isEmpty {
            // Fallback: show picker with app URL so at least something appears
            if let app = AppDelegate.shared?.previousFrontmostApp,
                let bid = app.bundleIdentifier,
                let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bid)
            {
                items = [url]
            } else {
                return
            }
        }
        presentSharingPicker(items: items)
    }

    private func executeShareIntent(
        _ intent: ShareIntent,
        userMessage: String? = nil
    ) {
        let capturedContext = effectiveAXContextForConversation()
        if let userMessage, !userMessage.isEmpty {
            l2ChatMessages.append(AIChatMessage(role: .user, content: userMessage))
        }
        l2IsLoading = true
        Task {
            let resolution = await ShareIntentRouter.shared.resolve(intent)
            let output = await ShareIntentRouter.shared.execute(
                resolution,
                axContext: capturedContext,
                presentSharingPicker: { items in
                    self.presentSharingPicker(items: items)
                }
            )
            await MainActor.run {
                self.l2ChatMessages.append(AIChatMessage(role: .assistant, content: output))
                self.l2IsLoading = false
            }
        }
    }

    private func executeCrossAppIntent(
        _ intent: CrossAppIntent,
        userMessage: String,
        unresolvedMessage: String = "❌ Couldn't resolve that. Try: \"send this to [name]\" or \"email this to [name]\""
    ) {
        if let existingTask = l2CurrentTask {
            existingTask.cancel()
            l2CurrentTask = nil
            l2IsLoading = false
            l2ActiveRequestID = nil
        }
        let capturedContext = effectiveAXContextForConversation()
        l2ChatMessages.append(AIChatMessage(role: .user, content: userMessage))
        l2IsLoading = true
        l2CurrentTask = Task {
            guard let resolved = await CrossAppNLHandler.shared.resolve(intent) else {
                await MainActor.run {
                    l2ChatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: unresolvedMessage
                        ))
                    l2IsLoading = false
                    l2CurrentTask = nil
                }
                return
            }
            let output = await CrossAppNLHandler.shared.execute(
                resolved,
                axContext: capturedContext,
                presentSharingPicker: { items in
                    self.presentSharingPicker(items: items)
                }
            )
            await MainActor.run {
                l2ChatMessages.append(AIChatMessage(role: .assistant, content: output))
                l2IsLoading = false
                l2CurrentTask = nil
                searchText = ""
                focusedPillIndex = nil
            }
        }
    }

    private func executeResolvedAppAction(
        _ resolution: L2AppActionResolution,
        userMessage: String
    ) {
        if let existingTask = l2CurrentTask {
            existingTask.cancel()
            l2CurrentTask = nil
            l2IsLoading = false
            l2ActiveRequestID = nil
        }

        let match = resolution.primary
        let capturedContext = effectiveAXContextForConversation()
        l2ChatMessages.append(AIChatMessage(role: .user, content: userMessage))
        l2IsLoading = true
        l2CurrentTask = Task {
            let result = await adapterManager.execute(
                match.action,
                context: capturedContext,
                targetBundleId: match.adapter.bundleId,
                query: userMessage
            )

            let output: String
            if result.0 {
                output = "✅ Executed \(match.adapter.appName) → \(match.action.name).\n\(result.1)"
            } else {
                output = "❌ Couldn't run \(match.adapter.appName) → \(match.action.name).\n\(result.1)"
            }

            await MainActor.run {
                l2ChatMessages.append(AIChatMessage(role: .assistant, content: output))
                l2IsLoading = false
                l2CurrentTask = nil
                searchText = ""
                focusedPillIndex = nil
            }
        }
    }

    private func executeGlobalAppLaunch(
        bundleId: String,
        appName: String,
        userMessage: String
    ) {
        l2ChatMessages.append(AIChatMessage(role: .user, content: userMessage))
        let launched = launchApplication(bundleIdentifier: bundleId, appName: appName)
        let message =
            launched
            ? "✅ Opened \(appName)."
            : "❌ Couldn't open \(appName)."
        l2ChatMessages.append(AIChatMessage(role: .assistant, content: message))
        searchText = ""
        focusedPillIndex = nil
    }

    private var isGlobalQueryModeActive: Bool {
        showContextInDock && isGlobalContextActive
    }

    private var effectiveConversationUserContext: UserContext {
        // Global Context: use live AX selection as the authoritative context
        if showContextInDock && isGlobalContextActive {
            let axFiles = axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
            if !axFiles.isEmpty { return .filesSelected(axFiles) }
            if let t = axContext.selectedText,
                !t.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            { return .textSelected(t) }
            switch currentContext {
            case .filesSelected, .textSelected, .url, .contactSelected: return currentContext
            default: break
            }
            // Clipboard pill: user explicitly copied content (covers VS Code/Electron/any app)
            if showGlobalClipboardPill && !globalClipboardText.isEmpty {
                if let url = URL(string: globalClipboardText), url.scheme != nil {
                    return .url(globalClipboardText)
                }
                return .textSelected(globalClipboardText)
            }
            return .none
        }

        if showContextInDock {
            let scope = resolveDockScope(for: searchText)
            if scope.isExplicitAppScope,
                !scope.scopedBundleId.isEmpty,
                !scope.scopedAppName.isEmpty
            {
                return .appFocused(name: scope.scopedAppName, bundleID: scope.scopedBundleId)
            }
        }

        guard isGlobalQueryModeActive else { return currentContext }
        switch currentContext {
        case .appFocused:
            return .none
        default:
            return currentContext
        }
    }

    private func resolveGlobalActionQuery(_ query: String) -> L2AppActionResolution? {
        let normalizedQuery = normalizedDockPillText(query)
        guard !normalizedQuery.isEmpty else { return nil }

        let queryTokens = Set(dockPillTokens(normalizedQuery))
        var matches: [L2AppActionMatch] = []

        for adapter in AppAdapterManager.shared.adapters where adapter.isEnabled {
            let normalizedAppName = normalizedDockPillText(adapter.appName)

            for action in adapter.actions {
                let normalizedActionName = normalizedDockPillText(action.name)
                let normalizedTriggers = action.triggers.map(normalizedDockPillText)
                let corpora = ([normalizedActionName] + normalizedTriggers).filter { !$0.isEmpty }

                var score = 0.0

                if corpora.contains(normalizedQuery) {
                    score += 155
                }
                if normalizedActionName == normalizedQuery {
                    score += 135
                }
                if corpora.contains(where: { $0.hasPrefix(normalizedQuery) }) {
                    score += 96
                }
                if corpora.contains(where: { $0.contains(normalizedQuery) }) {
                    score += 72
                }

                let actionTokens = Set(corpora.flatMap { dockPillTokens($0) })
                let overlap = queryTokens.intersection(actionTokens).count
                if overlap > 0 {
                    score += Double(overlap * 26)
                }

                if !normalizedAppName.isEmpty && normalizedQuery.contains(normalizedAppName) {
                    score += 24
                }
                if queryTokens.contains(where: { normalizedAppName.contains($0) }) {
                    score += 16
                }

                guard score >= 90 else { continue }

                matches.append(
                    L2AppActionMatch(
                        adapter: adapter,
                        action: action,
                        score: score,
                        matchedAppPhrase: normalizedAppName,
                        matchedActionPhrase: normalizedQuery,
                        usedFrontmostFallback: false
                    )
                )
            }
        }

        let ranked = matches.sorted {
            if $0.score != $1.score { return $0.score > $1.score }
            return $0.action.name.localizedCaseInsensitiveCompare($1.action.name) == .orderedAscending
        }

        guard let primary = ranked.first else { return nil }
        let alternatives = Array(ranked.dropFirst().prefix(3)).filter { $0.score >= primary.score - 20 }
        return L2AppActionResolution(primary: primary, alternatives: alternatives)
    }

    private func globalAIContextBlock() -> String {
        var lines: [String] = ["## Global Context Mode", "Treat the frontmost app as passive context only."]

        let context = effectiveAXContextForConversation()
        if !context.isEmpty {
            lines.append("## Passive Live Context")
            lines.append(context.contextSummary)
        }

        let selectedFiles = effectiveSelectedFileURLsForConversation()
        if !selectedFiles.isEmpty {
            lines.append("## Selected Files")
            for url in selectedFiles.prefix(8) {
                lines.append("- \(url.lastPathComponent)")
            }
        }

        return lines.joined(separator: "\n")
    }

    private func messagesScopedSemanticIntent(for scopedQuery: String) -> CrossAppIntent? {
        let normalized = scopedQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalized.isEmpty else { return nil }
        return CrossAppNLHandler.shared.parseMessagesScopedIntent(normalized)
    }

    private func rawDockQuery(matching normalizedQuery: String) -> String {
        let rawQuery = searchText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !rawQuery.isEmpty,
            normalizedDockPillText(rawQuery) == normalizedDockPillText(normalizedQuery)
        else {
            return normalizedQuery
        }
        return rawQuery
    }

    private func stripScopedAlias(_ alias: String, from rawQuery: String) -> String {
        let trimmed = rawQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        let aliasTokens = alias.split(separator: " ").map { $0.lowercased() }
        let queryTokens = trimmed.split(separator: " ", omittingEmptySubsequences: true)
        guard !aliasTokens.isEmpty, queryTokens.count >= aliasTokens.count else { return trimmed }

        let prefix = queryTokens.prefix(aliasTokens.count).map { $0.lowercased() }
        guard prefix == aliasTokens else { return trimmed }
        return queryTokens.dropFirst(aliasTokens.count).map(String.init).joined(separator: " ")
    }

    private func rawScopedActionQuery(for normalizedQuery: String, scope: DockScopeResolution) -> String {
        let rawQuery = rawDockQuery(matching: normalizedQuery)
        let normalizedRawQuery = normalizedDockPillText(rawQuery)

        if let explicitTarget = L2AppActionRouter.shared.appScopeTarget(for: normalizedRawQuery),
            explicitTarget.bundleId == scope.scopedBundleId
        {
            return stripScopedAlias(explicitTarget.matchedAlias, from: rawQuery)
        }

        if let installedTarget = installedAppMenuTarget(for: normalizedRawQuery),
            installedTarget.bundleId == scope.scopedBundleId
        {
            return stripScopedAlias(installedTarget.matchedAlias, from: rawQuery)
        }

        return rawQuery
    }

    private func messageIntentDisplayText(_ value: String, limit: Int) -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count > limit else { return trimmed }
        return String(trimmed.prefix(limit - 1)) + "…"
    }

    private func firstQuotedPhrase(in value: String) -> String? {
        guard let regex = try? NSRegularExpression(pattern: #""([^"]+)""#, options: []) else {
            return nil
        }
        let range = NSRange(value.startIndex..<value.endIndex, in: value)
        guard let match = regex.firstMatch(in: value, options: [], range: range),
            match.numberOfRanges > 1,
            let captureRange = Range(match.range(at: 1), in: value)
        else {
            return nil
        }
        return String(value[captureRange])
    }

    private enum MailSearchTokenKind {
        case generic
        case sender
        case subject
        case attachment
        case date
    }

    private struct MailSearchIntent {
        let query: String
        let tokenKind: MailSearchTokenKind
        let displayLabel: String
    }

    private func mailSearchDisplayLabel(
        query: String,
        tokenKind: MailSearchTokenKind
    ) -> String {
        switch tokenKind {
        case .date:
            return query
        case .sender:
            return "from \(query)"
        case .subject:
            return "subject \(query)"
        case .attachment:
            return "attachment \(query)"
        case .generic:
            return query
        }
    }

    private func mailSearchTokenKind(from value: String) -> MailSearchTokenKind {
        switch normalizedDockPillText(value) {
        case "sender":
            return .sender
        case "subject":
            return .subject
        case "attachment":
            return .attachment
        case "date":
            return .date
        default:
            return .generic
        }
    }

    private func resolvedMailMailboxSearchIntent(for rawScopedQuery: String) async -> MailSearchIntent? {
        #if canImport(FoundationModels)
        if #available(macOS 26.0, *) {
            if let generated = try? await generateMailIntent(
                from: rawScopedQuery,
                dateTimeContext: currentDateTimeContextBlock()
            ) {
                let mode = normalizedDockPillText(generated.mode)
                if mode == "question" || mode == "none" {
                    return nil
                }

                let resolvedQuery = generated.searchQuery
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                if !resolvedQuery.isEmpty {
                    let tokenKind = mailSearchTokenKind(from: generated.tokenKind)
                    return MailSearchIntent(
                        query: resolvedQuery,
                        tokenKind: tokenKind,
                        displayLabel: mailSearchDisplayLabel(
                            query: resolvedQuery,
                            tokenKind: tokenKind
                        )
                    )
                }
            }
        }
        #endif

        return shouldExecuteMailMailboxSearch(for: rawScopedQuery)
    }

    private func weekdayNameCandidate(for normalizedQuery: String) -> String? {
        let weekdays = [
            "monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"
        ]
        return weekdays.first(where: { $0.hasPrefix(normalizedQuery) || normalizedQuery.hasPrefix($0) })
    }

    private func mailDateSuggestionCandidates(for query: String) -> [String] {
        let normalized = normalizedDockPillText(query)
        guard !normalized.isEmpty else { return [] }

        var candidates: [String] = []
        let formatter = DateFormatter()
        formatter.locale = Locale.current
        formatter.dateFormat = "EEEE, d MMMM yyyy"
        let calendar = Calendar.current
        let now = Date()

        if let weekday = weekdayNameCandidate(for: normalized) {
            candidates.append(weekday)
            if let weekdayIndex = [
                "sunday": 1, "monday": 2, "tuesday": 3, "wednesday": 4,
                "thursday": 5, "friday": 6, "saturday": 7,
            ][weekday] {
                let currentWeekday = calendar.component(.weekday, from: now)
                let offset = (weekdayIndex - currentWeekday + 7) % 7
                if let date = calendar.date(byAdding: .day, value: offset, to: now) {
                    candidates.append(formatter.string(from: date))
                }
            }
        }

        if ["today", "tod"].contains(where: { normalized.hasPrefix($0) }) {
            candidates.append(formatter.string(from: now))
        } else if ["yesterday", "yest"].contains(where: { normalized.hasPrefix($0) }),
            let date = calendar.date(byAdding: .day, value: -1, to: now)
        {
            candidates.append(formatter.string(from: date))
        } else if ["tomorrow", "tomo"].contains(where: { normalized.hasPrefix($0) }),
            let date = calendar.date(byAdding: .day, value: 1, to: now)
        {
            candidates.append(formatter.string(from: date))
        }

        return Array(NSOrderedSet(array: candidates)) as? [String] ?? candidates
    }

    private func mailSemanticSearchIntent(from rawScopedQuery: String) -> MailSearchIntent? {
        let trimmed = rawScopedQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }

        let normalized = normalizedDockPillText(trimmed)
        let tokens = Set(dockPillTokens(normalized))
        let intentWords: Set<String> = ["search", "find", "lookup", "look", "show"]
        let dateCandidates = mailDateSuggestionCandidates(for: trimmed)
        let explicitSenderIntent = tokens.contains("from") || tokens.contains("sender")
        let explicitSubjectIntent = tokens.contains("subject")
        let explicitAttachmentIntent =
            tokens.contains("attachment") || tokens.contains("attachments")
                || tokens.contains("attach")
        let explicitDateIntent =
            tokens.contains("date") || !dateCandidates.isEmpty

        guard !tokens.isDisjoint(with: intentWords)
            || explicitSenderIntent
            || explicitSubjectIntent
            || explicitAttachmentIntent
            || explicitDateIntent
        else { return nil }

        if let quoted = firstQuotedPhrase(in: trimmed)?
            .trimmingCharacters(in: .whitespacesAndNewlines),
            !quoted.isEmpty
        {
            let tokenKind: MailSearchTokenKind =
                explicitSenderIntent ? .sender
                : explicitSubjectIntent ? .subject
                : explicitAttachmentIntent ? .attachment
                : explicitDateIntent ? .date
                : .generic
            let label: String =
                tokenKind == .date ? quoted
                : tokenKind == .sender ? "from \(quoted)"
                : tokenKind == .subject ? "subject \(quoted)"
                : tokenKind == .attachment ? "attachment \(quoted)"
                : quoted
            return MailSearchIntent(query: quoted, tokenKind: tokenKind, displayLabel: label)
        }

        var cleaned = trimmed
        let patterns = [
            #"(?i)\b(search|find|lookup|look\s+for|show)\b"#,
            #"(?i)\b(mail|mails|email|emails|mailbox|inbox)\b"#,
            #"(?i)\b(sender|from|subject|attachment|attachments|attach|for|about|with|in|date)\b"#,
        ]
        for pattern in patterns {
            cleaned = cleaned.replacingOccurrences(
                of: pattern,
                with: " ",
                options: .regularExpression
            )
        }
        cleaned = cleaned
            .replacingOccurrences(of: #"\s+"#, with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleaned.isEmpty else { return nil }

        let tokenKind: MailSearchTokenKind =
            explicitSenderIntent ? .sender
            : explicitSubjectIntent ? .subject
            : explicitAttachmentIntent ? .attachment
            : explicitDateIntent ? .date
            : .generic
        let label: String =
            tokenKind == .date ? cleaned
            : tokenKind == .sender ? "from \(cleaned)"
            : tokenKind == .subject ? "subject \(cleaned)"
            : tokenKind == .attachment ? "attachment \(cleaned)"
            : cleaned

        return MailSearchIntent(query: cleaned, tokenKind: tokenKind, displayLabel: label)
    }

    private func mailSemanticSearchQuery(from rawScopedQuery: String) -> String? {
        mailSemanticSearchIntent(from: rawScopedQuery)?.query
    }

    private func isQuestionStyleMailQuery(_ rawScopedQuery: String) -> Bool {
        let normalized = normalizedDockPillText(rawScopedQuery)
        guard !normalized.isEmpty else { return false }

        if rawScopedQuery.contains("?") { return true }

        let questionPrefixes = [
            "is", "are", "do", "does", "did", "have", "has", "what", "which", "who", "when",
            "where", "why", "how", "can", "could", "would", "should", "any", "show me",
            "tell me",
        ]
        if questionPrefixes.contains(where: { normalized == $0 || normalized.hasPrefix($0 + " ") }) {
            return true
        }

        return normalized.contains("any mail")
            || normalized.contains("any mails")
            || normalized.contains("there any")
    }

    private func shouldExecuteMailMailboxSearch(for rawScopedQuery: String) -> MailSearchIntent? {
        guard let intent = mailSemanticSearchIntent(from: rawScopedQuery) else { return nil }
        guard !isQuestionStyleMailQuery(rawScopedQuery) else { return nil }
        return intent
    }

    private struct MailQuestionFilters {
        let senderFilter: String
        let subjectFilter: String
        let unreadOnly: Bool
        let relativeDay: String
        let criteriaSummary: [String]
    }

    private func mailFieldFilter(
        from query: String,
        triggers: Set<String>
    ) -> String? {
        let tokens = dockPillTokens(normalizedDockPillText(query))
        guard let triggerIndex = tokens.firstIndex(where: { triggers.contains($0) }) else { return nil }

        let stopWords: Set<String> = [
            "today", "yesterday", "tomorrow", "unread", "read", "mail", "mails", "email",
            "emails", "mailbox", "inbox", "is", "are", "was", "were", "any", "there", "show",
            "find", "search", "lookup", "look", "for", "about", "with", "and", "or", "the",
            "a", "an", "messages", "message", "date",
        ]

        var collected: [String] = []
        for token in tokens.dropFirst(triggerIndex + 1) {
            if stopWords.contains(token) { break }
            collected.append(token)
        }

        let result = collected.joined(separator: " ").trimmingCharacters(in: .whitespacesAndNewlines)
        return result.isEmpty ? nil : result
    }

    private func mailQuestionFilters(for query: String) -> MailQuestionFilters {
        let normalized = normalizedDockPillText(query)
        let senderFilter = mailFieldFilter(from: query, triggers: ["from", "sender"]) ?? ""
        let subjectFilter = mailFieldFilter(from: query, triggers: ["subject"]) ?? ""
        let unreadOnly = normalized.contains("unread")

        let relativeDay: String =
            normalized.contains("today") ? "today"
            : normalized.contains("yesterday") ? "yesterday"
            : ""

        let criteriaSummary: [String] = [
            !senderFilter.isEmpty ? "sender contains “\(senderFilter)”" : nil,
            !subjectFilter.isEmpty ? "subject contains “\(subjectFilter)”" : nil,
            !relativeDay.isEmpty ? "received \(relativeDay)" : nil,
            unreadOnly ? "unread only" : nil,
        ].compactMap { $0 }

        return MailQuestionFilters(
            senderFilter: senderFilter,
            subjectFilter: subjectFilter,
            unreadOnly: unreadOnly,
            relativeDay: relativeDay,
            criteriaSummary: criteriaSummary
        )
    }

    private func answerAttachedMailQuestion(for rawScopedQuery: String) -> String? {
        guard isCurrentMailContextAttached(), isQuestionStyleMailQuery(rawScopedQuery) else { return nil }

        let filters = mailQuestionFilters(for: rawScopedQuery)
        let normalized = normalizedDockPillText(rawScopedQuery)
        let hasUsefulFilters =
            !filters.senderFilter.isEmpty
            || !filters.subjectFilter.isEmpty
            || filters.unreadOnly
            || !filters.relativeDay.isEmpty

        guard hasUsefulFilters || normalized.contains("mail") || normalized.contains("email") else {
            return nil
        }

        guard let snapshot = MailAutomation.mailboxSnapshotData(
            senderContains: filters.senderFilter,
            subjectContains: filters.subjectFilter,
            unreadOnly: filters.unreadOnly,
            relativeDay: filters.relativeDay,
            limit: 12,
            maxScan: 150
        ) else {
            return "Mail context could not be read from the current mailbox."
        }

        let expectsYesNo =
            rawScopedQuery.contains("?")
            || normalized.hasPrefix("is ")
            || normalized.hasPrefix("are ")
            || normalized.hasPrefix("do ")
            || normalized.hasPrefix("does ")
            || normalized.hasPrefix("did ")
            || normalized.hasPrefix("have ")
            || normalized.hasPrefix("has ")
            || normalized.contains("any mail")
            || normalized.contains("any mails")

        let criteriaText = filters.criteriaSummary.joined(separator: ", ")
        let matchCount = snapshot.messages.count

        if matchCount == 0 {
            if expectsYesNo {
                return criteriaText.isEmpty
                    ? "No — I couldn't find matching mail in \(snapshot.mailboxName)."
                    : "No — I couldn't find mail in \(snapshot.mailboxName) matching \(criteriaText)."
            }
            return criteriaText.isEmpty
                ? "No matching mail found in \(snapshot.mailboxName)."
                : "No mail in \(snapshot.mailboxName) matched \(criteriaText)."
        }

        var answer = expectsYesNo
            ? "Yes — found \(matchCount) matching \(matchCount == 1 ? "mail" : "mails") in \(snapshot.mailboxName)"
            : "Found \(matchCount) matching \(matchCount == 1 ? "mail" : "mails") in \(snapshot.mailboxName)"
        if !criteriaText.isEmpty {
            answer += " (\(criteriaText))."
        } else {
            answer += "."
        }

        for message in snapshot.messages.prefix(4) {
            answer += "\n- \(message.subject) — \(message.sender) — \(message.dateText)"
        }
        if matchCount > 4 {
            answer += "\n+ \(matchCount - 4) more"
        }

        return answer
    }

    private func buildAttachedMailContextBlock(for query: String) -> String? {
        let filters = mailQuestionFilters(for: query)
        guard let snapshot = MailAutomation.mailboxSnapshotData(
            senderContains: filters.senderFilter,
            subjectContains: filters.subjectFilter,
            unreadOnly: filters.unreadOnly,
            relativeDay: filters.relativeDay,
            limit: 12,
            maxScan: 150
        ) else {
            return "\n📧 ACTUAL MAIL DATA:\nMail context could not be read.\n"
        }

        var block = "\n📧 ACTUAL MAIL DATA (recent \(snapshot.mailboxName) scan):\n"
        if !filters.criteriaSummary.isEmpty {
            block += "Criteria: " + filters.criteriaSummary.joined(separator: ", ") + "\n"
        }
        block += "Mailbox: \(snapshot.mailboxName)\n"

        if snapshot.messages.isEmpty {
            block += "No matching messages were found in the recent Mail scan.\n"
            return block
        }

        for message in snapshot.messages {
            block += "- \(message.subject) | From: \(message.sender) | \(message.dateText) | Read: \(message.isRead)\n"
        }
        block +=
            "IMPORTANT: Use this ACTUAL mail data to answer mailbox questions. Do not make up email results.\n"
        return block
    }

    private func applicationURL(bundleIdentifier: String, appName: String) -> URL? {
        if let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleIdentifier) {
            return url
        }
        if let match = allApplications.first(where: { result in
            Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier == bundleIdentifier
        }) {
            return URL(fileURLWithPath: match.subtitle)
        }
        let fallbackDirectories = [
            "/Applications",
            "/System/Applications",
            "/System/Volumes/Preboot/Cryptexes/App/System/Applications",
            "\(NSHomeDirectory())/Applications",
        ]
        for directory in fallbackDirectories {
            let url = URL(fileURLWithPath: directory)
                .appendingPathComponent(appName)
                .appendingPathExtension("app")
            if FileManager.default.fileExists(atPath: url.path) {
                return url
            }
        }
        return nil
    }

    private func activateOrLaunchSemanticApp(bundleIdentifier: String, appName: String) async
        -> NSRunningApplication?
    {
        if let runningApp = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
        }) {
            await MainActor.run { runningApp.activate() }
            return runningApp
        }

        guard let appURL = applicationURL(bundleIdentifier: bundleIdentifier, appName: appName)
        else { return nil }

        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true

        do {
            let launchedApp = try await NSWorkspace.shared.openApplication(
                at: appURL,
                configuration: configuration
            )
            return launchedApp
        } catch {
            NSWorkspace.shared.open(appURL)
            for _ in 0..<20 {
                try? await Task.sleep(nanoseconds: 120_000_000)
                if let runningApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
                }) {
                    await MainActor.run { runningApp.activate() }
                    return runningApp
                }
            }
            return nil
        }
    }

    private func axStringAttribute(_ element: AXUIElement, _ attribute: CFString) -> String? {
        var ref: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, attribute, &ref) == .success else { return nil }
        return ref as? String
    }

    private func axStringArrayAttribute(_ element: AXUIElement, _ attribute: CFString) -> [String] {
        var ref: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, attribute, &ref) == .success else { return [] }
        return ref as? [String] ?? []
    }

    private func axChildElements(_ element: AXUIElement) -> [AXUIElement] {
        var ref: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, kAXChildrenAttribute as CFString, &ref) == .success,
            let children = ref as? [AXUIElement]
        else { return [] }
        return children
    }

    private func currentFocusedElement(in pid: pid_t) -> AXUIElement? {
        let appElement = AXUIElementCreateApplication(pid)
        var ref: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            appElement,
            kAXFocusedUIElementAttribute as CFString,
            &ref
        ) == .success, let focused = ref
        else { return nil }
        return unsafeBitCast(focused, to: AXUIElement.self)
    }

    private func isEditableAXElement(_ element: AXUIElement) -> Bool {
        let role = axStringAttribute(element, kAXRoleAttribute as CFString) ?? ""
        return ["AXSearchField", "AXTextField", "AXComboBox", "AXTextArea"].contains(role)
    }

    private func findMailSearchField(in element: AXUIElement, depth: Int = 0) -> AXUIElement? {
        guard depth < 8 else { return nil }

        let role = axStringAttribute(element, kAXRoleAttribute as CFString) ?? ""
        if role == "AXSearchField" {
            return element
        }

        let description = axStringAttribute(element, kAXDescriptionAttribute as CFString) ?? ""
        let title = axStringAttribute(element, kAXTitleAttribute as CFString) ?? ""
        let help = axStringAttribute(element, kAXHelpAttribute as CFString) ?? ""
        let metadata = normalizedDockPillText([description, title, help].joined(separator: " "))

        if isEditableAXElement(element),
            metadata.contains("search") || metadata.contains("mailbox")
        {
            return element
        }

        var firstEditableField: AXUIElement?
        for child in axChildElements(element) {
            if let exact = findMailSearchField(in: child, depth: depth + 1) {
                return exact
            }
            if firstEditableField == nil, isEditableAXElement(child) {
                firstEditableField = child
            }
        }
        return firstEditableField
    }

    private func setAXTextValue(_ text: String, on element: AXUIElement) -> Bool {
        let setFocusStatus = AXUIElementSetAttributeValue(
            element,
            kAXFocusedAttribute as CFString,
            kCFBooleanTrue
        )
        _ = setFocusStatus
        guard AXUIElementSetAttributeValue(
            element,
            kAXValueAttribute as CFString,
            text as CFTypeRef
        ) == .success else { return false }

        guard let currentValue = axStringAttribute(element, kAXValueAttribute as CFString) else {
            return false
        }

        let normalizedCurrent = normalizedDockPillText(currentValue)
        let normalizedTarget = normalizedDockPillText(text)
        return normalizedCurrent == normalizedTarget
            || normalizedCurrent.contains(normalizedTarget)
    }

    private func postKeyCode(_ keyCode: CGKeyCode, to pid: pid_t) {
        guard let source = CGEventSource(stateID: .hidSystemState),
            let keyDown = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: true),
            let keyUp = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: false)
        else { return }
        keyDown.postToPid(pid)
        keyUp.postToPid(pid)
    }

    private func postModifiedKeyCode(_ keyCode: CGKeyCode, flags: CGEventFlags, to pid: pid_t) {
        guard let source = CGEventSource(stateID: .hidSystemState),
            let keyDown = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: true),
            let keyUp = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: false)
        else { return }
        keyDown.flags = flags
        keyUp.flags = flags
        keyDown.postToPid(pid)
        keyUp.postToPid(pid)
    }

    private func postUnicodeText(_ text: String, to pid: pid_t) {
        let utf16 = Array(text.utf16)
        guard !utf16.isEmpty,
            let source = CGEventSource(stateID: .hidSystemState),
            let keyDown = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: true),
            let keyUp = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: false)
        else { return }
        keyDown.keyboardSetUnicodeString(stringLength: utf16.count, unicodeString: utf16)
        keyUp.keyboardSetUnicodeString(stringLength: utf16.count, unicodeString: utf16)
        keyDown.postToPid(pid)
        keyUp.postToPid(pid)
    }

    private func pasteString(_ text: String, to pid: pid_t) {
        let pasteboard = NSPasteboard.general
        let previousString = pasteboard.string(forType: .string)
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
        postModifiedKeyCode(9, flags: .maskCommand, to: pid)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) {
            pasteboard.clearContents()
            if let previousString {
                pasteboard.setString(previousString, forType: .string)
            }
        }
    }

    private func typeMailSearchQuery(_ query: String, into element: AXUIElement, pid: pid_t) async
        -> Bool
    {
        _ = AXUIElementSetAttributeValue(
            element,
            kAXFocusedAttribute as CFString,
            kCFBooleanTrue
        )
        try? await Task.sleep(nanoseconds: 60_000_000)
        postModifiedKeyCode(0, flags: .maskCommand, to: pid)
        try? await Task.sleep(nanoseconds: 40_000_000)
        pasteString(query, to: pid)
        try? await Task.sleep(nanoseconds: 80_000_000)

        if let currentValue = axStringAttribute(element, kAXValueAttribute as CFString) {
            let normalizedCurrent = normalizedDockPillText(currentValue)
            let normalizedTarget = normalizedDockPillText(query)
            return normalizedCurrent == normalizedTarget
                || normalizedCurrent.contains(normalizedTarget)
        }

        return true
    }

    private func axSearchableStrings(for element: AXUIElement) -> [String] {
        [
            axStringAttribute(element, kAXTitleAttribute as CFString),
            axStringAttribute(element, kAXValueAttribute as CFString),
            axStringAttribute(element, kAXDescriptionAttribute as CFString),
            axStringAttribute(element, kAXHelpAttribute as CFString),
        ]
        .compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }
    }

    private func axSubtreeSearchableStrings(for element: AXUIElement, depth: Int = 0) -> [String] {
        guard depth < 2 else { return axSearchableStrings(for: element) }

        var results = axSearchableStrings(for: element)
        for child in axChildElements(element).prefix(12) {
            results.append(contentsOf: axSubtreeSearchableStrings(for: child, depth: depth + 1))
        }
        return results
    }

    private func isMailSuggestionActionRole(_ role: String) -> Bool {
        [
            "AXRow",
            "AXGroup",
            "AXButton",
            "AXMenuItem",
            "AXListItem",
            "AXCell",
        ].contains(role)
    }

    private struct MailSuggestionMatcher {
        let tokenKind: MailSearchTokenKind
        let normalizedQuery: String
        let normalizedQueryTokens: [String]
        let normalizedCandidates: [String]
        let normalizedFieldTokens: [String]

        private static func normalize(_ text: String) -> String {
            let lowered = text.lowercased()
            let mapped = lowered.unicodeScalars.map { scalar -> Character in
                if CharacterSet.alphanumerics.contains(scalar)
                    || CharacterSet.whitespacesAndNewlines.contains(scalar)
                {
                    return Character(scalar)
                }
                return " "
            }
            return String(mapped)
                .components(separatedBy: .whitespacesAndNewlines)
                .filter { !$0.isEmpty }
                .joined(separator: " ")
        }

        private static func isActionRole(_ role: String) -> Bool {
            ["AXRow", "AXGroup", "AXButton", "AXMenuItem", "AXListItem", "AXCell"].contains(role)
        }

        init(intent: MailSearchIntent, candidates: [String]) {
            tokenKind = intent.tokenKind
            normalizedQuery = Self.normalize(intent.query)
            normalizedQueryTokens = normalizedQuery
                .split(whereSeparator: \.isWhitespace)
                .map(String.init)
                .filter { !$0.isEmpty }
            normalizedCandidates = candidates.map { Self.normalize($0) }.filter { !$0.isEmpty }

            switch intent.tokenKind {
            case .generic:
                normalizedFieldTokens = []
            case .sender:
                normalizedFieldTokens = ["sender", "contains"]
            case .subject:
                normalizedFieldTokens = ["subject", "contains"]
            case .attachment:
                normalizedFieldTokens = ["attachment", "name", "contains"]
            case .date:
                normalizedFieldTokens = ["date"]
            }
        }

        func score(
            role: String,
            actionNames: [String],
            directStrings: [String],
            subtreeStrings: [String]
        ) -> Int? {
            let normalizedDirect = directStrings.map { Self.normalize($0) }.filter { !$0.isEmpty }
            let normalizedSubtree = subtreeStrings.map { Self.normalize($0) }.filter { !$0.isEmpty }
            let combinedDirect = normalizedDirect.joined(separator: " ")
            let combinedSubtree = normalizedSubtree.joined(separator: " ")

            guard !combinedSubtree.isEmpty else { return nil }

            let exactDirectMatch = normalizedCandidates.contains { candidate in
                combinedDirect == candidate || combinedDirect.contains(candidate)
            }
            let exactSubtreeMatch = normalizedCandidates.contains { candidate in
                combinedSubtree == candidate || combinedSubtree.contains(candidate)
            }

            let tokenMatch: Bool = {
                switch tokenKind {
                case .generic:
                    return false
                case .date:
                    return exactDirectMatch
                        || exactSubtreeMatch
                        || normalizedQueryTokens.contains(where: { combinedSubtree.contains($0) })
                case .sender, .subject, .attachment:
                    let hasFieldTokens = normalizedFieldTokens.allSatisfy { combinedSubtree.contains($0) }
                    let hasQueryTokens =
                        !normalizedQueryTokens.isEmpty
                        && normalizedQueryTokens.allSatisfy { combinedSubtree.contains($0) }
                    return exactDirectMatch || exactSubtreeMatch || (hasFieldTokens && hasQueryTokens)
                }
            }()

            guard tokenMatch else { return nil }

            var score = 0
            if exactDirectMatch { score += 240 }
            if exactSubtreeMatch { score += 180 }
            if Self.isActionRole(role) { score += 120 }
            if role == "AXStaticText" { score -= 240 }
            if role == "AXRow" { score += 80 }
            if role == "AXMenuItem" || role == "AXListItem" || role == "AXCell" { score += 60 }
            if role == "AXGroup" || role == "AXButton" { score += 40 }
            if actionNames.contains(kAXPressAction as String) { score += 30 }
            if actionNames.contains(kAXConfirmAction as String) { score += 15 }
            if combinedDirect.contains(normalizedQuery) { score += 20 }
            if combinedSubtree.contains(normalizedQuery) { score += 10 }
            return score
        }
    }

    private func bestMailSuggestionTarget(
        in element: AXUIElement,
        matcher: MailSuggestionMatcher,
        depth: Int = 0
    ) -> (element: AXUIElement, score: Int)? {
        guard depth < 10 else { return nil }

        let role = axStringAttribute(element, kAXRoleAttribute as CFString) ?? ""
        let actionNames = axStringArrayAttribute(element, "AXActions" as CFString)
        let directStrings = axSearchableStrings(for: element)
        let subtreeStrings =
            isMailSuggestionActionRole(role)
            ? axSubtreeSearchableStrings(for: element)
            : directStrings

        var best: (element: AXUIElement, score: Int)?
        if let score = matcher.score(
            role: role,
            actionNames: actionNames,
            directStrings: directStrings,
            subtreeStrings: subtreeStrings
        ) {
            best = (element, score)
        }

        for child in axChildElements(element) {
            guard let childBest = bestMailSuggestionTarget(
                in: child,
                matcher: matcher,
                depth: depth + 1
            ) else { continue }

            if let currentBest = best {
                if childBest.score > currentBest.score {
                    best = childBest
                }
            } else {
                best = childBest
            }
        }

        return best
    }

    private func pressMailSuggestion(
        in element: AXUIElement,
        matcher: MailSuggestionMatcher,
        depth: Int = 0
    ) -> Bool {
        guard depth == 0 else { return false }
        guard let best = bestMailSuggestionTarget(in: element, matcher: matcher) else { return false }

        if AXUIElementPerformAction(best.element, kAXPressAction as CFString) == .success {
            return true
        }
        if AXUIElementPerformAction(best.element, kAXConfirmAction as CFString) == .success {
            return true
        }

        for child in axChildElements(best.element) {
            if AXUIElementPerformAction(child, kAXPressAction as CFString) == .success {
                return true
            }
            if AXUIElementPerformAction(child, kAXConfirmAction as CFString) == .success {
                return true
            }
        }
        return false
    }

    private func applyMailSearchTokenIntent(_ intent: MailSearchIntent, in pid: pid_t) async -> Bool {
        let candidates: [String] = {
            switch intent.tokenKind {
            case .generic:
                return []
            case .sender:
                return ["Sender contains: \(intent.query)"]
            case .subject:
                return ["Subject contains: \(intent.query)"]
            case .attachment:
                return ["Attachment name contains: \(intent.query)"]
            case .date:
                return mailDateSuggestionCandidates(for: intent.query)
            }
        }()

        guard !candidates.isEmpty else { return true }
        let matcher = MailSuggestionMatcher(intent: intent, candidates: candidates)

        for _ in 0..<12 {
            let appElement = AXUIElementCreateApplication(pid)
            if pressMailSuggestion(in: appElement, matcher: matcher) {
                return true
            }
            try? await Task.sleep(nanoseconds: 90_000_000)
        }

        return false
    }

    private func injectMailSearchQuery(_ query: String, into pid: pid_t) async -> Bool {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }

        for _ in 0..<18 {
            if let focusedElement = currentFocusedElement(in: pid),
                isEditableAXElement(focusedElement)
            {
                let didSetAXValue = setAXTextValue(trimmed, on: focusedElement)
                let didTypeValue =
                    didSetAXValue
                    ? false
                    : await typeMailSearchQuery(trimmed, into: focusedElement, pid: pid)
                if didSetAXValue || didTypeValue {
                    postKeyCode(36, to: pid)
                    return true
                }
            }

            let appElement = AXUIElementCreateApplication(pid)
            if let searchField = findMailSearchField(in: appElement) {
                let didSetAXValue = setAXTextValue(trimmed, on: searchField)
                let didTypeValue =
                    didSetAXValue
                    ? false
                    : await typeMailSearchQuery(trimmed, into: searchField, pid: pid)
                if didSetAXValue || didTypeValue {
                    postKeyCode(36, to: pid)
                    return true
                }
            }

            try? await Task.sleep(nanoseconds: 100_000_000)
        }

        return false
    }

    private func executeMailMailboxSearch(intent: MailSearchIntent, userMessage: String) {
        let searchQuery = intent.query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !searchQuery.isEmpty else { return }

        if let existingTask = l2CurrentTask {
            existingTask.cancel()
            l2CurrentTask = nil
            l2IsLoading = false
            l2ActiveRequestID = nil
        }

        l2ChatMessages.append(AIChatMessage(role: .user, content: userMessage))
        l2IsLoading = true

        l2CurrentTask = Task {
            guard let mailApp = await activateOrLaunchSemanticApp(
                bundleIdentifier: "com.apple.mail",
                appName: "Mail"
            ) else {
                await MainActor.run {
                    l2ChatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: "❌ Couldn't open Mail.",
                            isError: true
                        ))
                    l2IsLoading = false
                    l2CurrentTask = nil
                }
                return
            }

            let pid = mailApp.processIdentifier
            try? await Task.sleep(nanoseconds: 220_000_000)

            let liveItems = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            let mailboxSearchPath =
                liveItems.first(where: { item in
                    normalizedDockPillText(item.title) == "mailbox search"
                        || normalizedDockPillText(item.path.joined(separator: " ")) ==
                            "edit find mailbox search"
                })?.path

            var triggeredSearch = false
            if let mailboxSearchPath {
                triggeredSearch = AXMenuReader.shared.clickMenuItem(path: mailboxSearchPath, in: pid)
            }
            if !triggeredSearch {
                AXMenuReader.shared.executeShortcut(char: "f", modifiers: 2, in: pid)
                triggeredSearch = true
            }

            guard triggeredSearch else {
                await MainActor.run {
                    l2ChatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: "❌ Couldn't open Mail search.",
                            isError: true
                        ))
                    l2IsLoading = false
                    l2CurrentTask = nil
                }
                return
            }

            let injected = await injectMailSearchQuery(searchQuery, into: pid)
            let appliedToken = injected ? await applyMailSearchTokenIntent(intent, in: pid) : false

            await MainActor.run {
                if injected {
                    l2ChatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: appliedToken && intent.tokenKind != .generic
                                ? "Opened Mailbox Search for \(intent.displayLabel)."
                                : "Opened Mailbox Search for “\(searchQuery)”."
                        ))
                    searchText = ""
                    focusedPillIndex = nil
                } else {
                    l2ChatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content:
                                "⚠️ Opened Mail search, but couldn't inject the query automatically.",
                            isError: true
                        ))
                }
                l2IsLoading = false
                l2CurrentTask = nil
            }
        }
    }

    private func makeMessagesSemanticIntentPill(
        fullQuery: String,
        rawScopedQuery: String,
        scopedBundleId: String,
        scopedAppName: String
    ) -> DockPill? {
        guard let intent = messagesScopedSemanticIntent(for: rawScopedQuery),
            let recipientName = intent.recipientName?.trimmingCharacters(in: .whitespacesAndNewlines),
            let messageBody = intent.messageBody?.trimmingCharacters(in: .whitespacesAndNewlines),
            !recipientName.isEmpty,
            !messageBody.isEmpty
        else { return nil }

        let rawUserQuery = rawDockQuery(matching: fullQuery)
        let bodyLabel = messageIntentDisplayText(messageBody, limit: 36)
        let recipientLabel = messageIntentDisplayText(recipientName, limit: 26)

        var pill = DockPill(
            id: "messages-intent-send-\(normalizedDockPillText(rawScopedQuery))",
            name: "Send \"\(bodyLabel)\" to \(recipientLabel)",
            icon: "message.fill",
            accentColorName: "green",
            badge: "Conversation",
            execute: {
                self.executeCrossAppIntent(
                    intent,
                    userMessage: rawUserQuery,
                    unresolvedMessage: "❌ Couldn't resolve that Messages recipient. Try: message send \"hi\" to [name]"
                )
            }
        )
        pill.sourceBundleId = scopedBundleId
        pill.sourceAppName = scopedAppName
        pill.rankingKind = "semanticIntent"
        pill.trackingIdentifier =
            "messages-intent:\(normalizedDockPillText(recipientName)):\(normalizedDockPillText(messageBody))"
        pill.searchTerms = [
            scopedAppName, "messages", "message", "send", recipientName, messageBody, "conversation"
        ]
        return pill
    }

    private func makeMailSemanticSearchPill(
        fullQuery: String,
        rawScopedQuery: String,
        scopedBundleId: String,
        scopedAppName: String
    ) -> DockPill? {
        guard let intent = mailSemanticSearchIntent(from: rawScopedQuery) else { return nil }

        let rawUserQuery = rawDockQuery(matching: fullQuery)
        let queryLabel = messageIntentDisplayText(intent.displayLabel, limit: 42)

        var pill = DockPill(
            id: "mail-search-\(normalizedDockPillText(rawScopedQuery))",
            name: "Search Mail for \"\(queryLabel)\"",
            icon: "magnifyingglass",
            accentColorName: "blue",
            badge: "Mailbox",
            execute: {
                self.executeMailMailboxSearch(
                    intent: intent,
                    userMessage: rawUserQuery
                )
            }
        )
        pill.sourceBundleId = scopedBundleId
        pill.sourceAppName = scopedAppName
        pill.rankingKind = "semanticIntent"
        pill.trackingIdentifier =
            "mail-search:\(intent.tokenKind):\(normalizedDockPillText(intent.query))"
        pill.searchTerms = [scopedAppName, "mail", "mailbox", "search", "find", intent.query]
        return pill
    }

    private func buildPayloadActionPills(query: String) -> [DockPill] {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return [] }

        let selectedPaths = effectiveSelectedFileURLsForConversation().map(\.path)
        let selectedText = (axContext.selectedText ?? "").trimmingCharacters(
            in: .whitespacesAndNewlines)
        let currentURL = (axContext.currentURL ?? "").trimmingCharacters(
            in: .whitespacesAndNewlines)
        let windowTitle = (axContext.windowTitle ?? frontmostAppName).trimmingCharacters(
            in: .whitespacesAndNewlines)
        let clipboardText = (NSPasteboard.general.string(forType: .string) ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)

        let hasFiles = !selectedPaths.isEmpty
        let selectedURLs = selectedPaths.map { URL(fileURLWithPath: $0) }
        let hasText = !selectedText.isEmpty
        let hasURL = !currentURL.isEmpty
        let textPayload = hasText ? selectedText : clipboardText
        let noteBody = [hasText ? selectedText : nil, hasURL ? currentURL : nil]
            .compactMap { $0 }
            .joined(separator: "\n\n")
        let reminderText = !textPayload.isEmpty ? textPayload : windowTitle
        let downloadsPath = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent(
            "Downloads")

        func matches(_ terms: [String]) -> Bool {
            terms.contains { q.contains($0) || $0.contains(q) }
        }

        var pills: [DockPill] = []

        if hasText || hasURL, matches(["notes", "note", "quick note", "save note", "capture"]) {
            pills.append(
                DockPill(
                    id: "payload-notes",
                    name: "Save to Notes",
                    icon: "note.text",
                    accentColorName: "yellow",
                    badge: hasText ? "Selection" : "URL",
                    execute: {
                        guard self.settings.allowAutomation else {
                            self.l2ChatMessages.append(
                                AIChatMessage(
                                    role: .assistant,
                                    content: "Automation permission is disabled for Notes actions.",
                                    isError: true))
                            return
                        }
                        let title = windowTitle.isEmpty ? "Context Capture" : windowTitle
                        let ok: Bool
                        if !noteBody.isEmpty {
                            ok = AppleAppsAPI.shared.createNote(
                                title: title, body: noteBody, folder: "Context Dock")
                        } else {
                            ok = false
                        }
                        self.l2ChatMessages.append(
                            AIChatMessage(
                                role: .assistant,
                                content: ok ? "Saved to Notes." : "Failed to save to Notes.",
                                isError: !ok
                            ))
                    }
                ))
        }

        if hasText || hasURL || hasFiles,
            matches(["mail", "email", "compose", "new mail", "send email", "share via mail"])
        {
            pills.append(
                DockPill(
                    id: "payload-mail",
                    name: hasFiles ? "Share via Mail" : "Compose Mail",
                    icon: "envelope",
                    accentColorName: "blue",
                    badge: hasFiles ? "Files" : "Selection",
                    execute: {
                        self.executeShareIntent(
                            ShareIntent(
                                rawQuery: hasFiles ? "share via mail" : "compose mail",
                                channelHint: .mail,
                                recipientQuery: nil
                            )
                        )
                    }
                ))
        }

        if !textPayload.isEmpty || hasURL, matches(["reminder", "remind", "todo", "task"]) {
            pills.append(
                DockPill(
                    id: "payload-reminder",
                    name: "Create Reminder",
                    icon: "checklist",
                    accentColorName: "orange",
                    badge: "Selection",
                    execute: {
                        guard self.settings.allowAutomation else {
                            self.l2ChatMessages.append(
                                AIChatMessage(
                                    role: .assistant,
                                    content:
                                        "Automation permission is disabled for Reminders actions.",
                                    isError: true))
                            return
                        }
                        let ok = AppleAppsAPI.shared.createReminder(title: reminderText)
                        self.l2ChatMessages.append(
                            AIChatMessage(
                                role: .assistant,
                                content: ok ? "Reminder created." : "Failed to create reminder.",
                                isError: !ok
                            ))
                    }
                ))
        }

        if hasText || hasURL || hasFiles,
            matches(["message", "messages", "imessage", "new message", "send message"])
        {
            pills.append(
                DockPill(
                    id: "payload-messages",
                    name: "Send via Messages",
                    icon: "message",
                    accentColorName: "green",
                    badge: hasFiles ? "Files" : "Share",
                    execute: {
                        self.executeShareIntent(
                            ShareIntent(
                                rawQuery: hasFiles ? "send via messages" : "send this via messages",
                                channelHint: .messages,
                                recipientQuery: nil
                            )
                        )
                    }
                ))
        }

        if hasFiles, matches(["downloads", "download", "move to downloads", "send to downloads"]) {
            pills.append(
                DockPill(
                    id: "payload-downloads-move",
                    name: "Move to Downloads",
                    icon: "arrow.down.circle",
                    accentColorName: "teal",
                    badge: "\(selectedPaths.count)",
                    execute: {
                        let fm = FileManager.default
                        try? fm.createDirectory(
                            at: downloadsPath, withIntermediateDirectories: true)
                        var moved = 0
                        for source in selectedURLs {
                            let destination = downloadsPath.appendingPathComponent(
                                source.lastPathComponent)
                            let uniqueDestination = self.uniqueMoveDestination(for: destination)
                            do {
                                try fm.moveItem(at: source, to: uniqueDestination)
                                moved += 1
                            } catch {
                                continue
                            }
                        }
                        let ok = moved > 0
                        self.l2ChatMessages.append(
                            AIChatMessage(
                                role: .assistant,
                                content: ok
                                    ? "Moved \(moved) item\(moved == 1 ? "" : "s") to Downloads."
                                    : "Failed to move items to Downloads.",
                                isError: !ok
                            ))
                    }
                ))
            pills.append(
                DockPill(
                    id: "payload-downloads-open",
                    name: "Open Downloads",
                    icon: "folder",
                    accentColorName: "gray",
                    badge: "Downloads",
                    execute: {
                        NSWorkspace.shared.open(downloadsPath)
                    }
                ))
        }

        if hasFiles, matches(["share", "send", "export"]) {
            pills.append(
                DockPill(
                    id: "payload-share-files",
                    name: "Share Selected Files",
                    icon: "square.and.arrow.up",
                    accentColorName: "blue",
                    badge: "\(selectedPaths.count)",
                    execute: {
                        self.executeShareIntent(
                            ShareIntent(
                                rawQuery: "share selected files",
                                channelHint: .picker,
                                recipientQuery: nil
                            )
                        )
                    }
                ))
        }

        return pills
    }

    private func uniqueMoveDestination(for desiredURL: URL) -> URL {
        let fm = FileManager.default
        guard fm.fileExists(atPath: desiredURL.path) else { return desiredURL }

        let directory = desiredURL.deletingLastPathComponent()
        let baseName = desiredURL.deletingPathExtension().lastPathComponent
        let ext = desiredURL.pathExtension

        for index in 2...500 {
            let candidateName = ext.isEmpty ? "\(baseName) \(index)" : "\(baseName) \(index).\(ext)"
            let candidate = directory.appendingPathComponent(candidateName)
            if !fm.fileExists(atPath: candidate.path) {
                return candidate
            }
        }

        return desiredURL
    }

    private func detectCrossAppQuery(_ q: String) -> (NSRunningApplication, String)? {
        guard !q.isEmpty, let delegate = AppDelegate.shared else { return nil }
        let recentApps = delegate.recentApps.filter { !$0.isTerminated }
        let frontPID = delegate.previousFrontmostApp?.processIdentifier ?? 0
        for app in recentApps {
            guard app.processIdentifier != frontPID else { continue }
            let name = (app.localizedName ?? "").lowercased()
            guard !name.isEmpty else { continue }
            // Require a space after the app name so single-word queries like "centre"
            // never accidentally match a recent app whose name starts with "cent" etc.
            if q.hasPrefix(name + " ") {
                let remainder = String(q.dropFirst(name.count + 1))
                return (app, remainder)
            }
            // Also match shortened names: "safari close tab" matches "Safari Technology Preview"
            let firstWord = name.components(separatedBy: " ").first ?? name
            if firstWord.count >= 3, q.hasPrefix(firstWord + " ") {
                let remainder = String(q.dropFirst(firstWord.count + 1))
                return (app, remainder)
            }
        }
        return nil
    }

    private func installedAppMenuTarget(for query: String) -> InstalledAppMenuTarget? {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard q.count >= 2 else { return nil }

        var best: (target: InstalledAppMenuTarget, score: Int)?

        for result in allApplications where result.type == .application {
            let appName = result.title.trimmingCharacters(in: .whitespacesAndNewlines)
            let appPath = result.subtitle
            guard !appName.isEmpty, !appPath.isEmpty else { continue }

            let bundleId = Bundle(url: URL(fileURLWithPath: appPath))?.bundleIdentifier ?? ""
            guard !bundleId.isEmpty else { continue }
            guard AppMenuCapabilityCache.shared.hasSnapshot(bundleIdentifier: bundleId) else {
                continue
            }

            let normalizedName = appName.lowercased()
                .replacingOccurrences(of: "[^a-z0-9]+", with: " ", options: .regularExpression)
                .trimmingCharacters(in: .whitespacesAndNewlines)
            guard !normalizedName.isEmpty else { continue }

            var aliases = Set<String>()
            aliases.insert(normalizedName)
            if let first = normalizedName.split(separator: " ").first {
                aliases.insert(String(first))
            }
            if normalizedName.hasSuffix("s"), normalizedName.count > 3 {
                aliases.insert(String(normalizedName.dropLast()))
            }

            for alias in aliases where alias.count >= 2 {
                let actionQuery: String
                let score: Int
                if q == alias {
                    actionQuery = ""
                    score = 100 + alias.count
                } else if q.hasPrefix(alias + " ") {
                    actionQuery = String(q.dropFirst(alias.count + 1))
                        .trimmingCharacters(in: .whitespacesAndNewlines)
                    score = 120 + alias.count + min(actionQuery.count, 20)
                } else {
                    continue
                }

                let target = InstalledAppMenuTarget(
                    appName: appName,
                    bundleId: bundleId,
                    appPath: appPath,
                    actionQuery: actionQuery,
                    matchedAlias: alias
                )
                if best == nil || score > best!.score {
                    best = (target, score)
                }
            }
        }

        return best?.target
    }

    private func resolveDockScope(for query: String) -> DockScopeResolution {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let explicitAppTarget = q.isEmpty ? nil : L2AppActionRouter.shared.appScopeTarget(for: q)
        let installedMenuTarget =
            (explicitAppTarget == nil && l2TargetApp == nil)
            ? installedAppMenuTarget(for: q)
            : nil
        let isExplicitAppScope =
            l2TargetApp != nil || explicitAppTarget != nil || installedMenuTarget != nil
        let isGlobalScope = isGlobalContextActive && !isExplicitAppScope

        if isGlobalScope {
            return DockScopeResolution(
                scopedBundleId: "",
                scopedAppName: "Global Context",
                scopedSearchQuery: q,
                isExplicitAppScope: false,
                isGlobalScope: true
            )
        }

        let scopedBundleId =
            l2TargetApp?.bundleId
            ?? explicitAppTarget?.bundleId
            ?? installedMenuTarget?.bundleId
            ?? (frontmostAppBundleID.isEmpty ? axContext.bundleId : frontmostAppBundleID)
        let scopedAppName =
            l2TargetApp?.name
            ?? explicitAppTarget?.appName
            ?? installedMenuTarget?.appName
            ?? contextTargetApp()?.localizedName
            ?? axContext.appName
        let scopedSearchQuery =
            explicitAppTarget?.actionQuery
            ?? installedMenuTarget?.actionQuery
            ?? q

        return DockScopeResolution(
            scopedBundleId: scopedBundleId,
            scopedAppName: scopedAppName,
            scopedSearchQuery: scopedSearchQuery,
            isExplicitAppScope: isExplicitAppScope,
            isGlobalScope: false
        )
    }

    private func isPureScopedAppSelection(for query: String) -> Bool {
        let scope = resolveDockScope(for: query)
        return scope.isExplicitAppScope
            && scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private var dockScopeDisplayName: String {
        let scope = resolveDockScope(for: searchText)
        if scope.isGlobalScope {
            return "Global Context"
        }
        if scope.isExplicitAppScope {
            let scoped = scope.scopedAppName.trimmingCharacters(in: .whitespacesAndNewlines)
            if !scoped.isEmpty {
                return scoped
            }
        }
        return frontmostAppName
    }

    private var dockHeaderDisplayName: String {
        let label = dockScopeDisplayName.trimmingCharacters(in: .whitespacesAndNewlines)
        return label.isEmpty ? "Context" : label
    }

    private func finderDisplayPath(_ path: String) -> String {
        path.replacingOccurrences(of: NSHomeDirectory(), with: "~")
    }

    private func scopedDockWorkspaceKey(bundleIdentifier: String, appName: String) -> String {
        if let mapped = settings.appKey(forBundleID: bundleIdentifier, appName: appName),
            !mapped.isEmpty
        {
            return mapped
        }
        let normalized = appName
            .lowercased()
            .replacingOccurrences(of: " ", with: "_")
            .components(
                separatedBy: CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "_"))
                    .inverted
            )
            .joined()
        return normalized.isEmpty ? bundleIdentifier : normalized
    }

    private var currentL2DockSessionKey: String? {
        guard showContextInDock else { return nil }
        let scope = resolveDockScope(for: searchText)
        if scope.isGlobalScope {
            return "dock_global"
        }
        let scopedBundleId = scope.scopedBundleId.trimmingCharacters(in: .whitespacesAndNewlines)
        if !scopedBundleId.isEmpty {
            return "dock_app_\(scopedBundleId)"
        }
        let appName = scope.scopedAppName.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !appName.isEmpty else { return nil }
        return "dock_app_\(scopedDockWorkspaceKey(bundleIdentifier: appName, appName: appName))"
    }

    private func syncL2DockSession(force: Bool = false) {
        let newKey = currentL2DockSessionKey
        guard force || newKey != activeL2DockSessionKey else { return }

        if let previousKey = activeL2DockSessionKey {
            AppPanelChatStore.shared.save(l2ChatMessages, for: previousKey)
        }

        activeL2DockSessionKey = newKey
        l2CurrentTask?.cancel()
        l2CurrentTask = nil
        l2IsLoading = false
        l2ActiveRequestID = nil
        l2ChatMessages = newKey.map { AppPanelChatStore.shared.load(for: $0) } ?? []
        updateL2Results([])
    }

    @discardableResult
    private func activateInlineDockAppScope(
        bundleIdentifier: String,
        appName: String,
        searchTextOverride: String? = nil,
        expand: Bool = true
    ) -> Bool {
        guard !bundleIdentifier.isEmpty, !appName.isEmpty else { return false }

        let targetApp = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
        })
        let appURL = applicationURL(bundleIdentifier: bundleIdentifier, appName: appName)
        let appPath = appURL?.path ?? ""
        let icon =
            !appPath.isEmpty
            ? NSWorkspace.shared.icon(forFile: appPath)
            : (
                resolvedApplicationIcon(bundleIdentifier: bundleIdentifier, appName: appName)
                    ?? preparedDockIcon(targetApp?.icon)
            )
        let hasLegacyPanelState =
            activeSmartQueryKey != nil
            || searchContextApp != nil
            || isInSmartMode
            || !appPanelAllItems.isEmpty
            || !remPanelChatMessages.isEmpty
        let isNewScope = l2TargetApp?.bundleId != bundleIdentifier
        let shouldSyncSession =
            isNewScope
            || activeSmartQueryKey != nil
            || searchContextApp != nil
        // Reset terminal dismissal when switching to a different app scope
        if isNewScope { l2TerminalDismissed = false }
        let normalizedOverride = searchTextOverride?
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased() ?? ""
        let isPureScopeSelection =
            normalizedOverride.isEmpty
            || isPureScopedAppSelection(for: normalizedOverride)

        if let previousKey = activeSmartQueryKey, hasLegacyPanelState {
            AppPanelChatStore.shared.save(remPanelChatMessages, for: previousKey)
        }

        if hasLegacyPanelState {
            remPanelAITask?.cancel()
            remPanelIsProcessing = false
        }

        withAnimation(.spring(response: 0.22, dampingFraction: 0.84)) {
            if hasLegacyPanelState {
                searchContextApp = nil
                activeSmartQueryKey = nil
                isInSmartMode = false
                appPanelAllItems = []
                remPanelChatMessages = []
                clearPinnedResults()
            }
            l2TargetApp = (appName, icon, bundleIdentifier)
            showContextInDock = true
            showMediaLayer = false
            isAIMode = false
            searchResults = []
            selectedResultIndex = nil
            if expand { isSearchBarExpanded = true }
            if expand {
                if livePanelMode != .terminal { livePanelVisible = false }
            }
            if let searchTextOverride {
                searchText = searchTextOverride
            }
        }

        if let targetApp {
            seedCrossAppMenuCache(for: targetApp)
            loadCrossAppMenu(for: targetApp)  // always read + persist all menus on scope
        } else {
            crossAppMenuTargetPID = 0
            crossAppMenuItems = []
            crossAppMenuNeedsLiveLoad = false
        }

        if shouldSyncSession {
            syncL2DockSession(force: true)
        }

        // Pre-warm the scoped terminal PTY so it's ready when a command needs to run.
        // Do NOT open or show the terminal here — it only appears after the user approves a command.
        let hasAnyCLI = !terminalPackageManager.packages(
            forContextBundleId: bundleIdentifier, query: "", maxResults: 1).isEmpty
            || adapterManager.actions(for: bundleIdentifier)
                .contains { $0.type == .cliTool && !($0.cliToolCommand ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
        if hasAnyCLI {
            _ = prepareScopedWorkspaceTerminal()
        }

        focusedPillIndex = nil
        isSearchFieldFocused = true
        return true
    }

    private func scopedWorkspaceIdentity() -> (appName: String, bundleId: String, axContext: AXContext)? {
        if let target = l2TargetApp, !target.bundleId.isEmpty {
            return (
                target.name,
                target.bundleId,
                scopedWorkspaceAXContext(appName: target.name, bundleId: target.bundleId)
            )
        }

        if let ctx = searchContextApp {
            let bundleIdFromPath = ctx.appPath.isEmpty ? nil : Bundle(path: ctx.appPath)?.bundleIdentifier
            let bundleIdFromRunningApp = NSWorkspace.shared.runningApplications.first(where: {
                !$0.isTerminated && $0.localizedName == ctx.name
            })?.bundleIdentifier
            let resolvedBundleId = bundleIdFromPath ?? bundleIdFromRunningApp ?? ""
            if !resolvedBundleId.isEmpty {
                return (
                    ctx.name,
                    resolvedBundleId,
                    scopedWorkspaceAXContext(appName: ctx.name, bundleId: resolvedBundleId)
                )
            }
        }

        let meta = smartQueryMeta
        if !meta.appPath.isEmpty, let bundleId = Bundle(path: meta.appPath)?.bundleIdentifier {
            return (
                searchContextApp?.name ?? meta.label,
                bundleId,
                scopedWorkspaceAXContext(
                    appName: searchContextApp?.name ?? meta.label,
                    bundleId: bundleId
                )
            )
        }

        let fallbackBundleId =
            frontmostAppBundleID.isEmpty ? axContext.bundleId : frontmostAppBundleID
        let fallbackAppName =
            searchContextApp?.name
            ?? (frontmostAppName.isEmpty ? axContext.appName : frontmostAppName)
        guard !fallbackBundleId.isEmpty, !fallbackAppName.isEmpty else { return nil }
        return (
            fallbackAppName,
            fallbackBundleId,
            scopedWorkspaceAXContext(appName: fallbackAppName, bundleId: fallbackBundleId)
        )
    }

    private func scopedWorkspaceAXContext(appName: String, bundleId: String) -> AXContext {
        if axContext.bundleId == bundleId {
            return effectiveAXContextForConversation()
        }

        let runningApp = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == bundleId && !$0.isTerminated
        })

        return AXContext(
            appName: appName,
            bundleId: bundleId,
            pid: runningApp?.processIdentifier ?? 0,
            selectedText: nil,
            currentURL: nil,
            windowTitle: nil,
            focusedElementRole: nil,
            selectedFilePaths: effectiveSelectedFileURLsForConversation().map(\.path),
            menuItems: []
        )
    }

    private func prepareScopedWorkspaceTerminal() -> String {
        let consoleKey = activeConsoleKey
        let terminal = panelTerminal(for: consoleKey)
        TerminalAIBridge.shared.terminalController = terminal
        panelShowConsoleMap[consoleKey] = true
        return consoleKey
    }

    private func currentDateTimeContextBlock() -> String {
        let now = Date()
        let formatter = DateFormatter()
        formatter.dateStyle = .full
        formatter.timeStyle = .medium
        let localDateTime = formatter.string(from: now)
        let isoFormatter = ISO8601DateFormatter()
        isoFormatter.timeZone = .current
        let isoDateTime = isoFormatter.string(from: now)
        let timeZoneName = TimeZone.current.identifier

        return """
            CURRENT DATE & TIME:
            - Local: \(localDateTime)
            - ISO 8601: \(isoDateTime)
            - Time Zone: \(timeZoneName)
            Use this exact date/time for relative time references like today, yesterday, tomorrow, recent, and this week.
            """
    }

    private func canonicalExistingURLs(_ urls: [URL]) -> [URL] {
        var seen: Set<String> = []
        return urls.filter { url in
            let path = url.standardizedFileURL.path
            guard !path.isEmpty else { return false }
            guard FileManager.default.fileExists(atPath: path) else { return false }
            return seen.insert(path).inserted
        }
    }

    private func clearFinderFollowUpTargets() {
        finderFollowUpTargetPaths = []
        finderFollowUpFolderPath = ""
        finderFollowUpSourceQuery = ""
    }

    private func rememberFinderFollowUpTargets(
        _ urls: [URL],
        folderPath: String,
        sourceQuery: String = ""
    ) {
        let canonical = canonicalExistingURLs(urls)
        guard !canonical.isEmpty else { return }
        finderFollowUpTargetPaths = canonical.map(\.path)
        finderFollowUpFolderPath = folderPath
        finderFollowUpSourceQuery = sourceQuery
    }

    private func finderFollowUpTargetURLs(for folderPath: String? = nil) -> [URL] {
        guard !finderFollowUpTargetPaths.isEmpty else { return [] }
        if let folderPath,
            !folderPath.isEmpty,
            !finderFollowUpFolderPath.isEmpty,
            finderFollowUpFolderPath != folderPath
        {
            return []
        }
        return canonicalExistingURLs(finderFollowUpTargetPaths.map { URL(fileURLWithPath: $0) })
    }

    private func queryNeedsFinderFollowUpTargets(_ query: String) -> Bool {
        let normalized = normalizedDockPillText(query)
        guard !normalized.isEmpty else { return false }

        let tokens = Set(dockPillTokens(normalized))
        let pronounTerms: Set<String> = [
            "it", "them", "this", "that", "these", "those", "same", "again",
            "selected", "selection", "current"
        ]
        if !tokens.isDisjoint(with: pronounTerms) { return true }

        let actionTerms = [
            "share", "send", "mail", "email", "message", "open", "convert", "export",
            "save", "move", "copy", "duplicate", "rename", "compress", "zip", "print",
            "preview", "reveal", "quick look", "attach", "upload", "delete", "trash",
            "remove", "merge", "split", "extract", "encode", "transcode"
        ]
        let hasActionIntent = actionTerms.contains { normalized.contains($0) }
        let hasExplicitTarget = !finderTargetReferenceQuery(from: normalized).isEmpty
        return hasActionIntent && !hasExplicitTarget
    }

    private func effectiveFinderSelectedFileURLs(for query: String, currentFolderPath: String)
        -> [URL]
    {
        let liveSelection = canonicalExistingURLs(
            axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        )
        if !liveSelection.isEmpty {
            rememberFinderFollowUpTargets(
                liveSelection,
                folderPath: currentFolderPath,
                sourceQuery: query
            )
            return liveSelection
        }

        if case .filesSelected(let urls) = currentContext {
            let contextURLs = canonicalExistingURLs(urls)
            if !contextURLs.isEmpty {
                let normalizedCurrentFolderPath =
                    URL(fileURLWithPath: currentFolderPath).standardizedFileURL.path
                let isStaleAttachedFolderContext =
                    contextURLs.count == 1
                    && contextURLs[0].hasDirectoryPath
                    && contextURLs[0].standardizedFileURL.path == attachedFinderFolderSearchPath
                    && attachedFinderFolderSearchPath != normalizedCurrentFolderPath
                guard !isStaleAttachedFolderContext else { return [] }

                rememberFinderFollowUpTargets(
                    contextURLs,
                    folderPath: currentFolderPath,
                    sourceQuery: query
                )
                return contextURLs
            }
        }

        guard queryNeedsFinderFollowUpTargets(query) else { return [] }
        return finderFollowUpTargetURLs(for: currentFolderPath)
    }

    private func effectiveSelectedFileURLsForConversation() -> [URL] {
        let liveSelection = canonicalExistingURLs(
            axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        )
        if !liveSelection.isEmpty { return liveSelection }

        if case .filesSelected(let urls) = currentContext {
            let contextURLs = canonicalExistingURLs(urls)
            if !contextURLs.isEmpty { return contextURLs }
        }

        guard frontmostAppBundleID == "com.apple.finder"
            || contextTargetApp()?.bundleIdentifier == "com.apple.finder"
        else { return [] }

        if isFinderFolderSearchAttached(currentFolderPath: currentFinderFolderPath()) {
            let folderURL = URL(fileURLWithPath: attachedFinderFolderSearchPath)
            if FileManager.default.fileExists(atPath: folderURL.path) {
                return [folderURL]
            }
        }

        return finderFollowUpTargetURLs(for: currentFinderFolderPath())
    }

    private func effectiveAXContextForConversation() -> AXContext {
        var context = axContext
        if context.selectedFilePaths.isEmpty {
            context.selectedFilePaths = effectiveSelectedFileURLsForConversation().map(\.path)
        }
        return context
    }

    private func finderTargetReferenceQuery(from query: String) -> String {
        let normalized = normalizedDockPillText(query)
        guard !normalized.isEmpty else { return "" }

        let ignoredWords: Set<String> = [
            "convert", "conversion", "export", "save", "open", "move", "copy", "duplicate",
            "share", "send", "attach", "upload", "rename", "delete", "trash", "remove",
            "reveal", "preview", "print", "merge", "split", "extract", "encode", "compress",
            "zip", "unzip", "transform", "change", "make", "create", "render", "transcode",
            "format", "into", "from", "with", "using", "via", "to", "as", "file", "files",
            "folder", "folders", "document", "documents", "image", "images", "photo", "photos",
            "picture", "pictures", "pdf", "png", "jpg", "jpeg", "webp", "heic", "gif", "tiff",
            "bmp", "selected", "selection", "current", "this", "that", "these", "those",
            "please", "here"
        ]

        let remaining = dockPillTokens(normalized).filter {
            !$0.isEmpty && !ignoredWords.contains($0) && $0.count >= 2
        }
        return remaining.joined(separator: " ")
    }

    private func finderMetadataSummary(for url: URL) -> String {
        let resourceValues =
            (try? url.resourceValues(
                forKeys: [
                    .isDirectoryKey, .localizedTypeDescriptionKey, .contentModificationDateKey,
                    .fileSizeKey,
                ])) ?? URLResourceValues()
        let isDirectory = resourceValues.isDirectory ?? url.hasDirectoryPath
        let typeLabel =
            resourceValues.localizedTypeDescription
            ?? (isDirectory ? "Folder" : (url.pathExtension.isEmpty ? "File" : "\(url.pathExtension.uppercased()) file"))
        let sizeLabel: String = {
            guard !isDirectory else { return "folder" }
            let byteCount = Int64(resourceValues.fileSize ?? 0)
            guard byteCount > 0 else { return "size unknown" }
            return ByteCountFormatter.string(fromByteCount: byteCount, countStyle: .file)
        }()
        let modifiedLabel: String = {
            guard let modified = resourceValues.contentModificationDate else { return "modified unknown" }
            let formatter = RelativeDateTimeFormatter()
            formatter.unitsStyle = .full
            return "modified " + formatter.localizedString(for: modified, relativeTo: Date())
        }()
        return "\(typeLabel) | \(sizeLabel) | \(modifiedLabel) | \(finderDisplayPath(url.path))"
    }

    private func buildFinderFileCatalogBlock(
        currentFolderPath: String,
        selectedFilePaths: [String]
    ) -> String {
        let folderURL = URL(fileURLWithPath: currentFolderPath)
        let fileManager = FileManager.default

        var orderedURLs = selectedFilePaths.map { URL(fileURLWithPath: $0) }
        if let currentItems = try? fileManager.contentsOfDirectory(
            at: folderURL,
            includingPropertiesForKeys: [.isDirectoryKey, .contentModificationDateKey],
            options: [.skipsHiddenFiles, .skipsPackageDescendants]
        ) {
            let sortedItems = currentItems.sorted { lhs, rhs in
                let lhsValues =
                    (try? lhs.resourceValues(forKeys: [.isDirectoryKey, .contentModificationDateKey]))
                    ?? URLResourceValues()
                let rhsValues =
                    (try? rhs.resourceValues(forKeys: [.isDirectoryKey, .contentModificationDateKey]))
                    ?? URLResourceValues()
                let lhsDirectory = lhsValues.isDirectory ?? lhs.hasDirectoryPath
                let rhsDirectory = rhsValues.isDirectory ?? rhs.hasDirectoryPath
                if lhsDirectory != rhsDirectory { return lhsDirectory && !rhsDirectory }
                let lhsDate = lhsValues.contentModificationDate ?? .distantPast
                let rhsDate = rhsValues.contentModificationDate ?? .distantPast
                if lhsDate != rhsDate { return lhsDate > rhsDate }
                return lhs.lastPathComponent.localizedCaseInsensitiveCompare(rhs.lastPathComponent)
                    == .orderedAscending
            }
            orderedURLs.append(contentsOf: sortedItems)
        }

        var seen: Set<String> = []
        let uniqueURLs = orderedURLs.filter { seen.insert($0.path).inserted }
        guard !uniqueURLs.isEmpty else { return "" }

        let limit = min(uniqueURLs.count, 40)
        let lines = uniqueURLs.prefix(limit).map { url in
            "- \(url.lastPathComponent) | \(finderMetadataSummary(for: url))"
        }

        var block = "\nCURRENT FOLDER FILE CATALOG:\n" + lines.joined(separator: "\n")
        if uniqueURLs.count > limit {
            block += "\n- ... and \(uniqueURLs.count - limit) more items in this folder"
        }
        return block
    }

    private func buildFinderTargetSemanticMatches(
        for query: String,
        currentFolderPath: String,
        spotlightEnabled: Bool
    ) async -> [FinderSemanticMatch] {
        let targetQuery = finderTargetReferenceQuery(from: query)
        guard !targetQuery.isEmpty, targetQuery != normalizedDockPillText(query) else { return [] }

        let fastMatches = await buildFastFinderSemanticMatches(
            query: targetQuery,
            currentFolderPath: currentFolderPath
        )
        let spotlightMatches =
            spotlightEnabled && targetQuery.count >= 3
            ? runFinderSpotlightSearch(
                query: targetQuery,
                currentFolderPath: currentFolderPath,
                limit: 8
            )
            : []
        return mergeFinderSemanticMatches(fastMatches, with: spotlightMatches)
    }

    private func buildFinderResolvedTargetContext(
        query: String,
        selectedFilePaths: [String],
        retrievedMatches: [FinderSemanticMatch]
    ) -> (targetURLs: [URL], summaryBlock: String, contentBlock: String) {
        let selectedURLs = selectedFilePaths.map { URL(fileURLWithPath: $0) }
        let candidateURLs: [URL] =
            !selectedURLs.isEmpty
            ? Array(selectedURLs.prefix(5))
            : Array(retrievedMatches.prefix(5).map { URL(fileURLWithPath: $0.path) })

        guard !candidateURLs.isEmpty else {
            return ([], "", "")
        }

        let summaryLines = candidateURLs.map { url in
            "- \(url.lastPathComponent) | \(finderMetadataSummary(for: url))"
        }
        let summaryBlock =
            "\nRESOLVED TARGET FILES FOR THIS QUERY:\n" + summaryLines.joined(separator: "\n")

        let analyzableURLs = candidateURLs.filter {
            let values =
                (try? $0.resourceValues(forKeys: [.isDirectoryKey])) ?? URLResourceValues()
            return !(values.isDirectory ?? $0.hasDirectoryPath)
        }
        let analyzedFiles = ContextDetector.shared.analyzeFiles(Array(analyzableURLs.prefix(2)))
        var contentBlock = ""
        for file in analyzedFiles {
            guard let content = file.content,
                !content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            else { continue }
            contentBlock +=
                "\n\n### Resolved target content from \(file.url.lastPathComponent):\n```\n\(String(content.prefix(2500)))\n```"
        }

        return (candidateURLs, summaryBlock, contentBlock)
    }

    private func finderSemanticCategoryTokens(_ category: FinderFileCategory) -> Set<String> {
        switch category {
        case .pdf:
            return ["pdf", "pdfs"]
        case .image:
            return ["image", "images", "photo", "photos", "picture", "pictures", "screenshot", "screenshots"]
        case .video:
            return ["video", "videos", "movie", "movies"]
        case .audio:
            return ["audio", "music", "song", "songs", "mp3"]
        case .archive:
            return ["archive", "archives", "zip", "zips", "dmg", "dmgs", "torrent", "torrents"]
        case .app:
            return ["app", "apps", "application", "applications"]
        case .folder:
            return ["folder", "folders", "directory", "directories"]
        case .document:
            return ["document", "documents", "doc", "docs", "text"]
        }
    }

    private func finderSemanticProfile(for query: String) -> FinderSemanticQueryProfile {
        let normalized = normalizedDockPillText(query)
        let tokens = dockPillTokens(normalized)
        let category = FinderFileCategory.detect(in: normalized)
        let wantsFoldersOnly =
            category == .folder || tokens.contains("folder") || tokens.contains("folders")
                || tokens.contains("directory") || tokens.contains("directories")
        let wantsFilesOnly =
            !wantsFoldersOnly
                && (tokens.contains("file") || tokens.contains("files")
                    || tokens.contains("item") || tokens.contains("items"))
        let wantsRecent =
            tokens.contains("recent") || tokens.contains("latest") || tokens.contains("newest")
        let wantsToday = tokens.contains("today") || tokens.contains("tonight")
        let wantsYesterday = tokens.contains("yesterday")
        let wantsThisWeek = tokens.contains("week") || normalized.contains("this week")
        let wantsLargeFiles =
            tokens.contains("large") || tokens.contains("larger") || tokens.contains("big")
                || tokens.contains("huge") || tokens.contains("largest")
        let wantsSmallFiles =
            tokens.contains("small") || tokens.contains("tiny") || tokens.contains("smallest")

        var semanticTokens: Set<String> = [
            "today", "tonight", "yesterday", "recent", "latest", "newest",
            "this", "week", "here", "current", "folder", "folders", "directory", "directories",
            "file", "files", "item", "items", "modified", "updated", "edited", "changed",
            "large", "larger", "big", "huge", "largest", "small", "tiny", "smallest"
        ]
        if let category {
            semanticTokens.formUnion(finderSemanticCategoryTokens(category))
        }

        let residualQuery = tokens.filter { !semanticTokens.contains($0) }.joined(separator: " ")
        return FinderSemanticQueryProfile(
            originalQuery: normalized,
            residualQuery: residualQuery,
            category: category,
            wantsFoldersOnly: wantsFoldersOnly,
            wantsFilesOnly: wantsFilesOnly,
            wantsRecent: wantsRecent,
            wantsToday: wantsToday,
            wantsYesterday: wantsYesterday,
            wantsThisWeek: wantsThisWeek,
            wantsLargeFiles: wantsLargeFiles,
            wantsSmallFiles: wantsSmallFiles
        )
    }

    private func finderSemanticDateInterval(for profile: FinderSemanticQueryProfile, now: Date)
        -> DateInterval?
    {
        let calendar = Calendar.current
        if profile.wantsToday {
            let start = calendar.startOfDay(for: now)
            guard let end = calendar.date(byAdding: .day, value: 1, to: start) else { return nil }
            return DateInterval(start: start, end: end)
        }
        if profile.wantsYesterday {
            let todayStart = calendar.startOfDay(for: now)
            guard
                let start = calendar.date(byAdding: .day, value: -1, to: todayStart)
            else { return nil }
            return DateInterval(start: start, end: todayStart)
        }
        if profile.wantsThisWeek {
            let components = calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: now)
            guard
                let start = calendar.date(from: components),
                let end = calendar.date(byAdding: .day, value: 7, to: start)
            else { return nil }
            return DateInterval(start: start, end: end)
        }
        return nil
    }

    private func finderSemanticConstraintBoost(
        for url: URL,
        profile: FinderSemanticQueryProfile,
        resourceValues: URLResourceValues,
        now: Date
    ) -> Double? {
        let isDirectory = resourceValues.isDirectory ?? url.hasDirectoryPath

        if profile.wantsFoldersOnly && !isDirectory { return nil }
        if profile.wantsFilesOnly && isDirectory { return nil }
        if let category = profile.category, !category.matches(url) { return nil }

        var score = 0.0
        var matchedAnyConstraint = false

        if profile.wantsFoldersOnly && isDirectory {
            matchedAnyConstraint = true
            score += 140
        }
        if profile.wantsFilesOnly && !isDirectory {
            matchedAnyConstraint = true
            score += 110
        }
        if let category = profile.category {
            matchedAnyConstraint = true
            score += category == .folder ? 150 : 125
        }

        if let interval = finderSemanticDateInterval(for: profile, now: now) {
            guard let modified = resourceValues.contentModificationDate,
                interval.contains(modified)
            else { return nil }
            matchedAnyConstraint = true
            score += profile.wantsToday ? 240 : 220
            let ageHours = max(0, now.timeIntervalSince(modified) / 3600)
            score += max(0, 36 - min(36, ageHours))
        } else if profile.wantsRecent {
            guard let modified = resourceValues.contentModificationDate else { return nil }
            matchedAnyConstraint = true
            let ageHours = max(0, now.timeIntervalSince(modified) / 3600)
            score += max(80, 240 - min(180, ageHours * 4))
        }

        let size = Int64(resourceValues.fileSize ?? 0)
        if profile.wantsLargeFiles {
            guard !isDirectory, size >= 5 * 1_024 * 1_024 else { return nil }
            matchedAnyConstraint = true
            score += 150 + min(180, Double(size) / 1_048_576.0)
        }
        if profile.wantsSmallFiles {
            guard !isDirectory, size > 0, size <= 1 * 1_024 * 1_024 else { return nil }
            matchedAnyConstraint = true
            score += 130 + max(0, 24 - Double(size) / 65_536.0)
        }

        return matchedAnyConstraint ? score : nil
    }

    private func finderSemanticScore(query: String, for url: URL) -> Double? {
        let normalizedQuery = normalizedDockPillText(query)
        guard !normalizedQuery.isEmpty else { return nil }

        let name = normalizedDockPillText(url.lastPathComponent)
        let path = normalizedDockPillText(url.path)
        guard !name.isEmpty || !path.isEmpty else { return nil }

        var bestScore: Double? = nil

        if name == normalizedQuery {
            bestScore = 1100
        } else if name.hasPrefix(normalizedQuery) {
            bestScore = 980 + Double(min(normalizedQuery.count, 12) * 6)
        } else if name.contains(normalizedQuery) {
            bestScore = 900 + Double(min(normalizedQuery.count, 10) * 4)
        }

        if path.contains(normalizedQuery) {
            bestScore = max(bestScore ?? 0, 820 + Double(min(normalizedQuery.count, 12) * 3))
        }

        let queryTerms = dockPillTokens(normalizedQuery).filter { $0.count >= 2 }
        if !queryTerms.isEmpty {
            let matchedTerms = queryTerms.filter { name.contains($0) || path.contains($0) }
            if !matchedTerms.isEmpty {
                bestScore = max(
                    bestScore ?? 0,
                    780 + Double(matchedTerms.count * 42)
                )
            }
        }

        if let fuzzyName = FuzzyMatcher.score(normalizedQuery, against: name) {
            bestScore = max(bestScore ?? 0, fuzzyName)
        }
        if bestScore == nil,
            let fuzzyPath = FuzzyMatcher.score(normalizedQuery, against: path)
        {
            bestScore = max(bestScore ?? 0, fuzzyPath * 0.78)
        }

        let isDirectory = (try? url.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) ?? false
        if isDirectory {
            bestScore = (bestScore ?? 0) + 18
        }

        return bestScore
    }

    private func mergeFinderSemanticMatches(
        _ base: [FinderSemanticMatch],
        with additional: [FinderSemanticMatch]
    ) -> [FinderSemanticMatch] {
        var merged: [String: FinderSemanticMatch] = [:]
        for match in base + additional {
            if let existing = merged[match.path], existing.score >= match.score {
                continue
            }
            merged[match.path] = match
        }
        return merged.values.sorted { lhs, rhs in
            if lhs.score != rhs.score { return lhs.score > rhs.score }
            if lhs.isDirectory != rhs.isDirectory { return lhs.isDirectory && !rhs.isDirectory }
            return lhs.title.localizedCaseInsensitiveCompare(rhs.title) == .orderedAscending
        }
    }

    private func buildFastFinderSemanticMatches(query: String, currentFolderPath: String) async
        -> [FinderSemanticMatch]
    {
        let normalizedQuery = normalizedDockPillText(query)
        guard !normalizedQuery.isEmpty else { return [] }
        let profile = finderSemanticProfile(for: normalizedQuery)
        let textQuery =
            !profile.residualQuery.isEmpty
            ? profile.residualQuery
            : (profile.hasSemanticConstraint ? "" : normalizedQuery)
        let now = Date()

        var matches: [FinderSemanticMatch] = []
        let fileManager = FileManager.default

        func addMatch(_ url: URL, baseScore: Double, source: String, extraTerms: [String] = []) {
            let resourceValues =
                (try? url.resourceValues(forKeys: [.isDirectoryKey, .contentModificationDateKey, .fileSizeKey]))
                ?? URLResourceValues()
            let textScore =
                !textQuery.isEmpty ? finderSemanticScore(query: textQuery, for: url) : nil
            let semanticBoost = finderSemanticConstraintBoost(
                for: url,
                profile: profile,
                resourceValues: resourceValues,
                now: now
            )

            if !profile.residualQuery.isEmpty, textScore == nil { return }
            if profile.hasSemanticConstraint, semanticBoost == nil { return }
            guard textScore != nil || semanticBoost != nil else { return }

            let isDirectory = resourceValues.isDirectory ?? url.hasDirectoryPath
            matches.append(
                FinderSemanticMatch(
                    path: url.path,
                    title: url.lastPathComponent.isEmpty ? url.path : url.lastPathComponent,
                    subtitle: "\(source) • \(finderDisplayPath(url.path))",
                    isDirectory: isDirectory,
                    score: (textScore ?? 0) + (semanticBoost ?? 0) + baseScore,
                    source: source,
                    searchTerms: extraTerms + [source, url.lastPathComponent, url.path]
                ))
        }

        let folderURL = URL(fileURLWithPath: currentFolderPath)
        let isTemporalOrSizeQuery =
            profile.wantsRecent || profile.wantsToday || profile.wantsYesterday
            || profile.wantsThisWeek || profile.wantsLargeFiles || profile.wantsSmallFiles
        if !isTemporalOrSizeQuery,
            (!profile.hasSemanticConstraint || profile.wantsFoldersOnly || !profile.residualQuery.isEmpty)
        {
            addMatch(folderURL, baseScore: 180, source: "Current Folder", extraTerms: ["finder", "current directory"])
        }

        let selectedURLs = axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        for url in selectedURLs {
            addMatch(url, baseScore: 165, source: "Selected Item", extraTerms: ["finder", "selection"])
        }

        if let currentItems = try? fileManager.contentsOfDirectory(
            at: folderURL,
            includingPropertiesForKeys: [.isDirectoryKey],
            options: [.skipsHiddenFiles, .skipsPackageDescendants]
        ) {
            for url in currentItems {
                addMatch(url, baseScore: 140, source: "Current Folder", extraTerms: ["finder"])
            }
        }

        return mergeFinderSemanticMatches([], with: matches)
    }

    private func runFinderSpotlightSearch(query: String, currentFolderPath: String, limit: Int)
        -> [FinderSemanticMatch]
    {
        let normalizedQuery = normalizedDockPillText(query)
        guard normalizedQuery.count >= 3 else { return [] }
        let profile = finderSemanticProfile(for: normalizedQuery)
        let contentQuery = profile.residualQuery
        guard !contentQuery.isEmpty else { return [] }
        let now = Date()
        let normalizedFolderPath = URL(fileURLWithPath: currentFolderPath).standardizedFileURL.path

        func executeMDFind(arguments: [String], source: String, boost: Double)
            -> [FinderSemanticMatch]
        {
            let task = Process()
            let pipe = Pipe()
            task.executableURL = URL(fileURLWithPath: "/usr/bin/mdfind")
            task.arguments = arguments
            task.standardOutput = pipe
            task.standardError = Pipe()

            do {
                try task.run()
                task.waitUntilExit()
                let data = pipe.fileHandleForReading.readDataToEndOfFile()
                guard let output = String(data: data, encoding: .utf8), !output.isEmpty else {
                    return []
                }

                var results: [FinderSemanticMatch] = []
                for path in output.components(separatedBy: .newlines)
                    .filter({ !$0.isEmpty })
                    .prefix(limit)
                {
                    let url = URL(fileURLWithPath: path)
                    let normalizedPath = url.standardizedFileURL.path
                    let parentPath = url.deletingLastPathComponent().standardizedFileURL.path
                    guard parentPath == normalizedFolderPath else { continue }
                    let resourceValues =
                        (try? url.resourceValues(forKeys: [.isDirectoryKey, .contentModificationDateKey, .fileSizeKey]))
                        ?? URLResourceValues()
                    let isDirectory = resourceValues.isDirectory ?? url.hasDirectoryPath
                    let textScore = finderSemanticScore(query: contentQuery, for: url) ?? 720
                    let semanticBoost = finderSemanticConstraintBoost(
                        for: url,
                        profile: profile,
                        resourceValues: resourceValues,
                        now: now
                    )
                    if profile.hasSemanticConstraint && semanticBoost == nil { continue }
                    results.append(
                        FinderSemanticMatch(
                            path: normalizedPath,
                            title: url.lastPathComponent.isEmpty ? normalizedPath : url.lastPathComponent,
                            subtitle: "\(source) • \(finderDisplayPath(normalizedPath))",
                            isDirectory: isDirectory,
                            score: textScore + (semanticBoost ?? 0) + boost,
                            source: source,
                            searchTerms: [url.lastPathComponent, normalizedPath, source, "content", "finder"]
                        ))
                }
                return results
            } catch {
                return []
            }
        }

        let currentFolderMatches = executeMDFind(
            arguments: ["-onlyin", currentFolderPath, contentQuery],
            source: "Current Folder Content",
            boost: 150
        )
        return currentFolderMatches
    }

    private func finderResultType(for path: String, isDirectory: Bool) -> SearchResult.ResultType {
        if isDirectory { return .folder }
        let ext = URL(fileURLWithPath: path).pathExtension.lowercased()
        if ["pdf", "txt", "md", "rtf", "doc", "docx", "pages", "json", "csv", "xml", "yaml", "yml", "swift", "js", "ts", "py", "sh"].contains(ext) {
            return .document
        }
        return .file
    }

    private func finderSemanticSymbol(for match: FinderSemanticMatch) -> String {
        if match.isDirectory { return "folder" }
        switch URL(fileURLWithPath: match.path).pathExtension.lowercased() {
        case "pdf":
            return "doc.richtext"
        case "png", "jpg", "jpeg", "gif", "heic", "webp", "tiff", "bmp":
            return "photo"
        case "zip", "rar", "7z", "gz", "tar":
            return "archivebox"
        case "mp4", "mov", "m4v", "avi", "mkv":
            return "film"
        case "mp3", "wav", "m4a", "flac":
            return "music.note"
        default:
            return "doc"
        }
    }

    private func finderSemanticAction(for path: String, isDirectory: Bool) -> () -> Void {
        {
            let url = URL(fileURLWithPath: path)
            rememberFinderFollowUpTargets(
                [url],
                folderPath: isDirectory ? url.path : url.deletingLastPathComponent().path,
                sourceQuery: url.lastPathComponent
            )
            currentContext = .filesSelected([url])
            if isDirectory {
                NSWorkspace.shared.open(url)
            } else {
                NSWorkspace.shared.activateFileViewerSelecting([url])
            }
        }
    }

    private func makeFinderSemanticSearchResults(from matches: [FinderSemanticMatch]) -> [SearchResult] {
        matches.prefix(24).map { match in
            let icon = NSWorkspace.shared.icon(forFile: match.path)
            icon.size = NSSize(width: 32, height: 32)
            return SearchResult(
                title: match.title,
                subtitle: match.subtitle,
                icon: icon,
                action: finderSemanticAction(for: match.path, isDirectory: match.isDirectory),
                score: match.score,
                type: finderResultType(for: match.path, isDirectory: match.isDirectory),
                filePath: match.path,
                contactData: nil
            )
        }
    }

    private func makeFinderSemanticDockPills(from matches: [FinderSemanticMatch]) -> [DockPill] {
        matches.prefix(8).map { match in
            var pill = DockPill(
                id: "finder-search-\(match.path)",
                name: match.title,
                icon: finderSemanticSymbol(for: match),
                accentColorName: match.isDirectory ? "blue" : "teal",
                badge: match.source,
                execute: finderSemanticAction(for: match.path, isDirectory: match.isDirectory)
            )
            pill.sourceBundleId = "com.apple.finder"
            pill.sourceAppName = "Finder"
            pill.rankingKind = match.source == "Current Folder" ? "finderCurrent" : "finderSearch"
            pill.trackingIdentifier = "finder-search:\(match.path.lowercased())"
            pill.searchTerms = match.searchTerms
            pill.rankingScore = match.score
            return pill
        }
    }

    private func applyFinderSemanticMatches(_ matches: [FinderSemanticMatch], query: String) {
        let latestScope = resolveDockScope(for: searchText)
        let latestQuery = latestScope.scopedBundleId == "com.apple.finder"
            ? latestScope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            : ""
        guard latestQuery == query else { return }

        finderSemanticQuery = query
        let results = makeFinderSemanticSearchResults(from: matches)
        finderSemanticResults = results
        finderSemanticPills = makeFinderSemanticDockPills(from: matches)
        applyFinderSemanticPanelResults(results)
    }

    private func clearFinderSemanticState() {
        let shouldClearPanelResults =
            !finderSemanticQuery.isEmpty || !finderSemanticResults.isEmpty || isFinderSemanticLoading
        finderSemanticTask?.cancel()
        finderSemanticTask = nil
        isFinderSemanticLoading = false
        finderSemanticQuery = ""
        finderSemanticResults = []
        finderSemanticPills = []
        showL2ResultsPopover = false
        if shouldClearPanelResults {
            applyFinderSemanticPanelResults([])
        }
    }

    private func scheduleFinderSemanticSearchIfNeeded(for query: String) {
        finderSemanticTask?.cancel()

        guard isL2ContextActive, showContextInDock, !showMediaLayer else {
            clearFinderSemanticState()
            return
        }

        let scope = resolveDockScope(for: query)
        let currentFolderPath = currentFinderFolderPath()
        guard scope.scopedBundleId == "com.apple.finder",
            isFinderCurrentWindowSearchAttached(currentFolderPath: currentFolderPath)
        else {
            clearFinderSemanticState()
            return
        }

        let semanticQuery = scope.scopedBundleId == "com.apple.finder"
            ? scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            : ""
        guard !semanticQuery.isEmpty else {
            isFinderSemanticLoading = false
            finderSemanticQuery = ""
            finderSemanticResults = []
            finderSemanticPills = []
            showL2ResultsPopover = shouldKeepFinderSearchPopoverVisible(for: query)
            applyFinderSemanticPanelResults([])
            return
        }

        isFinderSemanticLoading = true
        finderSemanticTask = Task(priority: .userInitiated) {
            try? await Task.sleep(nanoseconds: 45_000_000)
            guard !Task.isCancelled else { return }

            let fastMatches = await buildFastFinderSemanticMatches(
                query: semanticQuery,
                currentFolderPath: currentFolderPath
            )
            guard !Task.isCancelled else { return }
            await MainActor.run {
                applyFinderSemanticMatches(fastMatches, query: semanticQuery)
                isFinderSemanticLoading = false
            }

            let spotlightEnabled = await MainActor.run { settings.enableSpotlightSearch }
            guard spotlightEnabled, semanticQuery.count >= 3 else { return }

            try? await Task.sleep(nanoseconds: 160_000_000)
            guard !Task.isCancelled else { return }

            let spotlightMatches = runFinderSpotlightSearch(
                query: semanticQuery,
                currentFolderPath: currentFolderPath,
                limit: 18
            )
            let merged = mergeFinderSemanticMatches(fastMatches, with: spotlightMatches)
            guard !Task.isCancelled else { return }
            await MainActor.run {
                applyFinderSemanticMatches(merged, query: semanticQuery)
                isFinderSemanticLoading = false
            }
        }
    }

    private func isFinderSearchStyleQuery(_ query: String) -> Bool {
        let normalized = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !normalized.isEmpty else { return false }

        let analyticalTerms = [
            "summarize", "summary", "explain", "review", "translate", "compare",
            "analyze", "analyse", "why", "how", "read", "rewrite", "draft",
            "rename", "organize", "sort", "clean up", "compress", "zip",
            "convert", "export", "save", "open", "move", "copy", "share", "send",
            "attach", "upload", "delete", "trash", "remove", "duplicate",
            "reveal", "preview", "quick look", "print", "merge", "split",
            "extract", "encode", "transcode"
        ]
        return !analyticalTerms.contains(where: normalized.contains)
    }

    private func finderSubmissionSummary(for query: String, results: [SearchResult]) -> String {
        if results.isEmpty {
            return "No Finder matches for “\(query)”."
        }

        let folderCount = results.filter { $0.type == .folder }.count
        let fileCount = results.count - folderCount
        if folderCount > 0 && fileCount > 0 {
            return "Found \(results.count) Finder matches for “\(query)” across folders and files."
        }
        if folderCount > 0 {
            return "Found \(folderCount) Finder folder match\(folderCount == 1 ? "" : "es") for “\(query)”."
        }
        return "Found \(fileCount) Finder file match\(fileCount == 1 ? "" : "es") for “\(query)”."
    }

    private func executeCachedMenuAction(
        bundleIdentifier: String,
        appName: String,
        appPath: String?,
        path: [String],
        shortcutChar: String?,
        shortcutModifiers: Int
    ) {
        Task.detached(priority: .userInitiated) {
            var targetApp = NSWorkspace.shared.runningApplications.first {
                $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
            }

            if targetApp == nil {
                let url =
                    NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleIdentifier)
                    ?? appPath.map(URL.init(fileURLWithPath:))
                if let url {
                    NSWorkspace.shared.open(url)
                }
            }

            for _ in 0..<30 {
                if let app = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
                }) {
                    targetApp = app
                    break
                }
                try? await Task.sleep(nanoseconds: 120_000_000)
            }

            guard let targetApp else { return }
            let pid = targetApp.processIdentifier
            targetApp.activate(options: [.activateIgnoringOtherApps])
            try? await Task.sleep(nanoseconds: 250_000_000)

            let liveMatch = await waitForExecutableMenuItem(
                path: path,
                in: pid,
                attempts: 18,
                pauseNanoseconds: 140_000_000
            )

            guard let liveMatch else {
                if let ch = shortcutChar, !ch.isEmpty {
                    await MainActor.run {
                        self.executeDockMenuAction(
                            sourcePID: pid,
                            path: path,
                            shortcutChar: ch,
                            shortcutModifiers: shortcutModifiers
                        )
                    }
                    return
                }
                await MainActor.run {
                    self.l2ChatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content:
                                "I opened \(appName), but that menu action is not available right now."
                        )
                    )
                }
                return
            }

            guard liveMatch.isEnabled else {
                await MainActor.run {
                    self.l2ChatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content:
                                "I opened \(appName), but that menu action is disabled in the current state."
                        )
                    )
                }
                return
            }

            await MainActor.run {
                self.executeDockMenuAction(
                    sourcePID: pid,
                    path: path,
                    shortcutChar: shortcutChar,
                    shortcutModifiers: shortcutModifiers
                )
            }
        }
    }

    private func waitForExecutableMenuItem(
        path: [String],
        in pid: pid_t,
        attempts: Int,
        pauseNanoseconds: UInt64
    ) async -> AXMenuItem? {
        guard !path.isEmpty else { return nil }

        for attempt in 0..<attempts {
            let liveItems = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            if let match = liveItems.first(where: { menuPathMatches($0, targetPath: path) }) {
                return match
            }

            AXMenuReader.shared.invalidateCache(for: pid)

            if attempt < attempts - 1 {
                try? await Task.sleep(nanoseconds: pauseNanoseconds)
            }
        }

        return nil
    }

    private func menuPathMatches(_ item: AXMenuItem, targetPath: [String]) -> Bool {
        let normalizedTarget = normalizedMenuPathForMatching(targetPath)
        let normalizedItem = normalizedMenuPathForMatching(item.path)

        if normalizedItem == normalizedTarget {
            return true
        }

        if item.isAppleMenu {
            let strippedTarget = normalizedTarget.filter { $0 != "apple" }
            if !strippedTarget.isEmpty && normalizedItem == strippedTarget {
                return true
            }
        }

        return false
    }

    private func normalizedMenuPathForMatching(_ path: [String]) -> [String] {
        path.map {
            $0
                .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: .current)
                .lowercased()
                .trimmingCharacters(in: .whitespacesAndNewlines)
        }
        .filter { !$0.isEmpty }
    }

    /// Detect whether the current query targets a cross-app and trigger menu loading if needed.
    /// Safe to call from `.onChange` handlers (outside view body evaluation).
    private func triggerCrossAppMenuLoadIfNeeded(for query: String) {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return }
        if let target = L2AppActionRouter.shared.appScopeTarget(for: q),
            !target.actionQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
            let app = NSWorkspace.shared.runningApplications.first(where: {
                $0.bundleIdentifier == target.bundleId
            })
        {
            loadCrossAppMenu(for: app)
            return
        }
        if settings.crossAppPills,
            let (app, actionQuery) = detectCrossAppQuery(q),
            !actionQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        {
            loadCrossAppMenu(for: app)
        }
    }

    private func seedCrossAppMenuCache(for app: NSRunningApplication) {
        let pid = app.processIdentifier
        let appName = app.localizedName ?? ""
        var cachedItems = AppMenuCapabilityCache.shared.menuItems(for: app, maxResults: 120)
        for index in cachedItems.indices {
            cachedItems[index].sourcePID = pid
            cachedItems[index].sourceAppName = appName
        }

        crossAppMenuTargetPID = pid
        crossAppMenuNeedsLiveLoad = true
        crossAppMenuItems = cachedItems
    }

    /// Load menu items for a target app into crossAppMenuItems (skips if already loaded for same PID).
    private func loadCrossAppMenu(for app: NSRunningApplication) {
        let pid = app.processIdentifier
        guard pid != 0 else { return }
        guard pid != crossAppMenuTargetPID || crossAppMenuNeedsLiveLoad else { return }
        // Defer state mutations to avoid modifying @State during view update (body evaluation).
        DispatchQueue.main.async {
            crossAppMenuTargetPID = pid
            crossAppMenuNeedsLiveLoad = false
            crossAppMenuTask?.cancel()
            crossAppMenuTask = Task.detached(priority: .userInitiated) {
                let name = app.localizedName ?? ""
                var loadedFromPersistentCache = false
                var items = AXMenuReader.shared.allMenuItems(for: pid, maxDepth: 6)
                if items.isEmpty {
                    items = AppMenuCapabilityCache.shared.menuItems(for: app, maxResults: 120)
                    loadedFromPersistentCache = !items.isEmpty
                }
                for i in items.indices {
                    items[i].sourcePID = pid
                    items[i].sourceAppName = name
                }
                if !loadedFromPersistentCache {
                    AppMenuCapabilityCache.shared.store(items: items, for: app)
                }
                await MainActor.run {
                    guard self.crossAppMenuTargetPID == pid else { return }
                    self.crossAppMenuItems = items
                }
            }
        }
    }

    private func distributedMenuItems(_ items: [AXMenuItem], limit: Int) -> [AXMenuItem] {
        guard limit > 0, !items.isEmpty else { return [] }

        var buckets: [String: [AXMenuItem]] = [:]
        var rootOrder: [String] = []

        for item in items {
            let root = item.path.first ?? item.title
            if buckets[root] == nil {
                buckets[root] = []
                rootOrder.append(root)
            }
            buckets[root, default: []].append(item)
        }

        for root in rootOrder {
            buckets[root]?.sort {
                if $0.path.count != $1.path.count { return $0.path.count < $1.path.count }
                return $0.title.localizedCaseInsensitiveCompare($1.title) == .orderedAscending
            }
        }

        var distributed: [AXMenuItem] = []
        var didAppend = true
        while distributed.count < limit && didAppend {
            didAppend = false
            for root in rootOrder where distributed.count < limit {
                guard var bucket = buckets[root], !bucket.isEmpty else { continue }
                distributed.append(bucket.removeFirst())
                buckets[root] = bucket
                didAppend = true
            }
        }

        return distributed
    }

    private func orderedScopedMenuMatches(_ items: [AXMenuItem], filterQuery: String, limit: Int)
        -> [AXMenuItem]
    {
        guard !items.isEmpty else { return [] }
        let normalizedFilter = filterQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if normalizedFilter.isEmpty {
            return distributedMenuItems(items, limit: limit)
        }

        return Array(
            items.sorted {
                let aPrefix = $0.title.lowercased().hasPrefix(normalizedFilter) ? 0 : 1
                let bPrefix = $1.title.lowercased().hasPrefix(normalizedFilter) ? 0 : 1
                if aPrefix != bPrefix { return aPrefix < bPrefix }
                if $0.path.count != $1.path.count { return $0.path.count < $1.path.count }
                return $0.title.localizedCaseInsensitiveCompare($1.title) == .orderedAscending
            }
            .prefix(limit)
        )
    }

    /// Build the ordered list of visible pills for the current dock state.
    /// This is the single source of truth for both rendering and keyboard navigation.
    func buildDockPills(query q: String) -> [DockPill] {
        // "youtube on web" / "browse tamilgun" / "web X" → immediate web-search pill
        if let searchTerm = L2AppActionRouter.shared.extractWebSearchQuery(from: q) {
            let browserName = L2AppActionRouter.defaultBrowserName()
            var pill = DockPill(
                id: "web-search-\(searchTerm)",
                name: "Search \"\(searchTerm)\" on Web",
                icon: "globe",
                accentColorName: "blue",
                badge: browserName,
                execute: { L2AppActionRouter.openWebSearch(searchTerm) }
            )
            pill.rankingKind = "webSearch"
            pill.searchTerms = [searchTerm, "web", "search", browserName]
            pill.trackingIdentifier = "web-search:\(searchTerm)"
            return [pill]
        }

        var pills: [DockPill] = []
        let scope = resolveDockScope(for: q)
        let rawScopedSearchQuery = rawScopedActionQuery(for: q, scope: scope)
        let explicitAppTarget = q.isEmpty ? nil : L2AppActionRouter.shared.appScopeTarget(for: q)
        let installedMenuTarget =
            (explicitAppTarget == nil && l2TargetApp == nil)
            ? installedAppMenuTarget(for: q)
            : nil
        let isExplicitAppScope = scope.isExplicitAppScope
        let isGlobalScope = scope.isGlobalScope
        let scopedBundleId = scope.scopedBundleId
        let scopedAppName = scope.scopedAppName
        let scopedSearchQuery = scope.scopedSearchQuery
        let rawPayloadActionPills = buildPayloadActionPills(query: q)
        let rawFinderFilePills =
            (!isExplicitAppScope || scopedBundleId == "com.apple.finder")
            ? buildFinderFilePills(query: q) : []
        let finderFileTitleSet = Set(rawFinderFilePills.map { normalizedDockPillText($0.name) })
        let rawFinderSelectionMenuPills =
            (!isExplicitAppScope || scopedBundleId == "com.apple.finder")
            ? buildFinderSelectionMenuPills(query: q, excludingTitles: finderFileTitleSet) : []
        let payloadActionPills: [DockPill] = {
            guard isExplicitAppScope, !scopedSearchQuery.isEmpty else {
                return rawPayloadActionPills
            }
            let payloadIntentWords = [
                "send", "share", "message", "messages", "imessage", "sms",
                "mail", "email", "note", "notes", "reminder", "remind",
                "download", "downloads"
            ]
            let isPayloadIntent = payloadIntentWords.contains { scopedSearchQuery.contains($0) }
            return isPayloadIntent ? rawPayloadActionPills : []
        }()
        let semanticFinderPills: [DockPill] = {
            guard !shouldUseFinderSearchPopover(for: q) else { return [] }
            guard scopedBundleId == "com.apple.finder" else { return [] }
            guard isFinderCurrentWindowSearchAttached() else { return [] }
            let semanticQuery = scopedSearchQuery
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
            guard !semanticQuery.isEmpty, finderSemanticQuery == semanticQuery else { return [] }
            return finderSemanticPills
        }()
        let messagesSemanticIntentPill =
            scopedBundleId == "com.apple.MobileSMS"
            ? makeMessagesSemanticIntentPill(
                fullQuery: q,
                rawScopedQuery: rawScopedSearchQuery,
                scopedBundleId: scopedBundleId,
                scopedAppName: scopedAppName
            )
            : nil
        let mailSemanticSearchPill =
            scopedBundleId == "com.apple.mail"
            ? makeMailSemanticSearchPill(
                fullQuery: q,
                rawScopedQuery: rawScopedSearchQuery,
                scopedBundleId: scopedBundleId,
                scopedAppName: scopedAppName
            )
            : nil
        let hasStrongContextQuery = !payloadActionPills.isEmpty
        let shouldSuppressMenuForContext = false
        let activeBundleId = isGlobalScope ? "" : scopedBundleId
        let scopedAppKey =
            isGlobalScope
            ? ""
            : (
                activeSmartQueryKey
                ?? settings.appKey(forBundleID: scopedBundleId, appName: scopedAppName)
                ?? settings.autoDetectedAppKey
                ?? ""
            )
        let allQuickActions =
            isGlobalScope
            ? []
            : (
                settings.contextDockShortcuts(for: scopedAppKey).isEmpty
                ? settings.shortcuts(for: scopedAppKey)
                : settings.contextDockShortcuts(for: scopedAppKey)
            )
        let userScriptExtensions =
            isGlobalScope || scopedAppKey.isEmpty
            ? [AppToolExtension]()
            : appPillScriptExtensions(for: scopedAppKey, query: scopedSearchQuery)
        let cliPackages: [TerminalPackage] = {
            guard !isGlobalScope, !scopedBundleId.isEmpty else { return [] }
            // For cli:// adapter scopes, directly surface the matching package by command name.
            if scopedBundleId.hasPrefix("cli://") {
                let cmd = String(scopedBundleId.dropFirst("cli://".count))
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                if let pkg = terminalPackageManager.packages.first(where: {
                    $0.isEnabled && $0.command.caseInsensitiveCompare(cmd) == .orderedSame
                }) {
                    if scopedSearchQuery.isEmpty { return [pkg] }
                    let q2 = scopedSearchQuery.lowercased()
                    let matches = pkg.command.lowercased().contains(q2)
                        || pkg.name.lowercased().contains(q2)
                        || pkg.subcommands.contains { $0.lowercased().hasPrefix(q2) }
                    return matches ? [pkg] : []
                }
                return []
            }
            return terminalPackageManager.packages(
                forContextBundleId: scopedBundleId,
                query: scopedSearchQuery,
                maxResults: q.isEmpty ? 6 : 4
            )
        }()
        let adapterActions =
            isGlobalScope || scopedBundleId.isEmpty
            ? [AdapterAction]()
            : (
                q.isEmpty
                ? adapterManager.actions(for: scopedBundleId)
                : adapterManager.actions(for: scopedBundleId, query: scopedSearchQuery)
            )
        let adapterCLICommands = Set<String>(
            adapterActions.compactMap { action in
                guard action.type == .cliTool else { return nil }
                let command = action.cliToolCommand?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                return command.isEmpty ? nil : command.lowercased()
            }
        )
        let visibleCLIPackages = cliPackages.filter { package in
            !adapterCLICommands.contains(package.command.lowercased())
        }
        let visibleAdapterActions = adapterActions
        let allAppTools = {
            guard !isGlobalScope else { return [L2Extension]() }
            guard !scopedAppName.isEmpty || !scopedBundleId.isEmpty else {
                return frontmostAppL2Extensions
            }
            return l2Extensions(forAppName: scopedAppName, bundleID: scopedBundleId)
        }()
        let allCtxExts =
            isExplicitAppScope
            ? scopedContextExtensions(
                query: scopedSearchQuery, appName: scopedAppName, bundleId: scopedBundleId)
            : l2ContextExtensions
        let quickActions =
            q.isEmpty
            ? allQuickActions
            : allQuickActions.filter { $0.name.lowercased().contains(scopedSearchQuery) }
        let appTools =
            q.isEmpty
            ? allAppTools
            : allAppTools.filter {
                $0.displayName.lowercased().contains(scopedSearchQuery)
                    || $0.toolName.lowercased().contains(scopedSearchQuery)
            }
        let ctxExts =
            q.isEmpty
            ? allCtxExts
            : allCtxExts.filter { $0.ilExtension.name.lowercased().contains(scopedSearchQuery) }
        let scopedAppLaunchPill: DockPill? = {
            // No "Open" pill for cli:// adapters — they're not launchable apps
            guard !scopedBundleId.hasPrefix("cli://") else { return nil }
            guard isExplicitAppScope, !q.isEmpty, !scopedBundleId.isEmpty, !scopedAppName.isEmpty,
                scopedSearchQuery.isEmpty
            else { return nil }

            var pill = DockPill(
                id: "launch-\(scopedBundleId)",
                name: "Open \(scopedAppName)",
                icon: "app.badge",
                accentColorName: "blue",
                badge: nil,
                execute: {
                    _ = launchApplication(
                        bundleIdentifier: scopedBundleId,
                        appName: scopedAppName,
                        path: installedMenuTarget?.appPath
                    )
                }
            )
            pill.rankingKind = "appLaunch"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "app-launch:\(scopedBundleId)"
            pill.searchTerms = [scopedAppName, "open", "launch", "app"]
            return pill
        }()

        let favs = settings.favouriteMenuPills(for: activeBundleId)
        let isScopedToOtherApp =
            isExplicitAppScope && !scopedBundleId.isEmpty && scopedBundleId != frontmostAppBundleID
        let useSeededMenuPills =
            q.isEmpty && !liveMenuItems.isEmpty && !shouldSuppressMenuForContext
            && !isScopedToOtherApp

        if useSeededMenuPills && !hasStrongContextQuery {
            let seedItems = Array(
                liveMenuItems
                    .filter { !$0.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                    .filter { !isExplicitAppScope || !$0.isAppleMenu }
                    .prefix(16)
            )

            for item in seedItems {
                let path = item.path
                let sourcePID =
                    item.sourcePID != 0
                    ? item.sourcePID
                    : (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
                let badge: String? = item.shortcutDisplay
                let shortcutChar = item.shortcutChar
                let shortcutMods = item.shortcutModifiers
                let menuImg = item.image

                var pill = DockPill(
                    id: "menu-seed-\(item.id)",
                    name: item.title,
                    icon: "menubar.rectangle",
                    accentColorName: "gray",
                    badge: badge,
                    execute: {
                        guard sourcePID != 0 else { return }
                        self.executeDockMenuAction(
                            sourcePID: sourcePID,
                            path: path,
                            shortcutChar: shortcutChar,
                            shortcutModifiers: shortcutMods
                        )
                    }
                )
                pill.menuItemImage = menuImg
                pill.menuItemName = item.title
                pill.sourceBundleId = activeBundleId
                pills.append(pill)
            }
        }

        if let scopedAppLaunchPill {
            pills.append(scopedAppLaunchPill)
        }

        if let messagesSemanticIntentPill {
            pills.append(messagesSemanticIntentPill)
        }

        if let mailSemanticSearchPill {
            pills.append(mailSemanticSearchPill)
        }

        pills.append(contentsOf: rawFinderFilePills.map { pill in
            var enriched = pill
            if enriched.rankingKind.isEmpty {
                enriched.rankingKind = "finderSelection"
            }
            enriched.sourceBundleId = enriched.sourceBundleId.isEmpty ? "com.apple.finder" : enriched.sourceBundleId
            enriched.sourceAppName = enriched.sourceAppName.isEmpty ? "Finder" : enriched.sourceAppName
            if enriched.searchTerms.isEmpty {
                enriched.searchTerms = [enriched.name, enriched.badge ?? "", "finder", "files"]
            }
            if enriched.trackingIdentifier.isEmpty {
                enriched.trackingIdentifier = "finder-selection:\(normalizedDockPillText(enriched.name))"
            }
            return enriched
        })

        pills.append(contentsOf: rawFinderSelectionMenuPills)

        pills.append(contentsOf: semanticFinderPills)

        pills.append(contentsOf: payloadActionPills.map { pill in
            var enriched = pill
            if enriched.rankingKind.isEmpty {
                enriched.rankingKind = "payload"
            }
            if enriched.searchTerms.isEmpty {
                enriched.searchTerms = [enriched.name, enriched.badge ?? ""]
            }
            if enriched.trackingIdentifier.isEmpty {
                enriched.trackingIdentifier = "payload:\(normalizedDockPillText(enriched.name))"
            }
            return enriched
        })

        let dedupeMenuItems: ([AXMenuItem]) -> [AXMenuItem] = { items in
            var seen = Set<String>()
            var deduped: [AXMenuItem] = []
            for item in items {
                let key = item.path.joined(separator: " > ").lowercased()
                guard !key.isEmpty, !seen.contains(key) else { continue }
                seen.insert(key)
                deduped.append(item)
            }
            return deduped
        }

        let persistentMenuMatches: (NSRunningApplication, String, Int) -> [AXMenuItem] = {
            app, query, limit in
            AppMenuCapabilityCache.shared.menuItems(for: app, query: query, maxResults: limit)
        }
        let persistentClosedAppMatches: (String, String, String, Int) -> [AXMenuItem] = {
            bundleId, appName, query, limit in
            AppMenuCapabilityCache.shared.menuItems(
                bundleIdentifier: bundleId,
                appName: appName,
                processIdentifier: 0,
                query: query,
                maxResults: limit
            )
        }
        let sanitizeScopedMenuMatches: ([AXMenuItem]) -> [AXMenuItem] = { items in
            guard isExplicitAppScope else { return items }
            return items.filter { !$0.isAppleMenu }
        }
        let pureScopeMenuLimit = 10
        let pureScopeCandidateLimit = 12
        let scopedRunningMenuMatches:
            (NSRunningApplication, String, Bool) -> [AXMenuItem] = { app, filterQ, preferCached in
                let cachedMatches = crossAppMenuItems.filter { item in
                    item.sourcePID == app.processIdentifier
                        && (filterQ.isEmpty || item.title.lowercased().contains(filterQ)
                            || item.path.contains { $0.lowercased().contains(filterQ) })
                }
                if preferCached {
                    let seedMatches =
                        cachedMatches.isEmpty
                        ? persistentMenuMatches(app, filterQ, pureScopeCandidateLimit)
                        : cachedMatches
                    return orderedScopedMenuMatches(
                        dedupeMenuItems(sanitizeScopedMenuMatches(seedMatches)),
                        filterQuery: filterQ,
                        limit: pureScopeMenuLimit
                    )
                }

                let matches = dedupeMenuItems(
                    sanitizeScopedMenuMatches(
                        cachedMatches + persistentMenuMatches(app, filterQ, 24)
                    )
                )
                return orderedScopedMenuMatches(matches, filterQuery: filterQ, limit: 16)
            }
        let scopedClosedMenuMatches:
            (String, String, String, Bool) -> [AXMenuItem] = { bundleId, appName, filterQ, preferCached in
                let matches = dedupeMenuItems(
                    sanitizeScopedMenuMatches(
                        persistentClosedAppMatches(
                            bundleId,
                            appName,
                            filterQ,
                            preferCached ? pureScopeCandidateLimit : 24
                        )
                    )
                )
                return orderedScopedMenuMatches(
                    matches,
                    filterQuery: filterQ,
                    limit: preferCached ? pureScopeMenuLimit : 16
                )
            }

        // Live menu items: primary (frontmost app) + optional cross-app when query targets another app
        let menuMatches: [AXMenuItem] = {
            if let installedMenuTarget {
                let filterQ = installedMenuTarget.actionQuery
                let preferCached = isExplicitAppScope && filterQ.isEmpty
                let targetApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == installedMenuTarget.bundleId && !$0.isTerminated
                })
                if let targetApp {
                    return scopedRunningMenuMatches(targetApp, filterQ, preferCached)
                }
                return scopedClosedMenuMatches(
                    installedMenuTarget.bundleId,
                    installedMenuTarget.appName,
                    filterQ,
                    preferCached
                )
            }
            if let pinnedTarget = l2TargetApp,
                let targetApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == pinnedTarget.bundleId
                })
            {
                let filterQ = scopedSearchQuery
                return scopedRunningMenuMatches(
                    targetApp,
                    filterQ,
                    isExplicitAppScope && filterQ.isEmpty
                )
            }
            if let pinnedTarget = l2TargetApp {
                let matches = scopedClosedMenuMatches(
                    pinnedTarget.bundleId,
                    pinnedTarget.name,
                    scopedSearchQuery,
                    isExplicitAppScope && scopedSearchQuery.isEmpty
                )
                if !matches.isEmpty {
                    return matches
                }
            }
            if let explicitAppTarget,
                let targetApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == explicitAppTarget.bundleId
                })
            {
                let filterQ = explicitAppTarget.actionQuery
                return scopedRunningMenuMatches(
                    targetApp,
                    filterQ,
                    isExplicitAppScope && filterQ.isEmpty
                )
            }
            if let explicitAppTarget {
                let filterQ = explicitAppTarget.actionQuery
                let matches = scopedClosedMenuMatches(
                    explicitAppTarget.bundleId,
                    explicitAppTarget.appName,
                    filterQ,
                    isExplicitAppScope && filterQ.isEmpty
                )
                if !matches.isEmpty {
                    return matches
                }
            }
            // Check if query starts with a known app name → cross-app mode (requires Cross-App Connect)
            if settings.crossAppPills, let (targetApp, actionQuery) = detectCrossAppQuery(q) {
                let filterQ = actionQuery.isEmpty ? q : actionQuery
                let candidateLimit = filterQ.isEmpty ? 80 : 24
                let cachedMatches = crossAppMenuItems.filter { item in
                    item.sourcePID == targetApp.processIdentifier
                        && (filterQ.isEmpty || item.title.lowercased().contains(filterQ)
                            || item.path.contains { $0.lowercased().contains(filterQ) })
                }
                let matches = dedupeMenuItems(
                    cachedMatches + persistentMenuMatches(targetApp, filterQ, candidateLimit)
                )
                return orderedScopedMenuMatches(matches, filterQuery: filterQ, limit: 16)
            }
            // Default: frontmost app's real menu items first — query-time AX search is primary.
            let cachedMatches = liveMenuItems.filter { item in
                item.title.lowercased().contains(q)
                    || item.path.contains { $0.lowercased().contains(q) }
            }
            let persistentMatches: [AXMenuItem] = {
                guard let app = AppDelegate.shared?.previousFrontmostApp else { return [] }
                return persistentMenuMatches(app, q, 24)
            }()
            let matches = dedupeMenuItems(cachedMatches + persistentMatches)
            return Array(
                matches.sorted {
                    let aFav = favs.contains($0.title) ? 0 : 1
                    let bFav = favs.contains($1.title) ? 0 : 1
                    if aFav != bFav { return aFav < bFav }
                    let aTitle = $0.title.lowercased().hasPrefix(q) ? 0 : 1
                    let bTitle = $1.title.lowercased().hasPrefix(q) ? 0 : 1
                    if aTitle != bTitle { return aTitle < bTitle }
                    return $0.path.count < $1.path.count
                }.prefix(16))
        }()

        // Context-reactive pills — menu items that just became enabled after a selection change.
        // Only shown when the user hasn't typed a query (they'd surface via menuMatches otherwise).
        if q.isEmpty && !shouldSuppressMenuForContext && menuMatches.isEmpty
            && !contextMenuPills.isEmpty
        {
            for item in contextMenuPills {
                let path = item.path
                let sourcePID =
                    item.sourcePID != 0
                    ? item.sourcePID
                    : (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
                let sc = item.shortcutChar
                let mod = item.shortcutModifiers
                let badge: String? =
                    item.shortcutDisplay ?? (path.count >= 2 ? path[path.count - 2] : nil)
                pills.append(
                    DockPill(
                        id: "ctx-menu-\(item.id)",
                        name: item.title,
                        icon: "sparkles",
                        accentColorName: "blue",
                        badge: badge,
                        execute: {
                            guard sourcePID != 0 else { return }
                            self.executeDockMenuAction(
                                sourcePID: sourcePID,
                                path: path,
                                shortcutChar: sc,
                                shortcutModifiers: mod
                            )
                        }
                    ))
            }
        }

        let visibleMenuMatches: [AXMenuItem] = {
            if shouldSuppressMenuForContext { return [] }
            return hasStrongContextQuery ? Array(menuMatches.prefix(6)) : menuMatches
        }()

        for result in ctxExts {
            let ext = result.ilExtension
            let ctx = currentContext
            var pill = DockPill(
                id: "ctx-\(ext.id)", name: ext.name,
                icon: ext.icon, accentColorName: "teal", badge: nil,
                execute: { Task { await executeL2Extension(ext, context: ctx) } })
            pill.rankingKind = "contextExtension"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "ctxext:\(ext.id)"
            pill.searchTerms = [ext.name]
            pills.append(pill)
        }

        for sc in quickActions {
            var pill = DockPill(
                id: "qa-\(sc.id)", name: sc.name,
                icon: sc.iconName, accentColorName: nil, badge: nil,
                execute: { executeAppShortcut(sc) })
            pill.rankingKind = "quickAction"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "quick:\(sc.id)"
            pill.searchTerms = [sc.name]
            pills.append(pill)
        }
        for ext in userScriptExtensions {
            let icon = ext.scriptLanguage?.systemImage ?? "terminal"
            let displayName = ext.toolName.replacingOccurrences(of: "-", with: " ").capitalized
            var pill = DockPill(
                id: "usr-script-\(ext.id.uuidString)",
                name: displayName,
                icon: icon,
                accentColorName: "green",
                badge: "Script",
                execute: { executeAppToolExtension(ext, launchQuery: scopedSearchQuery) }
            )
            pill.rankingKind = "userExtension"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "userext:\(scopedAppKey):\(ext.id.uuidString)"
            pill.searchTerms = [displayName, ext.toolName, ext.aiHint] + ext.profile.capabilities + ext.profile.exampleCommands
            pills.append(pill)
        }
        for package in visibleCLIPackages {
            let isTUI = TerminalAIBridge.shared.isTUICommand(package.command)
            let icon = isTUI ? "terminal.fill" : "chevron.left.forwardslash.chevron.right"
            let displayName = package.name.isEmpty ? package.command : package.name
            var pill = DockPill(
                id: "cli-\(scopedBundleId)-\(package.command)",
                name: displayName,
                icon: icon,
                accentColorName: "green",
                badge: "CLI",
                execute: { openCLIToolPanel(for: package) }
            )
            pill.rankingKind = "cliTool"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "cli:\(scopedBundleId):\(package.command)"
            pill.searchTerms =
                [displayName, package.command, package.description]
                + package.keywords
                + package.subcommands
                + package.taskCategories
                + Array(package.usageExamples.prefix(3))
            pills.append(pill)

            for sub in package.subcommands.prefix(4) {
                let fullCmd = "\(package.command) \(sub)"
                var subPill = DockPill(
                    id: "cli-sub-\(scopedBundleId)-\(fullCmd)",
                    name: sub,
                    icon: icon,
                    accentColorName: "green",
                    badge: package.command,
                    execute: { attachCLIToolToCurrentDock(command: fullCmd, package: package, runImmediately: true) }
                )
                subPill.rankingKind = "cliTool"
                subPill.sourceBundleId = scopedBundleId
                subPill.sourceAppName = scopedAppName
                subPill.trackingIdentifier = "cli-sub:\(scopedBundleId):\(fullCmd)"
                subPill.searchTerms = [sub, fullCmd, displayName, package.command]
                pills.append(subPill)
            }
        }
        for tool in appTools {
            var pill = DockPill(
                id: "tool-\(tool.toolName)", name: tool.displayName,
                icon: tool.icon, accentColorName: "indigo", badge: nil,
                execute: {
                    l2ChatMessages.append(AIChatMessage(role: .user, content: tool.displayName))
                    l2IsLoading = true
                    Task {
                        let (ok, out) = await L2ExtensionManager.shared.execute(
                            toolName: tool.toolName, arguments: [:])
                        await MainActor.run {
                            let msg =
                                ok
                                ? (out.isEmpty ? "✅ \(tool.displayName) done." : out)
                                : "❌ \(tool.displayName) failed: \(out)"
                            l2ChatMessages.append(AIChatMessage(role: .assistant, content: msg))
                            l2IsLoading = false
                        }
                    }
                })
            pill.rankingKind = "tool"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "tool:\(scopedBundleId):\(tool.toolName)"
            pill.searchTerms = [tool.displayName, tool.toolName]
            pills.append(pill)
        }
        for action in visibleAdapterActions {
            let cliCommand =
                action.cliToolCommand?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            let pillName =
                action.type == .cliTool && !cliCommand.isEmpty
                ? cliCommand
                : action.name
            var pill = DockPill(
                id: "adapter-\(scopedBundleId)-\(action.id)",
                name: pillName,
                icon: action.icon,
                accentColorName: action.accentColor ?? "blue",
                badge: action.type == .menubar ? "Custom" : (action.type == .cliTool ? "CLI" : action.type.displayName),
                execute: {
                    if action.type == .cliTool, !cliCommand.isEmpty
                    {
                        attachCLIToolToCurrentDock(
                            command: cliCommand,
                            bundleIdentifier: scopedBundleId,
                            appName: scopedAppName
                        )
                        return
                    }
                    let capturedContext = effectiveAXContextForConversation()
                    Task {
                        let result = await adapterManager.execute(
                            action,
                            context: capturedContext,
                            targetBundleId: scopedBundleId,
                            query: scopedSearchQuery
                        )
                        await MainActor.run {
                            if action.type == .aiPrompt, result.0, !result.1.isEmpty {
                                searchText = result.1
                                isSearchFieldFocused = true
                            }
                        }
                    }
                })
            pill.rankingKind = action.type == .cliTool ? "cliTool" : "adapter"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "adapter:\(scopedBundleId):\(action.id)"
            pill.searchTerms =
                [action.name, pillName, action.description, action.type.displayName, cliCommand]
                + action.triggers
            pills.append(pill)

            // For CLI tool adapter actions, also emit subcommand pills so the user
            // gets the same scannable help-command pills as standalone CLI packages.
            if action.type == .cliTool, !cliCommand.isEmpty,
               let pkg = terminalPackageManager.packages.first(where: {
                   $0.command.caseInsensitiveCompare(cliCommand) == .orderedSame
               })
            {
                for sub in pkg.subcommands.prefix(5) {
                    let fullCmd = "\(cliCommand) \(sub)"
                    var subPill = DockPill(
                        id: "adapter-sub-\(scopedBundleId)-\(fullCmd)",
                        name: sub,
                        icon: action.icon,
                        accentColorName: action.accentColor ?? "green",
                        badge: cliCommand,
                        execute: {
                            attachCLIToolToCurrentDock(
                                command: fullCmd,
                                package: pkg,
                                runImmediately: true
                            )
                        }
                    )
                    subPill.rankingKind = "cliTool"
                    subPill.sourceBundleId = scopedBundleId
                    subPill.sourceAppName = scopedAppName
                    subPill.trackingIdentifier = "adapter-sub:\(scopedBundleId):\(fullCmd)"
                    subPill.searchTerms = [sub, fullCmd, action.name, cliCommand] + pkg.keywords
                    pills.append(subPill)
                }
            }
        }

        if !useSeededMenuPills || hasStrongContextQuery {
            for item in visibleMenuMatches {
                let path = item.path
                let menuBundleId = activeBundleId
                let menuAppName = item.sourceAppName.isEmpty ? scopedAppName : item.sourceAppName
                let menuAppPath =
                    installedMenuTarget?.bundleId == menuBundleId
                    ? installedMenuTarget?.appPath
                    : allApplications.first { result in
                        Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier
                            == menuBundleId
                    }?.subtitle
                let sourcePID =
                    item.sourcePID != 0
                    ? item.sourcePID
                    : (menuBundleId.isEmpty
                        ? (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
                        : 0)
                // Only show source badge for cross-app items; Apple menu items are universal — no badge
                let isFrontmost =
                    sourcePID == (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
                let pillBadge: String? = {
                    if item.isAppleMenu { return nil }  // universal — no app badge
                    if !item.sourceAppName.isEmpty && !isFrontmost {
                        return item.sourceAppName  // cross-app badge
                    }
                    return path.count >= 2 ? path[path.count - 2] : nil  // parent menu name
                }()
                let shortcutChar = item.shortcutChar
                let shortcutMods = item.shortcutModifiers
                let shortcutHint = item.shortcutDisplay

                let isFav = favs.contains(item.title)
                var pill = DockPill(
                    id: "menu-\(item.id)", name: item.title,
                    icon: isFav ? "star.fill" : "menubar.rectangle",
                    accentColorName: isFav ? "yellow" : "gray",
                    badge: shortcutHint ?? pillBadge,
                    execute: {
                        if sourcePID == 0, !menuBundleId.isEmpty {
                            executeCachedMenuAction(
                                bundleIdentifier: menuBundleId,
                                appName: menuAppName,
                                appPath: menuAppPath,
                                path: path,
                                shortcutChar: shortcutChar,
                                shortcutModifiers: shortcutMods
                            )
                            return
                        }
                        guard sourcePID != 0 else { return }
                        self.executeDockMenuAction(
                            sourcePID: sourcePID,
                            path: path,
                            shortcutChar: shortcutChar,
                            shortcutModifiers: shortcutMods
                        )
                    })
                pill.isFavourited = isFav
                pill.menuItemName = item.title
                pill.sourceBundleId = menuBundleId
                pill.sourceAppName = menuAppName
                pill.rankingKind = "menu"
                pill.trackingIdentifier =
                    "menu:\(menuBundleId):\(path.joined(separator: " > ").lowercased())"
                pill.searchTerms = item.path + [menuAppName]
                if sourcePID != 0, item.title.lowercased().hasPrefix("share") {
                    pill = DockPill(
                        id: pill.id, name: pill.name,
                        icon: "square.and.arrow.up",
                        accentColorName: "blue",
                        badge: pill.badge,
                        execute: { showShareSheetForContext() })
                    pill.isShareAction = true
                    pill.isFavourited = isFav
                    pill.menuItemName = item.title
                    pill.sourceBundleId = menuBundleId
                    pill.sourceAppName = menuAppName
                    pill.rankingKind = "menu"
                    pill.trackingIdentifier =
                        "menu:\(menuBundleId):\(path.joined(separator: " > ").lowercased())"
                    pill.searchTerms = item.path + [menuAppName, "share"]
                }
                pills.append(pill)
            }
        }
        if !isExplicitAppScope {
            pills += buildCrossAppPills(query: q)
        }
        let resolvedRulePills = AXTriggerRuleEngine.shared.evaluate(context: axContext)
        if !isExplicitAppScope {
            let filteredRulePills =
                q.isEmpty
                ? resolvedRulePills : resolvedRulePills.filter { $0.name.lowercased().contains(q) }
            pills += filteredRulePills.map { r in
                DockPill(
                    id: r.id, name: r.name, icon: r.icon, accentColorName: r.accentColor,
                    badge: nil, execute: r.execute)
            }
        }

        let rankingQuery = isExplicitAppScope ? scopedSearchQuery : q
        return rankDockPills(
            pills,
            rawQuery: q,
            rankingQuery: rankingQuery,
            scopedBundleId: scopedBundleId,
            scopedAppName: scopedAppName,
            isExplicitAppScope: isExplicitAppScope
        )
    }

    /// Execute the currently focused pill. Only call when focusedPillIndex is non-nil.
    /// Clears the input field afterwards so the dock is ready for the next command.
    func executeFirstOrFocusedPill() {
        let q = searchText.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let pills = buildDockPills(query: q)
        guard let idx = focusedPillIndex, idx < pills.count else { return }
        let pill =
            pills[idx].isSeparator
            ? pills.first(where: { !$0.isSeparator }) ?? pills[idx]
            : pills[idx]
        executeDockPill(pill)
        // Clear input and focus so dock returns to default state
        searchText = ""
        focusedPillIndex = nil
    }

    private func executeDockPill(_ pill: DockPill) {
        UsageTracker.shared.recordAccess(for: defaultDockPillTrackingIdentifier(pill))
        pill.execute()
    }

    private func directAppActionQuery(for query: String) -> String? {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return nil }
        if let target = L2AppActionRouter.shared.explicitAppTarget(for: q) {
            return target.actionQuery
        }
        if let target = installedAppMenuTarget(for: q) {
            return target.actionQuery
        }
        if let partial = l2AppCompletion ?? bestL2PartialAppCompletion(for: q),
            !partial.actionQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        {
            return partial.actionQuery
        }
        if l2TargetApp != nil {
            return q
        }
        return nil
    }

    @discardableResult
    private func focusFirstDockPillIfAvailable(for query: String) -> Bool {
        let normalizedQuery = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let pillQuery = shouldUseFinderSearchPopover(for: normalizedQuery) ? "" : normalizedQuery
        let pills = buildDockPills(query: pillQuery)
        guard let firstVisibleIndex = pills.firstIndex(where: { !$0.isSeparator }) else {
            return false
        }

        pillNavViaKeyboard = true
        focusedPillIndex = firstVisibleIndex
        return true
    }

    private func isDirectAppActionQuery(_ actionQuery: String) -> Bool {
        let normalized = actionQuery
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
            .replacingOccurrences(of: "[^a-z0-9]+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalized.isEmpty else { return false }
        let tokens = normalized.split(separator: " ")
        return (1...2).contains(tokens.count)
    }

    @discardableResult
    private func executeFocusedOrDirectAppPillIfNeeded() -> Bool {
        let q = searchText.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let pills = buildDockPills(query: q)
        guard !pills.isEmpty else { return false }

        if let idx = focusedPillIndex, idx < pills.count {
            executeFirstOrFocusedPill()
            return true
        }

        guard let actionQuery = directAppActionQuery(for: q),
            isDirectAppActionQuery(actionQuery)
        else {
            return false
        }

        let defaultPill = pills.first(where: { !$0.isSeparator })
        let isPureScopedSelection: Bool = {
            guard let target = l2TargetApp else { return false }
            let aliases = dockPillAppAliases(appName: target.name, bundleId: target.bundleId)
            return aliases.contains(q)
        }()
        let pill =
            isPureScopedSelection
            ? (pills.first(where: { !$0.isSeparator && $0.rankingKind != "appLaunch" }) ?? defaultPill)
            : defaultPill
        guard let pill else { return false }

        let scope = resolveDockScope(for: q)
        let isScopedCLIQuery =
            pill.rankingKind == "cliTool"
            && scope.isExplicitAppScope
            && !scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        if isScopedCLIQuery {
            return false
        }

        executeDockPill(pill)
        searchText = ""
        focusedPillIndex = nil
        return true
    }

    @ViewBuilder
    private var l2UnifiedDockRow: some View {
        let q =
            isL2ContextActive
            ? searchText.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() : ""
        let finderSearchPopoverActive = shouldUseFinderSearchPopover(for: q)
        let pillQuery = finderSearchPopoverActive ? "" : q
        let pills = cachedDockPills
        let explicitAppTarget =
            pillQuery.isEmpty ? nil : L2AppActionRouter.shared.appScopeTarget(for: pillQuery)

        VStack(alignment: .leading, spacing: explicitAppTarget == nil ? 0 : 5) {
            if let explicitAppTarget {
                HStack(spacing: 5) {
                    Image(systemName: "app.badge")
                        .font(.system(size: 9, weight: .semibold))
                        .foregroundStyle(.secondary)
                    Text("\(explicitAppTarget.appName) Actions")
                        .font(.system(size: 10, weight: .semibold))
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                }
                .padding(.horizontal, 4)
                .transition(.opacity.combined(with: .move(edge: .top)))
            }

            // Active selection = files/text/URL right now (not stale clipboard)
            let hasActiveContextSelection: Bool = {
                if !axContext.selectedFilePaths.isEmpty { return true }
                let txt = axContext.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                if !txt.isEmpty { return true }
                switch currentContext {
                case .filesSelected(let u) where !u.isEmpty: return true
                case .textSelected(let t) where !t.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty: return true
                case .url(let s) where !s.isEmpty: return true
                default: return false
                }
            }()
            let hasAnySelection: Bool =
                hasActiveContextSelection || (showGlobalClipboardPill && !globalClipboardText.isEmpty)
            // In global context, only hide app pills when there's a real active selection (not just clipboard)
            let showPinnedRow = q.isEmpty && (pills.isEmpty || (isGlobalContextActive && !hasActiveContextSelection))
            // App search only when in global context with no active selection
            let showGlobalAppSearch = isGlobalContextActive && !hasActiveContextSelection && !q.isEmpty

            HStack(spacing: 6) {
                // Selection/clipboard chip — always visible when there's something selected or copied
                if hasAnySelection {
                    selectionContextChip
                        .transition(.scale(scale: 0.85).combined(with: .opacity))
                }

                if showGlobalAppSearch {
                    globalAppSearchPillRow(query: q)
                        .transition(.opacity.combined(with: .scale(scale: 0.98)))
                } else if showPinnedRow {
                    pinnedAndRecentAppsRow
                        .transition(.opacity.combined(with: .scale(scale: 0.98)))
                } else {
                    // When global context has a selection and user types, filter context pills by query
                    dockPillScrollRow(pills: pills, appQuery: q)
                }
            }
            .animation(.spring(response: 0.2, dampingFraction: 0.8), value: hasAnySelection)
        }
        .padding(.horizontal, 2)
        .animation(.spring(response: 0.25, dampingFraction: 0.8), value: pillQuery)
        .animation(
            .spring(response: 0.22, dampingFraction: 0.85), value: explicitAppTarget?.bundleId
        )
        .onChange(of: pillQuery) { newQuery in
            focusedPillIndex = nil
            focusedAppPillIndex = nil
            if newQuery != lastPillQuery {
                lastPillQuery = newQuery
                cachedDockPills = buildDockPills(query: newQuery)
            }
        }
        .onAppear {
            cachedDockPills = buildDockPills(query: pillQuery)
            lastPillQuery = pillQuery
        }
        .gesture(
            DragGesture(minimumDistance: 20)
                .onEnded { value in
                    let dy = value.translation.height
                    let dx = value.translation.width

                    guard abs(dy) > abs(dx) else { return }

                    if dy > 30 {
                        // Swipe DOWN → Global Context (manual, should not auto-return)
                        if !isGlobalContextActive {
                            withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
                                isGlobalContextActive = true
                            }
                            isGlobalContextAutoActivated = false
                            cachedDockPills = buildDockPills(query: lastPillQuery)
                        }
                    } else if dy < -30 {
                        // Swipe UP
                        if isGlobalContextActive {
                            // Exit Global Context → return to Context Dock
                            dismissContextAndReturnToDock()
                        } else if !showMediaLayer && settings.enableLayer3 {
                            // Context Dock → Media Dock
                            Task {
                                await mediaObserver.refreshNowPlaying()
                                withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                                    showContextInDock = true
                                    showMediaLayer = true
                                }
                                if searchText.isEmpty && !isSearchFieldFocused {
                                    startCollapseTimer()
                                }
                            }
                        }
                    }
                }
        )
    }

    @ViewBuilder
    private var selectionContextChip: some View {
        // Prefer live AX state (axContext) for immediate updates; fall back to currentContext
        let axFiles = axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        let axText = axContext.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        if !axFiles.isEmpty {
            let label = axFiles.count == 1
                ? axFiles[0].lastPathComponent
                : "\(axFiles.count) files"
            let icon = axFiles.count == 1
                ? fileIcon(for: axFiles[0].pathExtension.lowercased())
                : "doc.on.doc.fill"
            selectionChipView(icon: icon, label: label, onDismiss: dismissContextAndReturnToDock)
        } else if !axText.isEmpty {
            let snippet = String(axText.prefix(40))
            selectionChipView(icon: "text.cursor",
                              label: "\"\(snippet)\(axText.count > 40 ? "…" : "")\"",
                              onDismiss: dismissContextAndReturnToDock)
        } else if showGlobalClipboardPill && !globalClipboardText.isEmpty {
            let snippet = String(globalClipboardText.prefix(40))
            let isURL = URL(string: globalClipboardText)?.scheme != nil
            selectionChipView(
                icon: isURL ? "link" : "doc.on.clipboard",
                label: isURL
                    ? (URL(string: globalClipboardText)?.host ?? snippet)
                    : "\"\(snippet)\(globalClipboardText.count > 40 ? "…" : "")\"",
                onDismiss: {
                    showGlobalClipboardPill = false
                    globalClipboardText = ""
                    dismissContextAndReturnToDock()
                }
            )
        } else {
            switch currentContext {
            case .filesSelected(let urls) where !urls.isEmpty:
                let label = urls.count == 1 ? urls[0].lastPathComponent : "\(urls.count) files"
                let icon = urls.count == 1
                    ? fileIcon(for: urls[0].pathExtension.lowercased()) : "doc.on.doc.fill"
                selectionChipView(icon: icon, label: label, onDismiss: dismissContextAndReturnToDock)
            case .textSelected(let text)
            where !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty:
                let t = text.trimmingCharacters(in: .whitespacesAndNewlines)
                selectionChipView(icon: "text.cursor",
                                  label: "\"\(String(t.prefix(40)))\(t.count > 40 ? "…" : "")\"",
                                  onDismiss: dismissContextAndReturnToDock)
            case .url(let urlStr) where !urlStr.isEmpty:
                selectionChipView(icon: "link",
                                  label: URL(string: urlStr)?.host ?? String(urlStr.prefix(40)),
                                  onDismiss: dismissContextAndReturnToDock)
            default:
                EmptyView()
            }
        }
    }

    /// Clears the active global context and returns to the frontmost app's Context-Dock scope.
    private func dismissContextAndReturnToDock() {
        withAnimation(.spring(response: 0.2, dampingFraction: 0.8)) {
            currentContext = .none
            isGlobalContextActive = false
            isGlobalContextAutoActivated = false
            axContext = .empty
        }
        cachedDockPills = buildDockPills(query: lastPillQuery)
        setFrontmostAppContextOnly(reason: "dismiss context chip")
    }

    @ViewBuilder
    private func selectionChipView(icon: String, label: String, onDismiss: @escaping () -> Void) -> some View {
        HStack(spacing: 4) {
            Image(systemName: icon)
                .font(.system(size: 10, weight: .semibold))
                .foregroundStyle(Color.green.opacity(0.85))
            Text(label)
                .font(.system(size: 11, weight: .medium))
                .foregroundStyle(Color.primary.opacity(0.75))
                .lineLimit(1)
                .frame(maxWidth: 130)
            Button(action: onDismiss) {
                Image(systemName: "minus")
                    .font(.system(size: 8, weight: .bold))
                    .foregroundStyle(.secondary)
            }
            .buttonStyle(.plain)
        }
        .padding(.horizontal, 9)
        .padding(.vertical, 5)
        .background(Color.green.opacity(0.10), in: Capsule())
        .overlay(Capsule().strokeBorder(Color.green.opacity(0.25), lineWidth: 0.5))
        .transition(.scale(scale: 0.85).combined(with: .opacity))
    }

    @ViewBuilder
    private func dockPillScrollRow(pills: [DockPill], appQuery: String = "") -> some View {
        // Filtered app icons: pinned + running apps whose name starts with or contains the query.
        // Suppressed in global context with an active selection — queries filter context pills there.
        let filteredApps: [(icon: NSImage?, label: String, bundleId: String?, isRunning: Bool, action: () -> Void)] = {
            guard !appQuery.isEmpty, !isExplicitAppScope, !isGlobalContextActive else { return [] }
            let q = appQuery.lowercased()
            var seen = Set<String>()
            var results: [(icon: NSImage?, label: String, bundleId: String?, isRunning: Bool, action: () -> Void)] = []
            // Pinned apps
            for app in settings.pinnedApps where app.type == .application {
                let name = app.name.lowercased()
                guard name.hasPrefix(q) || (q.count >= 2 && name.contains(q)) else { continue }
                let key = app.bundleIdentifier ?? app.path
                guard seen.insert(key).inserted else { continue }
                let isRunning = runningApp(for: app) != nil
                let icon = resolvedPinnedIcon(for: app)
                let captured = app
                results.append((icon: icon, label: app.name, bundleId: app.bundleIdentifier, isRunning: isRunning, action: { launchPinnedApp(captured) }))
                if results.count >= 5 { break }
            }
            // Running apps not already in pinned
            for app in runningRegularApps where results.count < 5 {
                guard let name = app.localizedName else { continue }
                let lname = name.lowercased()
                guard lname.hasPrefix(q) || (q.count >= 2 && lname.contains(q)) else { continue }
                let key = app.bundleIdentifier ?? "\(app.processIdentifier)"
                guard seen.insert(key).inserted else { continue }
                let icon = resolvedRunningAppIcon(for: app)
                let captured = app
                results.append((icon: icon, label: name, bundleId: app.bundleIdentifier, isRunning: true, action: { activateRunningAppFromDock(captured) }))
            }
            return results
        }()

        ScrollViewReader { proxy in
            ScrollView(.horizontal, showsIndicators: false) {
                LazyHStack(spacing: 6) {
                    if !pills.isEmpty {
                        ForEach(Array(pills.enumerated()), id: \.element.id) { idx, pill in
                            unifiedPillButton(pill: pill, index: idx)
                                .id("pill-\(idx)")
                                .transition(.scale(scale: 0.8).combined(with: .opacity))
                        }
                    } else {
                        Spacer(minLength: 0)
                    }
                }
            }
            .onChange(of: focusedPillIndex) { newIndex in
                guard pillNavViaKeyboard, let idx = newIndex else { return }
                withAnimation(.spring(response: 0.25, dampingFraction: 0.82)) {
                    proxy.scrollTo("pill-\(idx)", anchor: .center)
                }
                if idx < pills.count, pills[idx].isShareAction {
                    showShareSheetForContext()
                }
            }
        }
    }

    private var isExplicitAppScope: Bool {
        resolveDockScope(for: searchText.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()).isExplicitAppScope
    }

    /// Single pill button with focus highlight for keyboard navigation.
    @ViewBuilder
    private func unifiedPillButton(pill: DockPill, index: Int) -> some View {
        if pill.isSeparator {
            // Render as a thin vertical divider with optional app-name label
            HStack(spacing: 3) {
                Rectangle()
                    .fill(Color.secondary.opacity(0.25))
                    .frame(width: 1, height: 16)
                if !pill.name.isEmpty {
                    Text(pill.name)
                        .font(.system(size: 9, weight: .medium))
                        .foregroundStyle(.tertiary)
                        .lineLimit(1)
                }
            }
            .padding(.horizontal, 2)
        } else {
            let accent = accentColor(for: pill.accentColorName)
            let focused = focusedPillIndex == index
            Button {
                executeDockPill(pill)
                searchText = ""
                focusedPillIndex = nil
            } label: {
                HStack(spacing: 5) {
                    if let img = pill.menuItemImage {
                        Image(nsImage: img)
                            .resizable()
                            .interpolation(.high)
                            .aspectRatio(contentMode: .fit)
                            .frame(width: 12, height: 12)
                            .opacity(focused ? 1.0 : 0.85)
                    } else {
                        Image(systemName: pill.icon)
                            .font(.system(size: 10, weight: .semibold))
                            .foregroundStyle(focused ? accent : accent.opacity(0.85))
                    }
                    Text(pill.name)
                        .font(.system(size: 11, weight: .medium))
                        .foregroundStyle(Color.primary.opacity(focused ? 1.0 : 0.85))
                        .lineLimit(1)
                    if let badge = pill.badge {
                        Text(badge)
                            .font(.system(size: 9, weight: .medium))
                            .foregroundStyle(.secondary)
                            .padding(.horizontal, 4).padding(.vertical, 1)
                            .background(.white.opacity(0.08), in: Capsule())
                    }
                }
                .padding(.horizontal, 10).padding(.vertical, 5)
                // Glass effect: thickMaterial base + white specular highlight on top
                .background {
                    if focused {
                        ZStack {
                            Capsule().fill(.ultraThinMaterial)
                            Capsule().fill(
                                LinearGradient(
                                    colors: [.white.opacity(0.22), .white.opacity(0.04)],
                                    startPoint: .top, endPoint: .bottom)
                            )
                            Capsule().strokeBorder(
                                LinearGradient(
                                    colors: [.white.opacity(0.55), accent.opacity(0.35)],
                                    startPoint: .topLeading, endPoint: .bottomTrailing),
                                lineWidth: 0.75)
                        }
                    } else {
                        ZStack {
                            Capsule().fill(.regularMaterial)
                            Capsule().strokeBorder(accent.opacity(0.25), lineWidth: 0.5)
                        }
                    }
                }
                .shadow(color: focused ? accent.opacity(0.18) : .clear, radius: 6, y: 2)
                .scaleEffect(focused ? 1.04 : 1.0)
                .animation(.spring(response: 0.18, dampingFraction: 0.75), value: focused)
            }
            .buttonStyle(.plain)
            .help(pill.name)
            .onHover { hovering in
                if !pillNavViaKeyboard {
                    focusedPillIndex = hovering ? index : nil
                }
            }
            // Right-click context menu — shows Favourite / Unfavourite for menu item pills
            .contextMenu {
                if !pill.menuItemName.isEmpty, !pill.sourceBundleId.isEmpty {
                    Button {
                        settings.toggleFavouriteMenuPill(
                            pill.menuItemName, for: pill.sourceBundleId)
                    } label: {
                        Label(
                            pill.isFavourited ? "Remove from Favourites" : "Add to Favourites",
                            systemImage: pill.isFavourited ? "star.slash" : "star"
                        )
                    }
                }
            }
        }  // end else (non-separator)
    }

    /// Resolve an optional color name string into a SwiftUI Color.
    private func accentColor(for name: String?) -> SwiftUI.Color {
        switch name?.lowercased() {
        case "blue": return .blue
        case "red": return .red
        case "green": return .green
        case "orange": return .orange
        case "yellow": return .yellow
        case "purple": return .purple
        case "indigo": return .indigo
        case "teal": return .teal
        case "pink": return .pink
        case "gray", "grey": return .secondary
        default: return Color.accentColor
        }
    }

    private func resolvedBundleId(for pid: pid_t, fallbackBundleId: String) -> String {
        if pid != 0,
            let bundleId = NSWorkspace.shared.runningApplications.first(
                where: { $0.processIdentifier == pid && !$0.isTerminated }
            )?.bundleIdentifier,
            !bundleId.isEmpty
        {
            return bundleId
        }
        return fallbackBundleId
    }

    /// Smart pills generated from the live AX context snapshot.
    /// These complement user-configured pills with zero-config, always-relevant actions.
    @ViewBuilder
    private var axSmartPills: some View {
        let ax = axContext
        if !ax.isEmpty {
            // Separator before smart pills
            Rectangle().fill(.secondary.opacity(0.2)).frame(width: 1, height: 20)

            // Copy URL — shown when a browser URL is detected
            if let url = ax.currentURL {
                Button {
                    NSPasteboard.general.clearContents()
                    NSPasteboard.general.setString(url, forType: .string)
                } label: {
                    HStack(spacing: 5) {
                        Image(systemName: "link").font(.system(size: 10, weight: .semibold))
                            .foregroundStyle(.teal)
                        Text("Copy URL").font(.system(size: 11, weight: .medium)).lineLimit(1)
                    }
                    .padding(.horizontal, 10).padding(.vertical, 5)
                    .background(.regularMaterial, in: Capsule())
                    .overlay(Capsule().strokeBorder(.teal.opacity(0.3), lineWidth: 0.5))
                }
                .buttonStyle(.plain).help(url)
                .transition(.scale(scale: 0.8).combined(with: .opacity))

                // Ask About Page — send URL to AI
                Button {
                    let prompt = "What is this page about? URL: \(url)"
                    searchText = prompt
                    isAIMode = true
                    showContextInDock = false
                    submitAIQuery()
                } label: {
                    HStack(spacing: 5) {
                        Image(systemName: "sparkles").font(.system(size: 10, weight: .semibold))
                            .foregroundStyle(.indigo)
                        Text("Ask About Page").font(.system(size: 11, weight: .medium)).lineLimit(1)
                    }
                    .padding(.horizontal, 10).padding(.vertical, 5)
                    .background(.regularMaterial, in: Capsule())
                    .overlay(Capsule().strokeBorder(.indigo.opacity(0.3), lineWidth: 0.5))
                }
                .buttonStyle(.plain).help("Ask AI about this page")
                .transition(.scale(scale: 0.8).combined(with: .opacity))
            }

            // Copy Selection — shown when text is selected in the frontmost app
            if let sel = ax.selectedText, !sel.isEmpty {
                Button {
                    NSPasteboard.general.clearContents()
                    NSPasteboard.general.setString(sel, forType: .string)
                } label: {
                    HStack(spacing: 5) {
                        Image(systemName: "text.cursor").font(.system(size: 10, weight: .semibold))
                            .foregroundStyle(.orange)
                        Text("Copy Selection").font(.system(size: 11, weight: .medium)).lineLimit(1)
                    }
                    .padding(.horizontal, 10).padding(.vertical, 5)
                    .background(.regularMaterial, in: Capsule())
                    .overlay(Capsule().strokeBorder(.orange.opacity(0.3), lineWidth: 0.5))
                }
                .buttonStyle(.plain).help(sel.count > 60 ? String(sel.prefix(60)) + "…" : sel)
                .transition(.scale(scale: 0.8).combined(with: .opacity))

                // Ask About Selection
                Button {
                    let text = sel.count > 500 ? String(sel.prefix(500)) : sel
                    searchText = "Explain: \(text)"
                    isAIMode = true
                    showContextInDock = false
                    submitAIQuery()
                } label: {
                    HStack(spacing: 5) {
                        Image(systemName: "sparkles").font(.system(size: 10, weight: .semibold))
                            .foregroundStyle(.indigo)
                        Text("Ask About Selection").font(.system(size: 11, weight: .medium))
                            .lineLimit(1)
                    }
                    .padding(.horizontal, 10).padding(.vertical, 5)
                    .background(.regularMaterial, in: Capsule())
                    .overlay(Capsule().strokeBorder(.indigo.opacity(0.3), lineWidth: 0.5))
                }
                .buttonStyle(.plain)
                .transition(.scale(scale: 0.8).combined(with: .opacity))
            }
        }
    }

    // MARK: - App Shortcuts Dock Row — shown when a smart query (calendar/notes…) or folder is active
    @ViewBuilder
    private var appShortcutsInDock: some View {
        let key = activeSmartQueryKey ?? folderSmartKey
        // contextPanelActions() already includes user shortcuts when searchContextApp != nil,
        // so only pull shortcuts directly for built-in key panels (no searchContextApp)
        let contextActions = contextPanelActions()
        let hasSearchCtx = searchContextApp != nil
        let extraShortcuts: [AppShortcut] =
            hasSearchCtx
            ? []
            : {
                // Merge quick-actions and context-dock shortcuts, deduplicated by name
                var seen = Set<String>()
                let quick = settings.shortcuts(for: key)
                let dock = settings.contextDockShortcuts(for: key)
                for s in quick { seen.insert(s.name) }
                return quick + dock.filter { seen.insert($0.name).inserted }
            }()

        // Context: is there a selected file or text right now?
        let hasFileSelection: Bool =
            folderPreviewSelectedFile != nil
            || (selectedResultIndex.map {
                $0 < searchResults.count && searchResults[$0].filePath != nil
            } ?? false)
            || !axContext.selectedFilePaths.isEmpty
            || {
                switch currentContext {
                case .filesSelected(let urls): return !urls.isEmpty
                default: return false
                }
            }()
        let hasTextSelection: Bool =
            !(axContext.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true)
            || {
                switch currentContext {
                case .textSelected(let text):
                    return !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                default:
                    return false
                }
            }()

        // Filter context-sensitive shortcuts: hide shell/$1 actions when nothing is selected
        let visibleShortcuts = extraShortcuts.filter { sc in
            guard sc.actionType == .shellCommand || sc.actionType == .appleScript else {
                return true
            }
            let v = sc.actionValue
            let needsFile =
                v.contains("$1") || v.contains("$2") || v.contains("$SELECTED_FILES")
                || v.contains("$SELECTED_FILE")
            let needsText = v.contains("$SELECTED_TEXT")
            if needsFile && !hasFileSelection { return false }
            if needsText && !hasTextSelection { return false }
            return true
        }

        let showHint = contextActions.isEmpty && visibleShortcuts.isEmpty

        return ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 8) {
                ForEach(contextActions) { action in
                    dockPillButton(icon: action.icon, label: action.label, action: action.action)
                }
                ForEach(visibleShortcuts) { sc in
                    dockPillButton(icon: sc.iconName, label: sc.name) { executeAppShortcut(sc) }
                }
                if showHint {
                    Text("No quick actions — add some in Settings › App Shortcuts")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .padding(.horizontal, 8)
                }
            }
            .padding(.horizontal, 6)
            .padding(.vertical, 4)
        }
    }

    /// Floating pill-shaped dock button used for all quick actions.
    @ViewBuilder
    private func dockPillButton(icon: String, label: String, action: @escaping () -> Void)
        -> some View
    {
        Button(action: action) {
            HStack(spacing: 5) {
                Image(systemName: icon)
                    .font(.system(size: 12, weight: .semibold))
                Text(label)
                    .font(.system(size: 12, weight: .medium))
                    .lineLimit(1)
            }
            .foregroundStyle(.primary)
            .padding(.horizontal, 11)
            .padding(.vertical, 6)
            .background(.regularMaterial, in: Capsule())
            .overlay(Capsule().strokeBorder(.primary.opacity(0.08), lineWidth: 0.5))
        }
        .buttonStyle(.plain)
        .help(label)
    }

    /// Key used when a folder is open but no app smart query is active
    private var folderSmartKey: String {
        if let path = folderPreviewPath {
            let name = URL(fileURLWithPath: path).lastPathComponent.lowercased()
            if name == "downloads" { return "downloads" }
        }
        return ""
    }

    private func executeAppShortcut(_ sc: AppShortcut) {
        // ── Gather context ───────────────────────────────────────────────
        // Selected file(s): folder preview selection first, then highlighted search result
        var selectedFilePaths: [String] = []
        if let previewFile = folderPreviewSelectedFile, !previewFile.isEmpty {
            selectedFilePaths = [previewFile]
        } else if let idx = selectedResultIndex, idx < searchResults.count,
            let path = searchResults[idx].filePath, !path.isEmpty
        {
            selectedFilePaths = [path]
        }
        // Also pick up any multi-selection from Finder if no in-app selection
        if selectedFilePaths.isEmpty {
            selectedFilePaths = ContextDetector.shared.getFinderSelectedFiles().map { $0.path }
        }

        // Use the app that was frontmost BEFORE ILauncher activated — never ILauncher itself.
        let prevApp = AppDelegate.shared?.previousFrontmostApp

        // Selected text: accessibility API on the pre-ILauncher frontmost app
        let selectedText: String = {
            guard let app = prevApp else { return "" }
            return ContextDetector.shared.getSelectedText(from: app) ?? ""
        }()

        // ── Substitution helper ──────────────────────────────────────────
        func inject(_ value: String) -> String {
            var result = value
            // $1..$N — individual file paths
            for (i, path) in selectedFilePaths.enumerated() {
                let escaped = path.replacingOccurrences(of: "'", with: "'\\''")
                result = result.replacingOccurrences(of: "$\(i + 1)", with: escaped)
            }
            // $SELECTED_FILES — space-separated list of all paths (shell-quoted)
            let allEscaped = selectedFilePaths.map {
                "'\($0.replacingOccurrences(of: "'", with: "\\'"))'"
            }.joined(separator: " ")
            result = result.replacingOccurrences(of: "$SELECTED_FILES", with: allEscaped)
            // $SELECTED_TEXT — text selected in frontmost app
            let textEscaped = selectedText.replacingOccurrences(of: "'", with: "'\\''")
            result = result.replacingOccurrences(of: "$SELECTED_TEXT", with: textEscaped)
            // $FRONTMOST_APP — name of the app that was active before ILauncher opened
            let frontmostName = prevApp?.localizedName ?? ""
            result = result.replacingOccurrences(of: "$FRONTMOST_APP", with: frontmostName)
            // $FRONTMOST_BUNDLE — bundle identifier of the pre-ILauncher app
            let frontmostBundle = prevApp?.bundleIdentifier ?? ""
            result = result.replacingOccurrences(of: "$FRONTMOST_BUNDLE", with: frontmostBundle)
            // AX-read context variables ─────────────────────────────────────────
            // $CURRENT_URL — URL currently open in the frontmost browser/app window
            let axURL = axContext.currentURL ?? ""
            result = result.replacingOccurrences(of: "$CURRENT_URL", with: axURL)
            // $WINDOW_TITLE — title of the frontmost window
            let axTitle = axContext.windowTitle ?? ""
            result = result.replacingOccurrences(of: "$WINDOW_TITLE", with: axTitle)
            // $AX_SELECTED_TEXT — selected text read via AX API (more reliable than clipboard)
            let axSel = axContext.selectedText ?? ""
            result = result.replacingOccurrences(of: "$AX_SELECTED_TEXT", with: axSel)
            return result
        }

        switch sc.actionType {
        case .openURL:
            if let url = URL(string: inject(sc.actionValue)) { NSWorkspace.shared.open(url) }
        case .openFile:
            NSWorkspace.shared.openApplication(
                at: URL(fileURLWithPath: sc.actionValue),
                configuration: NSWorkspace.OpenConfiguration())
        case .shellCommand:
            let cmd = inject(sc.actionValue)
            let ck = activeConsoleKey
            // Always create panel terminal if needed, open drawer, run command in real PTY
            let panelTerm = panelTerminal(for: ck)
            panelShowConsoleMap[ck] = true
            panelTerm.sendCommand(cmd)
            // Give the terminal focus so output is visible and interactive
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
                panelTerm.terminalView.window?.makeFirstResponder(panelTerm.terminalView)
            }
        case .appleScript:
            if let script = NSAppleScript(source: inject(sc.actionValue)) {
                script.executeAndReturnError(nil)
            }
        case .jxa:
            // JXA runs via osascript -l JavaScript, passing selected file + text as argv
            let scriptCode = sc.actionValue
            let ck = activeConsoleKey
            let file1 = selectedFilePaths.first ?? ""
            let selText = selectedText
            Task.detached {
                // Write script to a temp file so we can pass it cleanly
                let tmp = FileManager.default.temporaryDirectory
                    .appendingPathComponent("ilauncher_jxa_\(UUID().uuidString).js")
                try? scriptCode.write(to: tmp, atomically: true, encoding: .utf8)
                defer { try? FileManager.default.removeItem(at: tmp) }
                let proc = Process()
                proc.executableURL = URL(fileURLWithPath: "/usr/bin/osascript")
                var args = ["-l", "JavaScript", tmp.path]
                if !file1.isEmpty { args.append(file1) }
                if !selText.isEmpty { args.append(selText) }
                proc.arguments = args
                let pipe = Pipe()
                proc.standardOutput = pipe
                proc.standardError = pipe
                try? proc.run()
                proc.waitUntilExit()
                let out =
                    String(data: pipe.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8)
                    ?? ""
                // Show JXA output in the panel terminal drawer
                await MainActor.run {
                    self.panelShowConsoleMap[ck] = true
                    for line in out.components(separatedBy: "\n") where !line.isEmpty {
                        self.panelConsoleLinesMap[ck, default: []].append(
                            (line: line, isCommand: false))
                    }
                }
            }
        case .scriptFile:
            // Delegate to AXTriggerRuleEngine which handles all script file execution + notifications
            let envVars: [String: String] = [
                "CD_APP_NAME": frontmostAppName,
                "CD_BUNDLE_ID": frontmostAppBundleID,
                "CD_WINDOW_TITLE": axContext.windowTitle ?? "",
                "CD_SELECTED_TEXT": axContext.selectedText ?? selectedText,
                "CD_URL": axContext.currentURL ?? "",
                "CD_FILE": axContext.selectedFilePaths.first ?? selectedFilePaths.first ?? "",
                "CD_CLIPBOARD": NSPasteboard.general.string(forType: .string) ?? "",
            ]
            AXTriggerRuleEngine.shared.run(
                type: .scriptFile, value: sc.actionValue, envVars: envVars)
        case .menuItem:
            let envVars: [String: String] = [
                "CD_APP_NAME": frontmostAppName,
                "CD_BUNDLE_ID": frontmostAppBundleID,
                "CD_WINDOW_TITLE": axContext.windowTitle ?? "",
                "CD_SELECTED_TEXT": axContext.selectedText ?? selectedText,
                "CD_URL": axContext.currentURL ?? "",
                "CD_FILE": axContext.selectedFilePaths.first ?? selectedFilePaths.first ?? "",
                "CD_CLIPBOARD": NSPasteboard.general.string(forType: .string) ?? "",
            ]
            AXTriggerRuleEngine.shared.run(type: .menuItem, value: sc.actionValue, envVars: envVars)
        }
    }

    private func shellQuote(_ value: String) -> String {
        "'" + value.replacingOccurrences(of: "'", with: "'\\''") + "'"
    }

    private func appPillScriptExtensions(for appKey: String, query: String) -> [AppToolExtension] {
        settings.pillScriptExtensions(for: appKey, query: query, maxCount: query.isEmpty ? 6 : 4)
    }

    private func executeAppToolExtension(_ ext: AppToolExtension, launchQuery: String = "") {
        guard ext.kind == .script,
              let lang = ext.scriptLanguage,
              !ext.toolPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return
        }

        let queryText = launchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        let selectedFile: String = {
            if let previewFile = folderPreviewSelectedFile, !previewFile.isEmpty { return previewFile }
            if let idx = selectedResultIndex, idx < searchResults.count,
               let path = searchResults[idx].filePath, !path.isEmpty {
                return path
            }
            if let finderSelected = ContextDetector.shared.getFinderSelectedFiles().first?.path, !finderSelected.isEmpty {
                return finderSelected
            }
            if let axSelected = axContext.selectedFilePaths.first, !axSelected.isEmpty {
                return axSelected
            }
            return ""
        }()

        let fallbackQuery = axContext.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let effectiveQuery = queryText.isEmpty ? fallbackQuery : queryText
        let command = [
            lang.runCommand(scriptPath: ext.toolPath),
            shellQuote(selectedFile),
            shellQuote(effectiveQuery)
        ].joined(separator: " ")

        let ck = activeConsoleKey
        let panelTerm = panelTerminal(for: ck)
        panelShowConsoleMap[ck] = true
        panelTerm.sendCommand(command)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
            panelTerm.terminalView.window?.makeFirstResponder(panelTerm.terminalView)
        }
    }

    // MARK: - File-Type Extensions Dock Row — shown when a file result is highlighted
    private var selectedResultHasFileTypeExtensions: Bool {
        // True if we have context-based extensions for the selected file/result
        // (context extensions already handle file-type matching via their trigger system)
        guard let idx = selectedResultIndex, idx < searchResults.count else {
            return !l2ContextExtensions.isEmpty
                && !l2ContextExtensions.filter {
                    switch $0.matchReason {
                    case .fileTypeMatch: return true
                    default: return false
                    }
                }.isEmpty
        }
        let result = searchResults[idx]
        return (result.type == .file || result.type == .document) && !l2ContextExtensions.isEmpty
    }

    /// Shortcuts relevant to the currently highlighted search result's file type
    private var fileTypeShortcutsForSelection: [AppShortcut] {
        // File selected inside folder preview takes priority
        if let selectedFile = folderPreviewSelectedFile, !selectedFile.isEmpty {
            let ext = URL(fileURLWithPath: selectedFile).pathExtension.lowercased()
            return fileTypeShortcuts(for: ext)
        }
        guard let idx = selectedResultIndex,
            idx < searchResults.count
        else { return [] }
        let result = searchResults[idx]
        guard result.type == .file || result.type == .document else { return [] }
        let ext =
            (result.filePath.map { URL(fileURLWithPath: $0).pathExtension.lowercased() }) ?? ""
        return fileTypeShortcuts(for: ext)
    }

    /// Name of the currently selected file in the folder preview (for display)
    private var selectedFolderFileName: String? {
        guard let path = folderPreviewSelectedFile, !path.isEmpty else { return nil }
        return URL(fileURLWithPath: path).lastPathComponent
    }

    private func fileTypeShortcuts(for ext: String) -> [AppShortcut] {
        // Map common file extensions to app shortcut keys
        // Users can define their own shortcuts for these keys in Settings › App Shortcuts
        let key: String
        switch ext {
        case "pdf": key = "pdf"
        case "jpg", "jpeg", "png", "heic", "gif", "webp", "tiff": key = "image"
        case "mp4", "mov", "avi", "mkv", "m4v": key = "video"
        case "mp3", "aac", "flac", "wav", "m4a": key = "audio"
        case "zip", "rar", "7z", "tar", "gz": key = "archive"
        case "doc", "docx", "pages": key = "document"
        case "xls", "xlsx", "numbers", "csv": key = "spreadsheet"
        case "ppt", "pptx", "key": key = "presentation"
        case "swift", "py", "js", "ts", "rb", "go", "rs", "kt": key = "code"
        default: return []
        }
        return settings.shortcuts(for: key)
    }

    /// Unified context-based dock row shown when a file/result is selected.
    /// Uses the scoring system from LayeredExtensionManager — no hardcoded AppShortcut file-type mapping.
    @ViewBuilder
    private var fileTypeExtensionsInDock: some View {
        if l2ContextExtensions.isEmpty {
            pinnedAppsRow
        } else {
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    // File name chip (folder preview only)
                    if let fileName = selectedFolderFileName {
                        let ext = URL(fileURLWithPath: folderPreviewSelectedFile ?? "")
                            .pathExtension.lowercased()
                        HStack(spacing: 5) {
                            Image(systemName: fileIcon(for: ext))
                                .font(.system(size: 11))
                                .foregroundStyle(.secondary)
                            Text(fileName)
                                .font(.system(size: 11, weight: .medium))
                                .foregroundStyle(.secondary)
                                .lineLimit(1)
                                .frame(maxWidth: 120)
                        }
                        .padding(.horizontal, 9)
                        .padding(.vertical, 5)
                        .background(.secondary.opacity(0.12), in: Capsule())
                    }

                    // Context-based action pills — auto-scored by file type, app, selection
                    ForEach(l2ContextExtensions, id: \.ilExtension.id) { result in
                        L2ExtensionChipButton(
                            extensionResult: result,
                            currentContext: currentContext,
                            onExecute: executeL2Extension
                        )
                    }
                }
                .padding(.horizontal, 4)
            }
        }
    }

    private var searchBarSection: some View {
        Group {
            if settings.effectiveDockAtBottom {
                // Dock mode: Results above, dock pinned at bottom — all in one sheet
                let hasResultsToShowBottom =
                    !searchResults.isEmpty || (!searchText.isEmpty && !isL2ContextActive)
                    || (isAIMode && (!aiChatMessages.isEmpty || isAILoading || aiChatStreamingMessageId != nil)) || showFolderPreview
                    || searchContextApp != nil
                    || activeSmartQueryKey != nil
                    || (showContextInDock && (!l2ChatMessages.isEmpty || l2IsLoading))
                    || shouldShowFinderSearchResultsPanel(for: searchText)
                VStack(spacing: 0) {
                    if hasResultsToShowBottom {
                        resultsContentView
                            .frame(minHeight: 0, maxHeight: isAIMode ? 500 : (showFolderPreview ? 600 : 400))
                            .transition(.opacity)
                        if !isAIMode {
                            Divider().opacity(0.12)
                        }
                    }
                    dockBaseView(inDockMode: true)
                }
                .frame(maxWidth: .infinity)
            } else {
                // Normal mode: Dock + results in ONE unified sheet
                let hasResultsToShow =
                    !searchResults.isEmpty
                    || (!searchText.isEmpty && !isL2ContextActive)
                    || (isAIMode && (!aiChatMessages.isEmpty || isAILoading || aiChatStreamingMessageId != nil))
                    || showFolderPreview
                    || (showContextInDock && (!l2ChatMessages.isEmpty || l2IsLoading))
                    || searchContextApp != nil
                    || activeSmartQueryKey != nil
                    || shouldShowFinderSearchResultsPanel(for: searchText)

                VStack(spacing: 0) {
                    dockBaseView(inDockMode: false)

                    if hasResultsToShow {
                        // Hide divider in AI chat mode — the chat section connects seamlessly
                        if !isAIMode {
                            Divider().opacity(0.12)
                        }
                        resultsContentView
                            // AI chat drives its own height via calculatedHeight; other modes cap at 400
                            .frame(minHeight: 0, maxHeight: isAIMode ? 500 : (showFolderPreview ? 600 : 400))
                            .transition(.opacity)
                    }
                }
                .frame(maxWidth: .infinity)
            }
        }
        .frame(width: visibleDockWidth, alignment: .leading)
        .frame(width: calculatedWidth, alignment: .leading)
        .background(alignment: .leading) {
            // Keep the NSVisualEffectView at the full dock width so macOS samples the
            // same wallpaper region while the visible dock masks/shrinks from the right.
            GlassBackground(cornerRadius: 20)
                .frame(width: calculatedWidth)
        }
        .mask(alignment: .leading) {
            RoundedRectangle(cornerRadius: 20, style: .continuous)
                .frame(width: visibleDockWidth)
        }
        .ifLet(resolvedColorScheme) { view, scheme in
            view.environment(\.colorScheme, scheme)
        }
    }

    // MARK: - Dock Base View (always visible, doesn't move)
    @ViewBuilder
    private func dockBaseView(inDockMode: Bool) -> some View {
        let outerVerticalPadding: CGFloat = 10
        let inputVerticalPadding: CGFloat = 8
        let pinnedRowHeight: CGFloat = 48

        VStack(spacing: 0) {
            HStack(spacing: 12) {
                // Search field with darker glassy background
                HStack(spacing: 10) {
                    // Search icon
                    if isAIMode {
                        Menu {
                            ForEach(AIProvider.allCases) { provider in
                                Button(action: {
                                    settings.selectedAIProvider = provider
                                }) {
                                    HStack {
                                        Image(systemName: provider.iconName)
                                        Text(provider.shortName)
                                        Spacer()
                                        if settings.selectedAIProvider == provider {
                                            Image(systemName: "checkmark")
                                        }
                                    }
                                }
                            }

                            Divider()

                            Button("AI Settings...") {
                                openSettings()
                            }
                        } label: {
                            Image(systemName: settings.selectedAIProvider.iconName)
                                .foregroundStyle(providerColor)
                                .font(.system(size: 16, weight: .medium))
                        }
                        .menuStyle(.borderlessButton)
                        .fixedSize()
                        .onHover { hovering in
                            isHoveringSearchIcon = hovering
                            if hovering {
                                expandSearchBar()
                            } else {
                                // Start collapse timer when stopping hover (if no input and not focused)
                                if searchText.isEmpty && !isSearchFieldFocused {
                                    startCollapseTimer()
                                }
                            }
                        }
                        .help("Select AI Provider")
                    } else {
                        Button(action: {
                            let typedAppIcon = typedL2AppIcon(for: searchText)
                            let canToggleGlobalContext =
                                showContextInDock
                                && settings.enableFrontmostDetection
                                && l2TargetApp == nil
                                && typedAppIcon == nil
                                && searchContextApp == nil
                                && activeSmartQueryKey == nil

                            if canToggleGlobalContext {
                                isGlobalContextActive.toggle()
                                // Clear clipboard pill when manually exiting global context
                                if !isGlobalContextActive {
                                    showGlobalClipboardPill = false
                                    globalClipboardText = ""
                                }
                            }

                            // Click toggles: collapse if expanded, expand if collapsed
                            withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                                if isSearchBarExpanded && searchText.isEmpty
                                    && !isSearchFieldFocused
                                {
                                    isSearchBarExpanded = false
                                } else {
                                    expandSearchBar()
                                }
                            }
                            updateWindowSize()
                        }) {
                            // Globe on L3, app icon on L2 (target override or frontmost), magnifying glass on L1
                            if showContextInDock && settings.enableFrontmostDetection {
                                // l2TargetApp overrides frontmost icon after Tab completion
                                let typedAppIcon = typedL2AppIcon(for: searchText)
                                let displayIcon =
                                    l2TargetApp?.icon ?? typedAppIcon?.icon ?? (isGlobalContextActive ? nil : frontmostAppIcon)
                                if isGlobalContextActive && l2TargetApp == nil && typedAppIcon == nil {
                                    let selectionActive: Bool = {
                                        if !axContext.selectedFilePaths.isEmpty { return true }
                                        if let t = axContext.selectedText,
                                            !t.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                                        { return true }
                                        if showGlobalClipboardPill && !globalClipboardText.isEmpty { return true }
                                        switch currentContext {
                                        case .filesSelected(let u): return !u.isEmpty
                                        case .textSelected(let t):
                                            return !t.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                                        case .url(let s):
                                            return !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                                        default: return false
                                        }
                                    }()
                                    Image(systemName: "globe")
                                        .foregroundStyle(
                                            selectionActive
                                                ? Color.green.opacity(isHoveringSearchIcon ? 1.0 : 0.85)
                                                : .secondary.opacity(isHoveringSearchIcon ? 0.8 : 0.65)
                                        )
                                        .font(.system(size: 18, weight: .semibold))
                                        .frame(width: 24, height: 24)
                                        .animation(.easeInOut(duration: 0.18), value: selectionActive)
                                } else if let appIcon = displayIcon {
                                    Image(nsImage: appIcon)
                                        .resizable()
                                        .aspectRatio(contentMode: .fit)
                                        .frame(width: 20, height: 20)
                                        .opacity(isHoveringSearchIcon ? 1.0 : 0.8)
                                        .transition(.scale(scale: 0.7).combined(with: .opacity))
                                        .id(
                                            l2TargetApp?.bundleId ?? typedAppIcon?.bundleId
                                                ?? frontmostAppBundleID
                                        )  // triggers animation on change
                                } else {
                                    Image(systemName: "magnifyingglass")
                                        .foregroundStyle(
                                            .secondary.opacity(isHoveringSearchIcon ? 0.8 : 0.5)
                                        )
                                        .font(.system(size: 18, weight: .semibold))
                                        .frame(width: 24, height: 24)
                                }
                            } else {
                                Image(systemName: "magnifyingglass")
                                    .foregroundStyle(
                                        .secondary.opacity(isHoveringSearchIcon ? 0.8 : 0.5)
                                    )
                                    .font(.system(size: 18, weight: .semibold))
                                    .frame(width: 24, height: 24)
                            }
                        }
                        .buttonStyle(.plain)
                        .onHover { hovering in
                            isHoveringSearchIcon = hovering
                            if hovering && !suppressHoverExpand {
                                expandSearchBar()
                            }
                        }
                        .help(
                            isGlobalContextActive
                                ? "Switch to frontmost app context"
                                : "Switch to Global Context"
                        )
                        // Hide standalone icon when scope badge is pinned — icon lives inside the badge
                        .opacity(l2TargetApp != nil && showContextInDock ? 0 : 1)
                        .frame(width: l2TargetApp != nil && showContextInDock ? 0 : nil)
                    }

                    // Spotlight-style app context chip — shown after Tab/→ on app result
                    if let ctx = searchContextApp, !showContextInDock {
                        HStack(spacing: 5) {
                            if let icon = ctx.icon {
                                Image(nsImage: icon)
                                    .resizable()
                                    .aspectRatio(contentMode: .fit)
                                    .frame(width: 16, height: 16)
                                    .clipShape(RoundedRectangle(cornerRadius: 3))
                            }
                            Text(ctx.name)
                                .font(.system(size: 13, weight: .medium))
                                .foregroundStyle(.primary)
                                .lineLimit(1)
                            Button(action: { clearSearchContext() }) {
                                Image(systemName: "xmark.circle.fill")
                                    .font(.system(size: 11))
                                    .foregroundStyle(.secondary.opacity(0.7))
                            }
                            .buttonStyle(.plain)
                        }
                        .padding(.horizontal, 8)
                        .padding(.vertical, 4)
                        .background(
                            Color.accentColor.opacity(0.12),
                            in: RoundedRectangle(cornerRadius: 7, style: .continuous)
                        )
                        .overlay(
                            RoundedRectangle(cornerRadius: 7, style: .continuous)
                                .strokeBorder(Color.accentColor.opacity(0.2), lineWidth: 0.5)
                        )
                    }

                    // Pinned L2 scope badge — icon + divider only (compact).
                    if let target = l2TargetApp, showContextInDock {
                        HStack(spacing: 6) {
                            AppBundleIconView(
                                bundleId: target.bundleId,
                                fallbackSymbol: target.bundleId.hasPrefix("cli://")
                                    ? "terminal.fill" : "app.fill",
                                size: 18, cornerRadius: 4
                            )
                            Rectangle()
                                .fill(Color.primary.opacity(0.15))
                                .frame(width: 1, height: 18)
                        }
                        .padding(.leading, 4)
                        .padding(.trailing, 2)
                        .transition(.scale(scale: 0.85, anchor: .leading).combined(with: .opacity))
                    }

                    // Text field - visible when expanded (auto-collapses on all layers)
                    if isSearchBarExpanded {
                        let selectedResult: SearchResult? = {
                            guard let idx = selectedResultIndex, idx < searchResults.count,
                                !isAIMode, !isL2ContextActive, activeSmartQueryKey == nil, searchContextApp == nil
                            else { return nil }
                            return searchResults[idx]
                        }()
                        // Spotlight-style: show result name in bar whenever a result is selected (even while typing)
                        let showingResultPreview = selectedResult != nil

                        ZStack(alignment: .leading) {
                            // Selected result preview (Spotlight-style: "Visual Studio Code.app — Open")
                            if let result = selectedResult {
                                // Intelligent inline completion:
                                // • Prefix match  → show typed text (invisible spacer) + greyed remainder + action
                                // • Fuzzy match   → show full result name + action
                                let title = result.title
                                let typed = searchText
                                let isPrefixMatch = title.lowercased().hasPrefix(typed.lowercased())

                                HStack(spacing: 0) {
                                    if isPrefixMatch && !typed.isEmpty {
                                        // Typed portion — invisible spacer so grey completion aligns after cursor
                                        Text(typed)
                                            .font(.system(size: 15))
                                            .foregroundStyle(.clear)
                                        // Grey completion (the "remaining" part)
                                        Text(String(title.dropFirst(typed.count)))
                                            .font(.system(size: 15))
                                            .foregroundStyle(.secondary.opacity(0.45))
                                            .lineLimit(1)
                                    } else {
                                        // Fuzzy match — show full name in primary color
                                        Text(title)
                                            .font(.system(size: 15, weight: .medium))
                                            .foregroundStyle(.primary)
                                            .lineLimit(1)
                                    }
                                    // Action hint
                                    Text("  —  \(selectedResultAction(result))")
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.35))
                                }
                            } else if isL2ContextActive, l2TargetApp == nil,
                                let completion = l2AppCompletion,
                                !completion.ghost.isEmpty,
                                completion.actionQuery.trimmingCharacters(
                                    in: .whitespacesAndNewlines
                                ).isEmpty,
                                !searchText.isEmpty,
                                !searchText.contains(" ")
                            {
                                // L2 partial app autocomplete ghost text: "sa" → "sa[fari]  — Tab to select"
                                HStack(spacing: 0) {
                                    Text(searchText)
                                        .font(.system(size: 15))
                                        .foregroundStyle(.clear)  // invisible spacer — aligns with real TextField cursor
                                    Text(completion.ghost)
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.4))
                                        .lineLimit(1)
                                    Text("  — Tab to select")
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.25))
                                }
                            } else if searchText.isEmpty {
                                // Normal placeholders (always visible when field is empty)
                                if let ctx = searchContextApp {
                                    // Context panel (file, folder, app, contact, etc.)
                                    Text(
                                        remPanelIsProcessing
                                            ? "Processing…" : "Ask AI about \(ctx.name)…"
                                    )
                                    .foregroundStyle(.secondary.opacity(0.5))
                                    .font(.system(size: 15, weight: .regular))
                                    .lineLimit(1)
                                    .truncationMode(.tail)
                                } else if let key = activeSmartQueryKey {
                                    // Built-in panel (reminders, calendar, notes, etc.)
                                    let label =
                                        settings.customAppEntries.first(where: { $0.key == key })?
                                        .label ?? key.capitalized
                                    Text(
                                        remPanelIsProcessing
                                            ? "Processing…" : "Ask AI about \(label)…"
                                    )
                                    .foregroundStyle(.secondary.opacity(0.5))
                                    .font(.system(size: 15, weight: .regular))
                                    .lineLimit(1)
                                    .truncationMode(.tail)
                                } else if showContextInDock
                                    && !dockScopeDisplayName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                                {
                                    // L2: show the active dock scope
                                    Text(dockScopeDisplayName)
                                        .foregroundStyle(.secondary.opacity(0.5))
                                        .font(.system(size: 15, weight: .regular))
                                } else {
                                    Text(
                                        isAIMode
                                            ? "Ask \(settings.selectedAIProvider.shortName)..."
                                            : "Context-Dock"
                                    )
                                    .foregroundStyle(.secondary.opacity(0.5))
                                    .font(.system(size: 15, weight: .regular))
                                }
                            }

                            TextField("", text: $searchText)
                                .textFieldStyle(.plain)
                                .font(.system(size: 15))
                                .focused($isSearchFieldFocused)
                                // For prefix match: TextField stays visible (shows typed text + cursor).
                                // For fuzzy match or empty: hide it so the full result name shows cleanly.
                                .opacity(
                                    {
                                        if let result = selectedResult {
                                            let isPrefixMatch = result.title.lowercased().hasPrefix(
                                                searchText.lowercased())
                                            return (isPrefixMatch && !searchText.isEmpty) ? 1 : 0
                                        }
                                        return 1
                                    }()
                                )
                                .onChange(of: searchText) { oldValue, newValue in
                                    // In L2 context dock mode, pills filter in the pill row —
                                    // do NOT run L1 search (which would expand the window with results).
                                    if !isAIMode && !showContextInDock {
                                        performSearch()
                                    }
                                    // Trigger cross-app menu loading outside body evaluation
                                    if isL2ContextActive {
                                        let finderFolderSearchActive =
                                            isFinderFolderSearchModeEnabled(for: newValue)
                                        if finderFolderSearchActive {
                                            l2AppCompletion = nil
                                        } else {
                                            showL2ResultsPopover = false
                                            triggerCrossAppMenuLoadIfNeeded(for: newValue)
                                        }
                                        scheduleFinderSemanticSearchIfNeeded(for: newValue)
                                    }
                                    // Update partial app autocomplete for L2
                                    if isL2ContextActive {
                                        let trimmed = newValue.trimmingCharacters(in: .whitespaces)
                                        if shouldUseFinderSearchPopover(for: trimmed) {
                                            l2AppCompletion = nil
                                        } else if trimmed.isEmpty
                                            || L2AppActionRouter.shared.appScopeTarget(
                                                for: trimmed) != nil
                                            || installedAppMenuTarget(for: trimmed) != nil
                                        {
                                            l2AppCompletion = nil
                                        } else {
                                            l2AppCompletion = bestL2PartialAppCompletion(
                                                for: trimmed
                                            )
                                        }
                                        // Only clear scope when the user explicitly targets a DIFFERENT app.
                                        // If they type a plain query (e.g. "brew update") while Terminal
                                        // scope is active, keep the scope — that's their query FOR Terminal.
                                        if let target = l2TargetApp, !trimmed.isEmpty {
                                            if let otherTarget = L2AppActionRouter.shared.appScopeTarget(
                                                for: trimmed.lowercased()),
                                                otherTarget.bundleId != target.bundleId
                                            {
                                                withAnimation(.easeInOut(duration: 0.15)) {
                                                    l2TargetApp = nil
                                                }
                                                if searchContextApp?.resultType == .application {
                                                    clearSearchContext(preserveQuery: true)
                                                }
                                            }
                                        }
                                    }
                                    if isL2ContextActive || isAIMode {
                                        scheduleBrowserContextWarmup(reason: "query changed")
                                    }
                                    resetCollapseTimer()
                                }
                                .onChange(of: isSearchFieldFocused) { oldValue, newValue in
                                    if newValue {
                                        collapseTimer?.cancel()
                                    } else {
                                        if searchText.isEmpty {
                                            startCollapseTimer()
                                        }
                                    }
                                }
                                .onSubmit {
                                    if isL2ContextActive {
                                        enforceL2ContextMode()
                                        let trimmed = searchText.trimmingCharacters(
                                            in: .whitespacesAndNewlines
                                        )
                                        if shouldUseFinderSearchPopover(for: trimmed) {
                                            if let firstResult = finderSemanticResults.first {
                                                executeFinderFolderSearchResult(firstResult)
                                            }
                                            return
                                        }
                                        if focusedPillIndex != nil,
                                            executeFocusedOrDirectAppPillIfNeeded()
                                        {
                                            return
                                        }
                                        if launchTypedAppMatchIfNeeded() {
                                            return
                                        }
                                        guard !trimmed.isEmpty else { return }
                                        if executeFocusedOrDirectAppPillIfNeeded() {
                                            return
                                        }
                                        handleL2Query(trimmed)
                                    } else if isAIMode {
                                        if launchTypedAppMatchIfNeeded() {
                                            return
                                        }
                                        let q = searchText.trimmingCharacters(
                                            in: .whitespacesAndNewlines
                                        )
                                        if q.count > 3 {
                                            submitAIQuery()
                                        }
                                    } else {
                                        executeSelectedResult()
                                    }
                                }
                        }
                        .transition(.opacity.combined(with: .scale(scale: 0.95, anchor: .leading)))

                        // Trailing area: result icon OR clear button OR AI controls
                        if let result = selectedResult {
                            // Spotlight-style: show result icon on the right while a result is selected
                            if let icon = result.icon {
                                Image(nsImage: icon)
                                    .resizable()
                                    .aspectRatio(contentMode: .fit)
                                    .frame(width: 28, height: 28)
                                    .clipShape(
                                        RoundedRectangle(cornerRadius: 6, style: .continuous)
                                    )
                                    .shadow(radius: 2)
                            }
                        } else if isAIMode {
                            aiModeControls
                        } else if !searchText.isEmpty {
                            Button(action: {
                                searchText = ""
                                searchResults = []
                                selectedResultIndex = nil
                            }) {
                                Image(systemName: "xmark.circle.fill")
                                    .foregroundStyle(.secondary.opacity(0.5))
                                    .font(.system(size: 14))
                            }
                            .buttonStyle(.plain)
                            .help("Clear")
                        } else if showContextInDock, l2TargetApp == nil,
                            frontmostAppBundleID == "com.apple.finder",
                            !isGlobalContextActive
                        {
                            addFinderFolderButton
                        } else if showContextInDock, l2TargetApp == nil,
                            AXWebReader.shared.isBrowser(bundleId: frontmostAppBundleID)
                        {
                            safariTabsButton
                        }
                    }
                }
                .padding(.horizontal, isSearchBarExpanded ? 12 : 8)
                .padding(.vertical, inputVerticalPadding)
                .frame(maxWidth: isSearchBarExpanded ? .infinity : 44)
                .background {
                    // Inner search field glass — tinted with app icon dominant color when scoped
                    let inAppScope = l2TargetApp != nil && showContextInDock
                    let scopeColor: SwiftUI.Color = l2TargetApp?.icon?.dominantSwiftUIColor ?? SwiftUI.Color.accentColor
                    ZStack {
                        RoundedRectangle(cornerRadius: 12, style: .continuous)
                            .fill(Color.black.opacity(0.18))
                        if inAppScope {
                            RoundedRectangle(cornerRadius: 12, style: .continuous)
                                .fill(
                                    LinearGradient(
                                        gradient: Gradient(colors: [
                                            scopeColor.opacity(0.18),
                                            scopeColor.opacity(0.05)
                                        ]),
                                        startPoint: .leading,
                                        endPoint: .trailing
                                    )
                                )
                        }
                        RoundedRectangle(cornerRadius: 12, style: .continuous)
                            .strokeBorder(
                                inAppScope ? scopeColor.opacity(0.40) : Color.white.opacity(0.08),
                                lineWidth: inAppScope ? 1.0 : 0.75
                            )
                    }
                    .animation(.easeInOut(duration: 0.25), value: inAppScope)
                    .animation(.easeInOut(duration: 0.3), value: l2TargetApp?.bundleId)
                }
                .onHover { hovering in
                    isHoveringInputField = hovering

                    // Auto-shrink when mouse leaves input field (if no text and not focused)
                    if !hovering && searchText.isEmpty && !isSearchFieldFocused {
                        startCollapseTimer()
                    }
                }
                .animation(
                    .spring(response: 0.3, dampingFraction: 0.75), value: isSearchBarExpanded)

                // Pinned apps or context chips/AI extensions or browser (3-layer swipeable)
                HStack(spacing: 8) {
                    Group {
                        if showMediaLayer {
                            mediaControlsInDock
                                .transition(.opacity.combined(with: .move(edge: .trailing)))
                        } else if activeSmartQueryKey != nil {
                            appShortcutsInDock
                                .transition(.opacity)
                        } else if showContextInDock {
                            if isAIMode {
                                // AI chat mode: always show running/pinned apps for quick reference
                                pinnedAndRecentAppsRow
                                    .transition(.opacity)
                            } else if hasAIExtensionsToShow {
                                aiExtensionsInDock
                                    .transition(.opacity)
                            } else {
                                l2UnifiedDockRow
                                    .transition(.opacity)
                            }
                        } else {
                            pinnedAndRecentAppsRow
                                .transition(.opacity)
                        }
                    }
                    .frame(maxWidth: 400)
                    .frame(height: pinnedRowHeight)  // Fixed height to prevent jumping

                    // Right icon: profile/bell (media only lives in L3 — no indicator here)
                    if !showMediaLayer
                        && (settings.enableLayer2 || (isAIMode && hasAIExtensionsToShow)
                            || notificationManager.unreadCount > 0)
                    {
                        ZStack(alignment: .topTrailing) {
                            Button(action: {
                                withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                                    showNotificationDock.toggle()
                                    if showNotificationDock { notifDockTab = 0 }
                                }
                            }) {
                                if let profileImage = userProfileImage {
                                    Image(nsImage: profileImage)
                                        .resizable()
                                        .aspectRatio(contentMode: .fill)
                                        .frame(width: 28, height: 28)
                                        .clipShape(Circle())
                                        .overlay(
                                            Circle().strokeBorder(
                                                Color.white.opacity(0.2), lineWidth: 1))
                                } else {
                                    Image(systemName: "person.circle.fill")
                                        .font(.system(size: 28))
                                        .foregroundStyle(
                                            notificationManager.unreadCount > 0
                                                ? Color.primary : Color.secondary.opacity(0.6))
                                }
                            }
                            .buttonStyle(.plain)
                            .popover(isPresented: $showNotificationDock, arrowEdge: .top) {
                            NotificationDockView(
                                    selectedTab: $notifDockTab,
                                    profileImage: userProfileImage,
                                    onClose: {
                                        withAnimation(.spring(response: 0.25, dampingFraction: 0.85)) {
                                            showNotificationDock = false
                                        }
                                    },
                                    onOpenSettings: { openSettings() }
                                )
                                .frame(width: notificationDockPopoverWidth, alignment: .trailing)
                                .background(.clear)
                                .ifLet(resolvedColorScheme) { view, scheme in
                                    view.environment(\.colorScheme, scheme)
                                }
                            }
                            .help(
                                showNotificationDock
                                    ? "Close Notifications"
                                    : notificationManager.unreadCount > 0
                                        ? "\(notificationManager.unreadCount) unread notification(s)"
                                        : "Notifications")

                            // Notification badge
                            if notificationManager.unreadCount > 0 {
                                ZStack {
                                    Circle().fill(Color.red).frame(width: 14, height: 14)
                                    Text(
                                        notificationManager.unreadCount > 9
                                            ? "9+" : "\(notificationManager.unreadCount)"
                                    )
                                    .font(.system(size: 8, weight: .bold)).foregroundStyle(.white)
                                }
                                .offset(x: 4, y: -4)
                            }
                        }
                    }
                }
                .onHover { hovering in
                    isHoveringDockArea = hovering
                    // When mouse enters the dock area, switch from keyboard nav to hover nav
                    if hovering { pillNavViaKeyboard = false }
                }
                .animation(.spring(response: 0.3, dampingFraction: 0.75), value: showContextInDock)
                .animation(.spring(response: 0.28, dampingFraction: 0.82), value: showMediaLayer)
                if showMediaLayer, mediaObserver.duration > 0 {
                    GeometryReader { geo in
                        ZStack(alignment: .leading) {
                            Rectangle().fill(Color.primary.opacity(0.08))
                            Rectangle()
                                .fill(Color.accentColor.opacity(0.8))
                                .frame(
                                    width: max(
                                        0,
                                        geo.size.width
                                            * CGFloat(
                                                mediaObserver.elapsed
                                                    / max(mediaObserver.duration, 1)
                                            )
                                    )
                                )
                        }
                    }
                    .frame(height: 3)
                    .padding(.horizontal, 12)
                    .padding(.bottom, 4)
                    .transition(.opacity)
                }
            }
            .frame(maxWidth: .infinity)
            .padding(.horizontal, 12)
            .padding(.vertical, outerVerticalPadding)
        }
        .frame(maxWidth: .infinity)
    }

    @ViewBuilder
    private var mediaControlsInDock: some View {
        HStack(spacing: 8) {
            Group {
                if let art = mediaObserver.artworkImage {
                    Image(nsImage: art)
                        .resizable()
                        .aspectRatio(contentMode: .fill)
                } else if let icon = mediaObserver.appIcon {
                    Image(nsImage: icon)
                        .resizable()
                        .aspectRatio(contentMode: .fit)
                } else {
                    RoundedRectangle(cornerRadius: 7, style: .continuous)
                        .fill(Color.primary.opacity(0.10))
                        .overlay(
                            Image(systemName: "music.note")
                                .font(.system(size: 13, weight: .semibold))
                                .foregroundStyle(.secondary)
                        )
                }
            }
            .frame(width: 34, height: 34)
            .clipShape(RoundedRectangle(cornerRadius: 7, style: .continuous))

            VStack(alignment: .leading, spacing: 1) {
                Text(
                    mediaObserver.title.isEmpty
                        ? (mediaObserver.appName.isEmpty ? "Now Playing" : mediaObserver.appName)
                        : mediaObserver.title
                )
                .font(.system(size: 12, weight: .semibold))
                .foregroundStyle(.primary)
                .lineLimit(1)

                Text(mediaObserver.artist.isEmpty ? mediaObserver.appName : mediaObserver.artist)
                    .font(.system(size: 10, weight: .medium))
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
            }
            .frame(maxWidth: .infinity, alignment: .leading)

            HStack(spacing: 4) {
                compactMediaButton(systemName: "gobackward.15") {
                    mediaObserver.skipBack()
                }
                compactMediaButton(
                    systemName: mediaObserver.isPlaying ? "pause.fill" : "play.fill",
                    filled: true
                ) {
                    mediaObserver.togglePlayPause()
                }
                compactMediaButton(systemName: "goforward.15") {
                    mediaObserver.skipForward()
                }
            }
        }
        .frame(maxWidth: .infinity)
    }

    @ViewBuilder
    private func compactMediaButton(
        systemName: String,
        filled: Bool = false,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            Image(systemName: systemName)
                .font(.system(size: filled ? 13 : 12, weight: .semibold))
                .foregroundStyle(filled ? .white : .primary)
                .frame(width: filled ? 30 : 26, height: filled ? 30 : 26)
                .background(
                    filled ? Color.accentColor : Color.primary.opacity(0.07),
                    in: RoundedRectangle(cornerRadius: filled ? 8 : 7, style: .continuous)
                )
        }
        .buttonStyle(.plain)
    }

    /// SF Symbol name for a file extension
    private func fileIcon(for ext: String) -> String {
        switch ext {
        case "pdf": return "doc.richtext"
        case "jpg", "jpeg", "png", "heic", "gif", "webp", "tiff": return "photo"
        case "mp4", "mov", "avi", "mkv", "m4v": return "film"
        case "mp3", "aac", "flac", "wav", "m4a": return "music.note"
        case "zip", "rar", "7z", "tar", "gz": return "archivebox"
        case "doc", "docx", "pages": return "doc.text"
        case "xls", "xlsx", "numbers", "csv": return "tablecells"
        case "ppt", "pptx", "key": return "rectangle.on.rectangle"
        case "swift", "py", "js", "ts", "rb", "go", "rs", "kt":
            return "chevron.left.forwardslash.chevron.right"
        default: return "doc"
        }
    }

    // MARK: - Results Content (for smart positioning)
    @ViewBuilder
    private var resultsContentView: some View {
        // Show different content based on current mode (AI vs Normal)
        // The L3 media dock can still surface search results while typing.
        let content = Group {
            if isAIMode {
                // AI mode: AI Chat section (works on L1/L2/L3)
                aiChatSection
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
            } else if showContextInDock && !showMediaLayer
                && (searchContextApp != nil || activeSmartQueryKey != nil)
            {
                appPanelView
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
            } else if showContextInDock && !showMediaLayer
                && shouldShowFinderSearchResultsPanel(for: searchText)
            {
                finderFolderSearchResultsPanel
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
            } else if showContextInDock && !showMediaLayer {
                VStack(spacing: 0) {
                    // Two-column row: chat left + results/filePreview right
                    HStack(spacing: 0) {
                        l2ChatSection
                        if livePanelVisible {
                            switch livePanelMode {
                            case .results, .filePreview:
                                livePanelView
                                    .transition(
                                        .asymmetric(
                                            insertion: .move(edge: .trailing).combined(with: .opacity),
                                            removal: .move(edge: .trailing).combined(with: .opacity)
                                        ))
                            default:
                                EmptyView()
                            }
                        }
                    }
                    .animation(.spring(response: 0.28, dampingFraction: 0.85), value: livePanelVisible)
                    // Terminal drawer below chat (only for .terminal mode)
                    if livePanelVisible, case .terminal = livePanelMode,
                        let term = panelTerminalControllers[activeConsoleKey]
                    {
                        Divider().opacity(0.12)
                        inlineDockTerminalView(term: term)
                    }
                }
                .transition(.opacity.combined(with: .scale(scale: 0.98)))
            } else {
                // Normal mode: Search results (works on L1/L2/L3)
                // L3 stays media-first, but search typing still uses the shared results list.
                indexingProgressSection
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
                resultsSection
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
            }
        }

        if settings.effectiveDockAtBottom {
            // In dock mode, add padding to results (match compact dock height)
            content
                .padding(.horizontal, 12)
                .padding(.bottom, 6)
        } else {
            // In normal mode, add subtle padding at top for smooth connection to dock
            content
                .padding(.top, 4)
        }
    }

    @ViewBuilder
    private var finderFolderSearchResultsPanel: some View {
        let scope = resolveDockScope(for: searchText)
        let folderPath = currentFinderFolderPath()
        let folderName = URL(fileURLWithPath: folderPath).lastPathComponent
        let query = scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)

        VStack(alignment: .leading, spacing: 0) {
            HStack(spacing: 8) {
                Image(systemName: "folder.badge.magnifyingglass")
                    .font(.system(size: 11, weight: .semibold))
                    .foregroundStyle(.secondary)
                Text(folderName.isEmpty ? "Current Folder Search" : folderName)
                    .font(.system(size: 13, weight: .semibold))
                    .lineLimit(1)
                Spacer()
                Text("Names + Content")
                    .font(.system(size: 11, weight: .medium))
                    .foregroundStyle(.secondary)
            }
            .padding(.horizontal, 16)
            .padding(.top, 10)
            .padding(.bottom, 8)

            Divider()
                .padding(.horizontal, 12)

            if isFinderSemanticLoading && searchResults.isEmpty {
                VStack(spacing: 10) {
                    ProgressView()
                    Text("Searching filenames and indexed content in this folder…")
                        .font(.system(size: 13))
                        .foregroundStyle(.secondary)
                        .multilineTextAlignment(.center)
                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 28)
                .padding(.horizontal, 16)
            } else if !query.isEmpty && searchResults.isEmpty {
                VStack(spacing: 10) {
                    Image(systemName: "magnifyingglass")
                        .font(.system(size: 18, weight: .medium))
                        .foregroundStyle(.secondary.opacity(0.8))
                    Text("No matches in this Finder folder.")
                        .font(.system(size: 13, weight: .medium))
                        .foregroundStyle(.primary)
                    Text("Try another name or content phrase.")
                        .font(.system(size: 12))
                        .foregroundStyle(.secondary)
                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 28)
                .padding(.horizontal, 16)
            } else {
                resultsSection
            }
        }
    }

    // MARK: - Separator (for smart positioning)
    @ViewBuilder
    private var separatorView: some View {
        let shouldShowSeparator =
            if showMediaLayer {
                // Show separator on L3 if media is playing
                mediaObserver.isPlaying
            } else if isAIMode {
                // Show separator for AI mode
                hasUserSentMessageInCurrentSession && (!aiChatMessages.isEmpty || isAILoading)
            } else {
                // Show separator for search results
                !searchResults.isEmpty || fileIndexManager.progress.isIndexing
            }

        if shouldShowSeparator {
            Divider()
                .padding(.horizontal, 12)
                .transition(.opacity)
        }
    }

