    @ViewBuilder
    private func livePanelAppCard(ctx: SearchContextApp) -> some View {
        VStack(alignment: .leading, spacing: 0) {
            HStack(spacing: 12) {
                if let icon = ctx.icon {
                    Image(nsImage: icon)
                        .resizable().aspectRatio(contentMode: .fit)
                        .frame(width: 52, height: 52)
                        .shadow(color: .black.opacity(0.2), radius: 4, x: 0, y: 2)
                } else {
                    Image(systemName: "app.fill")
                        .font(.system(size: 40))
                        .foregroundStyle(Color.accentColor)
                }
                VStack(alignment: .leading, spacing: 4) {
                    Text(ctx.name)
                        .font(.system(size: 14, weight: .semibold))
                        .lineLimit(1)
                    if !ctx.appPath.isEmpty {
                        let bundleID = Bundle(path: ctx.appPath)?.bundleIdentifier ?? ""
                        if !bundleID.isEmpty {
                            Text(bundleID)
                                .font(.system(size: 9))
                                .foregroundStyle(.tertiary)
                                .lineLimit(1)
                        }
                        let version =
                            Bundle(path: ctx.appPath)?.infoDictionary?["CFBundleShortVersionString"]
                            as? String ?? ""
                        if !version.isEmpty {
                            Text("Version \(version)")
                                .font(.system(size: 10))
                                .foregroundStyle(.secondary)
                        }
                    }
                }
            }
            .padding(.horizontal, 14)
            .padding(.top, 16)
            .padding(.bottom, 12)

            Divider().padding(.horizontal, 14)
            livePanelActionGrid(ctx: ctx).padding(.bottom, 12)
        }
    }

    @ViewBuilder
    private func livePanelGenericCard(ctx: SearchContextApp) -> some View {
        VStack(spacing: 12) {
            if let icon = ctx.icon {
                Image(nsImage: icon)
                    .resizable().aspectRatio(contentMode: .fit)
                    .frame(width: 48, height: 48)
