    @ViewBuilder
    private var livePanelNowPlayingView: some View {
        VStack(spacing: 0) {
            // Album art placeholder + info
            VStack(spacing: 0) {
                // Large album art area
                ZStack {
                    RoundedRectangle(cornerRadius: 12, style: .continuous)
                        .fill(
                            LinearGradient(
                                colors: [
