                .frame(maxWidth: .infinity)
                .frame(height: 120)
                .padding(.horizontal, 16)
                .padding(.top, 16)

                // Track info
                VStack(spacing: 4) {
                    Text(nowPlayingTitle.isEmpty ? "Nothing Playing" : nowPlayingTitle)
                        .font(.system(size: 13, weight: .semibold))
                        .lineLimit(1)
                        .frame(maxWidth: .infinity, alignment: .center)
                    Text(nowPlayingArtist.isEmpty ? "—" : nowPlayingArtist)
                        .font(.system(size: 11))
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                    if !nowPlayingAlbum.isEmpty {
                        Text(nowPlayingAlbum)
                            .font(.system(size: 10))
                            .foregroundStyle(.tertiary)
                            .lineLimit(1)
                    }
                }
                .padding(.horizontal, 16)
                .padding(.top, 12)
                .padding(.bottom, 8)

                // Now playing source badge
                if let info = miniPlayer.playerInfo {
                    HStack(spacing: 4) {
                        Circle().fill(Color.green).frame(width: 5, height: 5)
                        Text("via \(info.toolName)")
                            .font(.system(size: 9))
                            .foregroundStyle(.secondary)
                    }
                    .padding(.bottom, 4)
                }

                Divider().padding(.horizontal, 16).padding(.vertical, 6)

                // Playback controls
                HStack(spacing: 0) {
                    Spacer()
                    Button {
                        MiniPlayerController.shared.previous()
                    } label: {
                        Image(systemName: "backward.fill")
                            .font(.system(size: 18))
                            .foregroundStyle(.secondary)
                    }
                    .buttonStyle(.plain)
                    Spacer()
                    Button {
                        MiniPlayerController.shared.togglePlayPause()
                    } label: {
                        Image(
                            systemName: nowPlayingIsPlaying
                                ? "pause.circle.fill" : "play.circle.fill"
                        )
                        .font(.system(size: 36))
                        .foregroundStyle(Color.accentColor)
                    }
                    .buttonStyle(.plain)
                    Spacer()
                    Button {
                        MiniPlayerController.shared.next()
                    } label: {
                        Image(systemName: "forward.fill")
                            .font(.system(size: 18))
                            .foregroundStyle(.secondary)
                    }
                    .buttonStyle(.plain)
                    Spacer()
                }
                .padding(.horizontal, 16)
                .padding(.vertical, 10)

                Button {
                    MiniPlayerController.shared.stop()
                } label: {
                    Label("Stop Playback", systemImage: "stop.fill")
                        .font(.system(size: 10))
                        .foregroundStyle(.secondary)
                }
                .buttonStyle(.plain)
                .padding(.bottom, 12)
            }
            .frame(maxWidth: .infinity)

            Spacer()
        }
        .onAppear {
            refreshNowPlaying()
            nowPlayingTimer = Timer.scheduledTimer(withTimeInterval: 3.0, repeats: true) { _ in
                Task { @MainActor in refreshNowPlaying() }
            }
        }
        .onDisappear {
            nowPlayingTimer?.invalidate()
            nowPlayingTimer = nil
        }
    }

    private func refreshNowPlaying() {
        let info = MediaInfoProvider.shared.getNowPlayingInfo()
        nowPlayingTitle = info.title ?? miniPlayer.playerInfo?.currentSong ?? ""
        nowPlayingArtist = info.artist ?? ""
        nowPlayingAlbum = info.album ?? ""
        nowPlayingIsPlaying = info.playbackRate > 0 || (miniPlayer.playerInfo?.isPlaying ?? false)
    }

