// MARK: - Glass Background

/// NSVisualEffectView wrapped in SwiftUI — provides true wallpaper-blur glass effect.
/// Rounded corners are applied at the AppKit layer so they clip the blur itself.
struct GlassBackground: NSViewRepresentable {
    var cornerRadius: CGFloat = 16
    @ObservedObject private var settings = AppSettings.shared

    func makeNSView(context: Context) -> NSVisualEffectView {
        let ve = NSVisualEffectView()
        ve.blendingMode = .behindWindow
        ve.state = .active
        ve.wantsLayer = true
        configure(ve)
        return ve
    }

    func updateNSView(_ ve: NSVisualEffectView, context: Context) {
        ve.blendingMode = .behindWindow
        configure(ve)
    }

    private func configure(_ ve: NSVisualEffectView) {
        ve.layer?.cornerRadius = cornerRadius
        ve.layer?.masksToBounds = true

        let isLight = isLightMode
        switch settings.appearanceMode {
        case "light":
            ve.material = .popover
            ve.appearance = NSAppearance(named: .aqua)
        case "dark":
            ve.material = .popover
            ve.appearance = NSAppearance(named: .darkAqua)
        default:
            ve.material = .popover
            ve.appearance = nil
        }

        // ── Base fill: wallpaper-sampled glass shared by compact dock and expanded sheets.
        ve.layer?.sublayers?.filter { $0.name == "baseFill" }.forEach { $0.removeFromSuperlayer() }
        let base = CALayer()
        base.name = "baseFill"
        base.cornerRadius = cornerRadius
        base.frame = ve.bounds
        base.autoresizingMask = [.layerWidthSizable, .layerHeightSizable]
        if isLight {
            base.backgroundColor = CGColor(red: 0.98, green: 0.98, blue: 0.98, alpha: 0.62)
        } else {
            // Dark: bright enough to stand out from any wallpaper
            base.backgroundColor = CGColor(red: 0.22, green: 0.22, blue: 0.26, alpha: 0.82)
        }
        ve.layer?.insertSublayer(base, at: 0)

        // ── Specular top-edge highlight ──
        ve.layer?.sublayers?.filter { $0.name == "specularHighlight" }.forEach {
            $0.removeFromSuperlayer()
        }
        if ve.bounds.height > 0 {
            let highlight = CAGradientLayer()
            highlight.name = "specularHighlight"
            let alpha: CGFloat = isLight ? 0.70 : 0.45
            highlight.colors = [
                CGColor(red: 1, green: 1, blue: 1, alpha: alpha),
                CGColor(red: 1, green: 1, blue: 1, alpha: 0.0),
            ]
            highlight.startPoint = CGPoint(x: 0.5, y: 1)
            highlight.endPoint = CGPoint(x: 0.5, y: 0)
            highlight.frame = CGRect(
                x: 0, y: ve.bounds.height - 2, width: ve.bounds.width, height: 2)
            highlight.cornerRadius = cornerRadius
            ve.layer?.addSublayer(highlight)
        }

        // ── Border ring ──
        ve.layer?.sublayers?.filter { $0.name == "borderRing" }.forEach {
            $0.removeFromSuperlayer()
        }
        let border = CALayer()
        border.name = "borderRing"
        border.cornerRadius = cornerRadius
        border.frame = ve.bounds
        border.autoresizingMask = [.layerWidthSizable, .layerHeightSizable]
        border.borderColor =
            isLight
            ? CGColor(red: 0, green: 0, blue: 0, alpha: 0.09)
            : CGColor(red: 1, green: 1, blue: 1, alpha: 0.22)
        border.borderWidth = 1.0
        ve.layer?.addSublayer(border)
    }

    private var isLightMode: Bool {
        if settings.appearanceMode == "light" { return true }
        if settings.appearanceMode == "dark" { return false }
        return NSApp.effectiveAppearance.bestMatch(from: [.aqua, .darkAqua]) == .aqua
    }
}

extension View {
    /// Wraps a view in the full glass-pill container: NSVisualEffectView blur + specular border stroke + shadow.
    func glassContainer(cornerRadius: CGFloat = 16) -> some View {
        self
            .background(GlassBackground(cornerRadius: cornerRadius))
            .clipShape(RoundedRectangle(cornerRadius: cornerRadius))
    }
}

// MARK: - View helpers

extension View {
    /// Applies a transform only when an optional value is non-nil.
    @ViewBuilder
    func ifLet<T, V: View>(_ value: T?, transform: (Self, T) -> V) -> some View {
        if let value {
            transform(self, value)
        } else {
            self
        }
    }
}

// MARK: - App launch usage tracker (for ghost-text completion ranking)

final class AppLaunchTracker {
    static let shared = AppLaunchTracker()
    private let key = "appLaunchCounts"

    private var counts: [String: Int] {
        get { UserDefaults.standard.dictionary(forKey: key) as? [String: Int] ?? [:] }
        set { UserDefaults.standard.set(newValue, forKey: key) }
    }

    func record(bundleId: String) {
        var c = counts
        c[bundleId, default: 0] += 1
        counts = c
    }

    func count(for bundleId: String) -> Int {
        counts[bundleId] ?? 0
    }
}

// MARK: - App icon dominant color extraction

extension NSImage {
    /// Returns the dominant (average) color of the image by sampling to 1×1.
    var dominantSwiftUIColor: SwiftUI.Color {
        guard let cgImage = cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            return SwiftUI.Color.accentColor
        }
        let colorSpace = CGColorSpaceCreateDeviceRGB()
        var pixel = [UInt8](repeating: 0, count: 4)
        guard let ctx = CGContext(
            data: &pixel, width: 1, height: 1,
            bitsPerComponent: 8, bytesPerRow: 4,
            space: colorSpace,
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else { return SwiftUI.Color.accentColor }
        ctx.draw(cgImage, in: CGRect(x: 0, y: 0, width: 1, height: 1))
        let r = CGFloat(pixel[0]) / 255
        let g = CGFloat(pixel[1]) / 255
        let b = CGFloat(pixel[2]) / 255
        let nsColor = NSColor(calibratedRed: r, green: g, blue: b, alpha: 1)
            .usingColorSpace(.deviceRGB) ?? NSColor(red: r, green: g, blue: b, alpha: 1)
        var hue: CGFloat = 0, sat: CGFloat = 0, bri: CGFloat = 0, alp: CGFloat = 0
        nsColor.getHue(&hue, saturation: &sat, brightness: &bri, alpha: &alp)
        // Boost saturation so the glow reads as a colour tint, not grey
        let boosted = NSColor(hue: hue, saturation: min(sat * 1.4 + 0.2, 1), brightness: min(bri * 1.1, 1), alpha: 1)
        return SwiftUI.Color(boosted)
    }
}

// MARK: - NSSharingServicePicker dismiss coordinator

/// Lightweight Obj-C object that acts as NSSharingServicePickerDelegate.
/// Calls `onDismiss` after the user picks a service or cancels the picker.
final class SharePickerCoordinator: NSObject, NSSharingServicePickerDelegate {
    static var key = 0  // used as objc_setAssociatedObject key
    private let onDismiss: () -> Void

    init(onDismiss: @escaping () -> Void) {
        self.onDismiss = onDismiss
    }

    func sharingServicePicker(
        _ picker: NSSharingServicePicker,
        didChoose service: NSSharingService?
    ) {
        DispatchQueue.main.async { self.onDismiss() }
    }
}
